export default "xception as e:\\n                failed_imports.append(f\\\"Category {category_name}: {e!s}\\\")\\n                print(f\\\"FAILED: Category {category_name}: {e!s}\\\")  # noqa: T201\\n\\n        print(f\\\"Successfully imported {successful_imports} components\\\")  # noqa: T201\\n\\n        if failed_imports:\\n            print(f\\\"Failed imports ({len(failed_imports)}):\\\")  # noqa: T201\\n            for failure in failed_imports[:10]:  # Show first 10 failures\\n                print(f\\\"  - {failure}\\\")  # noqa: T201\\n            if len(failed_imports) > 10:\\n                print(f\\\"  ... and {len(failed_imports) - 10} more\\\")  # noqa: T201\\n\\n            pytest.fail(f\\\"Failed to import {len(failed_imports)} components\\\")\\n\\n    def test_dynamic_imports_mapping_complete(self):\\n        \\\"\\\"\\\"Test that _dynamic_imports mapping is complete for all categories.\\\"\\\"\\\"\\n        failed_mappings = []\\n\\n        for category_name in components.__all__:\\n            if category_name in UNAVAILABLE_BUNDLE_CATEGORIES:\\n                continue\\n            try:\\n                category_module = getattr(components, category_name)\\n\\n                if hasattr(category_module, \\\"__all__\\\") and hasattr(category_module, \\\"_dynamic_imports\\\"):\\n                    category_all = set(category_module.__all__)\\n                    dynamic_imports_keys = set(category_module._dynamic_imports.keys())\\n\\n                    # Check that all items in __all__ have corresponding _dynamic_imports entries\\n                    missing_in_dynamic = category_all - dynamic_imports_keys\\n                    if missing_in_dynamic:\\n                        failed_mappings.append(f\\\"{category_name}: Missing in _dynamic_imports: {missing_in_dynamic}\\\")\\n\\n                    # Check that all _dynamic_imports keys are in __all__\\n                    missing_in_all = dynamic_imports_keys - category_all\\n                    if missing_in_all:\\n                        failed_mappings.append(f\\\"{category_name}: Missing in __all__: {missing_in_all}\\\")\\n\\n            except Exception as e:\\n                failed_mappings.append(f\\\"{category_name}: Error checking mappings: {e!s}\\\")\\n\\n        if failed_mappings:\\n            pytest.fail(f\\\"Inconsistent mappings: {failed_mappings}\\\")\\n\\n    def test_backward_compatibility_imports(self):\\n        \\\"\\\"\\\"Test that traditional import patterns still work.\\\"\\\"\\\"\\n        # Test some key imports that should always work\\n        traditional_imports = [\\n            (\\\"langflow.components.data\\\", \\\"APIRequestComponent\\\"),\\n            (\\\"langflow.components.models_and_agents\\\", \\\"AgentComponent\\\"),\\n            (\\\"langflow.components.models_and_agents\\\", \\\"LanguageModelComponent\\\"),\\n            (\\\"langflow.components.helpers\\\", \\\"CalculatorComponent\\\"),\\n        ]\\n\\n        failed_imports = []\\n\\n        for module_name, component_name in traditional_imports:\\n            if module_name.rsplit(\\\".\\\", 1)[-1] in UNAVAILABLE_BUNDLE_CATEGORIES:\\n                continue\\n            try:\\n                module = importlib.import_module(module_name)\\n                component = getattr(module, component_name)\\n                assert component is not None\\n                assert callable(component)\\n\\n            except Exception as e:\\n                failed_imports.append(f\\\"{module_name}.{component_name}: {e!s}\\\")\\n\\n        if failed_imports:\\n            pytest.fail(f\\\"Traditional imports failed: {failed_imports}\\\")\\n\\n    def test_component_modules_have_required_attributes(self):\\n        \\\"\\\"\\\"Test that component modules have required attributes for dynamic loading.\\\"\\\"\\\"\\n        failed_modules = []\\n\\n        for category_name in components.__all__:\\n            if category_name in UNAVAILABLE_BUNDLE_CATEGORIES:\\n                continue\\n            try:\\n                category_module = getattr(components, category_name)\\n\\n                # Check for required attributes\\n                required_attrs = [\\\"__all__\\\"]\\n\\n                failed_modules.extend(\\n                    f\\\"{category_name}: Missing required attribute {attr}\\\"\\n                    for attr in required_attrs\\n                    if not hasattr(category_module, attr)\\n                )\\n\\n                # Check that if it has dynamic imports, it has the pattern\\n                if hasattr(category_module, \\\"_dynamic_imports\\\"):\\n                    if not hasattr(category_module, \\\"__getattr__\\\"):\\n                        failed_modules.append(f\\\"{category_name}: Has _dynamic_imports but no __getattr__\\\")\\n                    if not hasattr(category_module, \\\"__dir__\\\"):\\n                        failed_modules.append(f\\\"{category_name}: Has _dynamic_imports but no __dir__\\\")\\n\\n            except Exception as e:\\n                failed_modules.append(f\\\"{category_name}: Error checking attributes: {e!s}\\\")\\n\\n        if failed_modules:\\n            pytest.fail(f\\\"Module attribute issues: {failed_modules}\\\")\\n\\n    def test_no_circular_imports(self):\\n        \\\"\\\"\\\"Test that there are no circular import issues.\\\"\\\"\\\"\\n        # Test importing in different orders to catch circular imports\\n        import_orders = [\\n            [\\\"models_and_agents\\\", \\\"data\\\", \\\"helpers\\\"],\\n            [\\\"helpers\\\", \\\"models_and_agents\\\", \\\"data\\\"],\\n            [\\\"data\\\", \\\"helpers\\\", \\\"models_and_agents\\\"],\\n        ]\\n\\n        for order in import_orders:\\n            try:\\n                for category_name in order:\\n                    if category_name in UNAVAILABLE_BUNDLE_CATEGORIES:\\n                        continue\\n                    category_module = getattr(components, category_name)\\n                    # Access a component to trigger dynamic import\\n                    if hasattr(category_module, \\\"__all__\\\") and category_module.__all__:\\n                        first_component_name = category_module.__all__[0]\\n                        getattr(category_module, first_component_name)\\n\\n            except Exception as e:\\n                pytest.fail(f\\\"Circular import issue with order {order}: {e!s}\\\")\\n\\n    def test_component_access_caching(self):\\n        \\\"\\\"\\\"Test that component access caching works correctly.\\\"\\\"\\\"\\n        # Access the same component multiple times and ensure caching works\\n        test_cases = [\\n            (\\\"data\\\", \\\"APIRequestComponent\\\"),\\n            (\\\"models_and_agents\\\", \\\"LanguageModelComponent\\\"),\\n            (\\\"helpers\\\", \\\"CalculatorComponent\\\"),\\n        ]\\n\\n        for category_name, component_name in test_cases:\\n            if category_name in UNAVAILABLE_BUNDLE_CATEGORIES:\\n                continue\\n            category_module = getattr(components, category_name)\\n\\n            # First access\\n            component1 = getattr(category_module, component_name)\\n\\n            # Component should now be cached in module globals\\n            assert component_name in category_module.__dict__\\n\\n            # Second access should return the same object\\n            component2 = getattr(category_module, component_name)\\n            assert component1 is component2, f\\\"Caching failed for {category_name}.{component_name}\\\"\\n\\n    def test_error_handling_for_missing_components(self):\\n        \\\"\\\"\\\"Test that appropriate errors are raised for missing components.\\\"\\\"\\\"\\n        test_cases = [\\n            (\\\"data\\\", \\\"AnotherNonExistentComponent\\\"),\\n            (\\\"models_and_agents\\\", \\\"NonExistentComponent\\\"),\\n        ]\\n\\n        for category_name, component_name in test_cases:\\n            if category_name in UNAVAILABLE_BUNDLE_CATEGORIES:\\n                continue\\n            category_module = getattr(components, category_name)\\n\\n            with pytest.raises(AttributeError, match=f\\\"has no attribute '{component_name}'\\\"):\\n                getattr(category_module, component_name)\\n\\n    def test_dir_functionality(self):\\n        \\\"\\\"\\\"Test that __dir__ functionality works for all modules.\\\"\\\"\\\"\\n        # Test main components module\\n        main_dir = dir(components)\\n        if \\\"openai\\\" not in UNAVAILABLE_BUNDLE_CATEGORIES:\\n            assert \\\"openai\\\" in main_dir\\n        assert \\\"data\\\" in main_dir\\n        assert \\\"models_and_agents\\\" in main_dir\\n\\n        # Test category modules\\n        for category_name in [\\\"openai\\\", \\\"data\\\", \\\"helpers\\\", \\\"models_and_agents\\\"]:\\n            if category_name in UNAVAILABLE_BUNDLE_CATEGORIES:\\n                continue\\n            category_module = getattr(components, category_name)\\n            category_dir = dir(category_module)\\n\\n            # Should include all components from __all__\\n            if hasattr(category_module, \\\"__all__\\\"):\\n                for component_name in category_module.__all__:\\n                    assert component_name in category_dir, f\\\"{component_name} missing from dir({category_name})\\\"\\n\\n    def test_module_metadata_preservation(self):\\n        \\\"\\\"\\\"Test that module metadata is preserved after dynamic loading.\\\"\\\"\\\"\\n        test_components = [\\n            (\\\"data\\\", \\\"APIRequestComponent\\\"),\\n            (\\\"models_and_agents\\\", \\\"LanguageModelComponent\\\"),\\n        ]\\n\\n        for category_name, component_name in test_components:\\n            if category_name in UNAVAILABLE_BUNDLE_CATEGORIES:\\n                continue\\n            category_module = getattr(components, category_name)\\n            component = getattr(category_module, component_name)\\n\\n            # Check that component has expected metadata\\n            assert hasattr(component, \\\"__name__\\\")\\n            assert hasattr(component, \\\"__module__\\\")\\n            assert component.__name__ == component_name\\n            assert category_name in component.__module__\\n\\n\\nclass TestSpecificModulePatterns:\\n    \\\"\\\"\\\"Test specific module patterns and edge cases.\\\"\\\"\\\"\\n\\n    def test_empty_init_modules(self):\\n        \\\"\\\"\\\"Test modules that might have empty __init__.py files.\\\"\\\"\\\"\\n        # These modules might have empty __init__.py files in the original structure\\n        potentially_empty_modules = [\\n            \\\"chains\\\",\\n            \\\"output_parsers\\\",\\n            \\\"textsplitters\\\",\\n            \\\"toolkits\\\",\\n            \\\"link_extractors\\\",\\n            \\\"documentloaders\\\",\\n        ]\\n\\n        for module_name in potentially_empty_modules:\\n            if module_name in components.__all__:\\n                try:\\n                    module = getattr(components, module_name)\\n                    # Should be able to import even if empty\\n                    assert module is not None\\n                except Exception as e:\\n                    pytest.fail(f\\\"Failed to import potentially empty module {module_name}: {e}\\\")\\n\\n    def test_platform_specific_imports(self):\\n        \\\"\\\"\\\"Test platform-specific imports like NVIDIA Windows components.\\\"\\\"\\\"\\n        if \\\"nvidia\\\" in UNAVAILABLE_BUNDLE_CATEGORIES:\\n            pytest.skip(\\\"NVIDIA moved to the opt-in lfx-bundles distribution\\\")\\n\\n        # Test NVIDIA module which has platform-specific logic\\n        nvidia_module = components.nvidia\\n        assert nvidia_module is not None\\n\\n        # Should have basic components regardless of platform\\n        assert \\\"NVIDIAModelComponent\\\" in nvidia_module.__all__\\n\\n        # Should be able to access components\\n        nvidia_model = nvidia_module.NVIDIAModelComponent\\n        assert nvidia_model is not None\\n\\n    def test_large_modules_import_efficiently(self):\\n        \\\"\\\"\\\"Test that large modules with many components import efficiently.\\\"\\\"\\\"\\n        import time\\n\\n        # Test large modules\\n        large_modules = [\\\"data\\\", \\\"processing\\\", \\\"langchain_utilities\\\"]\\n\\n        for module_name in large_modules:\\n            if module_name in components.__all__:\\n                start_time = time.time()\\n                module = getattr(components, module_name)\\n                import_time = time.time() - start_time\\n\\n                # Initial import should be fast (just loading __init__.py)\\n                assert import_time < 0.5, f\\\"Module {module_name} took too long to import: {import_time}s\\\"\\n\\n                # Should have components available\\n                assert hasattr(module, \\\"__all__\\\")\\n                assert len(module.__all__) > 0\\n\\n\\nclass TestDirectModuleImports:\\n    \\\"\\\"\\\"Test direct module imports to catch actual import errors.\\n\\n    These tests bypass the lazy import system and directly import module files\\n    to catch issues like:\\n    - Deprecated import paths (e.g., langchain.embeddings.base)\\n    - Syntax errors\\n    - Missing imports\\n    - Circular imports\\n    \\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_all_lfx_component_modules_directly_importable(self):\\n        \\\"\\\"\\\"Test that all lfx component modules can be directly imported.\\n\\n        This bypasses the lazy import system to catch actual import errors\\n        like deprecated imports, syntax errors, etc. Uses async for 3-5x\\n        performance improvement.\\n        \\\"\\\"\\\"\\n        try:\\n            import lfx.components as components_pkg\\n        except ImportError:\\n            pytest.skip(\\\"lfx.components not available\\\")\\n\\n        # Collect all module names\\n        module_names = []\\n        for _, modname, _ in pkgutil.walk_packages(components_pkg.__path__, prefix=components_pkg.__name__ + \\\".\\\"):\\n            # Skip deactivated components\\n            if \\\"deactivated\\\" in modname:\\n                continue\\n            category_name = modname.removeprefix(f\\\"{components_pkg.__name__}.\\\").split(\\\".\\\", 1)[0]\\n            if category_name in UNAVAILABLE_BUNDLE_CATEGORIES:\\n                continue\\n            # Skip private modules\\n            if any(part.startswith(\\\"_\\\") for part in modname.split(\\\".\\\")):\\n                continue\\n            module_names.append(modname)\\n\\n        # Define async function to import a single module\\n        async def import_module_async(modname):\\n            \\\"\\\"\\\"Import a module asynchronously.\\\"\\\"\\\"\\n            try:\\n                # Run import in thread pool to avoid blocking\\n                await asyncio.to_thread(importlib.import_module, modname)\\n            except ImportError as e:\\n                error_msg = str(e)\\n                # Check if it's a missing optional dependency (expected)\\n                if any(\\n                    pkg in error_msg\\n                    for pkg in [\\n                        \\\"agentics\\\",\\n                        \\\"agentics-py\\\",\\n                        \\\"crewai\\\",\\n                        \\\"langchain_openai\\\",\\n                        \\\"langchain_anthropic\\\",\\n                        \\\"langchain_google\\\",\\n                        \\\"langchain_cohere\\\",\\n                        \\\"langchain_pinecone\\\",\\n                        \\\"langchain_chroma\\\",\\n                        \\\"qdrant_client\\\",\\n                        \\\"pymongo\\\",\\n                        \\\"cassandra\\\",\\n                        \\\"weaviate\\\",\\n                        \\\"pinecone\\\",\\n                        \\\"chromadb\\\",\\n                        \\\"redis\\\",\\n                        \\\"elasticsearch\\\",\\n                        \\\"langchain_community\\\",\\n                        # ALTK is excluded on Intel macOS; the IBM integrations remain optional.\\n                        \\\"altk\\\",\\n                        \\\"langchain_ibm\\\",\\n                        \\\"ibm_watsonx_ai\\\",\\n                        # Bundle distributions that can be temporarily unpublished;\\n                        # the relocation shim raises with the distribution name.\\n                        \\\"lfx-openai\\\",\\n                        \\\"lfx-datastax\\\",\\n                        \\\"lfx-oracle\\\",\\n                    ]\\n                ):\\n                    return (\\\"skipped\\\", modname, \\\"missing optional dependency\\\")\\n                return (\\\"failed\\\", modname, error_msg)\\n            except Exception as e:\\n                return (\\\"failed\\\", modname, f\\\"{type(e).__name__}: {e}\\\")\\n            else:\\n                return (\\\"success\\\", modname, None)\\n\\n        # Pre-import third-party modules with internal circular imports single-threaded\\n        # before the concurrent fan-out below. This reuses the exact warm-up the\\n        # production loader (``_load_components_dynamically``) runs, so the test and\\n        # production stay in lockstep -- see ``_warm_circular_imports`` for the full\\n        # deadlock explanation.\\n        _warm_circular_imports()\\n\\n        # Import all modules in parallel\\n        results = await asyncio.gather(*[import_module_async(modname) for modname in module_names])\\n\\n        # Process results\\n        failed_imports = []\\n        successful_imports = 0\\n        skipped_modules = []\\n\\n        for status, modname, error in results:\\n            if status == \\\"success\\\":\\n                successful_imports += 1\\n            elif status == \\\"skipped\\\":\\n                skipped_modules.append(f\\\"{modname} ({error})\\\")\\n            else:  # failed\\n                failed_imports.append(f\\\"{modname}: {error}\\\")\\n\\n        if failed_imports:\\n            failure_msg = (\\n                f\\\"Failed to import {len(failed_imports)} component modules. \\\"\\n                f\\\"Successfully imported {successful_imports} modules. \\\"\\n                f\\\"Skipped {len(skipped_modules)} modules.\\\\n\\\\n\\\"\\n                f\\\"Failed imports:\\\\n\\\" + \\\"\\\\n\\\".join(f\\\"  \u2022 {f}\\\" for f in failed_imports) + \\\"\\\\n\\\\n\\\"\\n                \\\"This may indicate deprecated imports, syntax errors, or other issues.\\\"\\n            )\\n            pytest.fail(failure_msg)\\n\\n    def test_no_deprecated_langchain_imports(self):\\n        \\\"\\\"\\\"Test that no component uses deprecated langchain import paths.\\n\\n        This specifically catches issues like the Qdrant bug where\\n        'from langchain.embeddings.base import Embeddings' was used instead of\\n        'from langchain_core.embeddings import Embeddings'.\\n\\n        Uses AST parsing to scan all Python files for deprecated patterns.\\n        \\\"\\\"\\\"\\n        import ast\\n        from pathlib import Path\\n\\n        try:\\n            import lfx\\n\\n            lfx_path = Path(lfx.__file__).parent\\n        except ImportError:\\n            pytest.skip(\\\"lfx package not found\\\")\\n\\n        components_path = lfx_path / \\\"components\\\"\\n        if not components_path.exists():\\n            pytest.skip(\\\"lfx.components directory not found\\\")\\n\\n        deprecated_imports = []\\n\\n        # Known deprecated import patterns\\n        deprecated_patterns = [\\n            (\\\"langchain.embeddings.base\\\", \\\"langchain_core.embeddings\\\"),\\n            (\\\"langchain.llms.base\\\", \\\"langchain_core.language_models.llms\\\"),\\n            (\\\"langchain.chat_models.base\\\", \\\"langchain_core.language_models.chat_models\\\"),\\n            (\\\"langchain.schema\\\", \\\"langchain_core.messages\\\"),\\n            (\\\"langchain.vectorstores\\\", \\\"langchain_community.vectorstores\\\"),\\n            (\\\"langchain.document_loaders\\\", \\\"langchain_community.document_loaders\\\"),\\n            (\\\"langchain.text_splitter\\\", \\\"langchain_text_splitters\\\"),\\n        ]\\n\\n        # Walk through all Python files in components\\n        for py_file in components_path.rglob(\\\"*.py\\\"):\\n            if py_file.name.startswith(\\\"_\\\"):\\n                continue\\n\\n            try:\\n                content = py_file.read_text(encoding=\\\"utf-8\\\")\\n                tree = ast.parse(content, filename=str(py_file))\\n\\n                for node in ast.walk(tree):\\n                    if isinstance(node, ast.ImportFrom):\\n                        module = node.module or \\\"\\\"\\n\\n                        # Check against deprecated patterns\\n                        for deprecated, replacement in deprecated_patterns:\\n                            if module.startswith(deprecated):\\n                                relative_path = py_file.relative_to(lfx_path)\\n                                deprecated_imports.append(\\n                                    f\\\"{relative_path}:{node.lineno}: \\\"\\n                                    f\\\"Uses deprecated '{deprecated}' - should use '{replacement}'\\\"\\n                                )\\n\\n            except Exception:  # noqa: S112\\n                # Skip files that can't be parsed\\n                continue\\n\\n        if deprecated_imports:\\n            failure_msg = (\\n                f\\\"Found {len(deprecated_imports)} deprecated langchain imports.\\\\n\\\\n\\\"\\n                f\\\"Deprecated imports:\\\\n\\\" + \\\"\\\\n\\\".join(f\\\"  \u2022 {imp}\\\" for imp in deprecated_imports) + \\\"\\\\n\\\\n\\\"\\n                \\\"Please update to use current import paths.\\\"\\n            )\\n            pytest.fail(failure_msg)\\n\\n    @pytest.mark.asyncio\\n    async def test_vector_store_components_directly_importable(self):\\n        \\\"\\\"\\\"Test that all vector store components can be directly imported.\\n\\n        Vector stores are particularly prone to import issues due to their\\n        many optional dependencies. This test ensures they can be imported\\n        when dependencies are available.\\n        \\\"\\\"\\\"\\n        vector_store_components = [\\n            (\\\"lfx.components.chroma\\\", \\\"ChromaVectorStoreComponent\\\"),\\n            (\\\"lfx.components.pinecone\\\", \\\"PineconeVectorStoreComponent\\\"),\\n            (\\\"lfx.components.qdrant\\\", \\\"QdrantVectorStoreComponent\\\"),\\n            (\\\"lfx.components.weaviate\\\", \\\"WeaviateVectorStoreComponent\\\"),\\n            (\\\"lfx.components.vectorstores\\\", \\\"LocalDBComponent\\\"),\\n        ]\\n\\n        async def test_vector_store_import(module_name, class_name):\\n            \\\"\\\"\\\"Test import of a single vector store component.\\\"\\\"\\\"\\n            category_name = module_name.split(\\\".\\\")[2]\\n            if category_name in UNAVAILABLE_BUNDLE_CATEGORIES:\\n                return (\\\"skipped\\\", module_name, class_name, \\\"optional bundle not installed\\\")\\n\\n            try:\\n\\n                def _import():\\n                    module = importlib.import_module(module_name)\\n                    component_class = getattr(module, class_name)\\n                    assert isinstance(component_class, type)\\n\\n                await asyncio.to_thread(_import)\\n            except (ImportError, AttributeError) as e:\\n                error_msg = str(e)\\n                # Check if it's a missing optional dependency\\n                if any(\\n                    pkg in error_msg\\n                    for pkg in [\\n                        \\\"langchain_chroma\\\",\\n                        \\\"langchain_pinecone\\\",\\n                        \\\"qdrant_client\\\",\\n                        \\\"weaviate\\\",\\n                        \\\"chromadb\\\",\\n                        \\\"pinecone\\\",\\n                        \\\"langchain_community\\\",\\n                    ]\\n                ):\\n                    return (\\\"skipped\\\", module_name, class_name, \\\"missing optional dependency\\\")\\n                return (\\\"failed\\\", module_name, class_name, error_msg)\\n            else:\\n                return (\\\"success\\\", module_name, class_name, None)\\n\\n        # Test all vector stores in parallel\\n        results = await asyncio.gather(*[test_vector_store_import(mod, cls) for mod, cls in vector_store_components])\\n\\n        # Process results\\n        failed_imports = []\\n\\n        for status, module_name, class_name, error in results:\\n            if status == \\\"failed\\\":\\n                failed_imports.append(f\\\"{module_name}.{class_name}: {error}\\\")\\n\\n        if failed_imports:\\n            failure_msg = (\\n                f\\\"Failed to import {len(failed_imports)} vector store components.\\\\n\\\\n\\\"\\n                f\\\"Failed imports:\\\\n\\\" + \\\"\\\\n\\\".join(f\\\"  \u2022 {f}\\\" for f in failed_imports)\\n            )\\n            pytest.fail(failure_msg)\\n\\n    def test_qdrant_component_directly_importable(self):\\n        \\\"\\\"\\\"Regression test for Qdrant component import (deprecated import fix).\\n\\n        This test specifically validates that the Qdrant component can be\\n        imported after fixing the deprecated langchain.embeddings.base import.\\n        \\\"\\\"\\\"\\n        if \\\"qdrant\\\" in UNAVAILABLE_BUNDLE_CATEGORIES:\\n            pytest.skip(\\\"Qdrant moved to the opt-in lfx-bundles distribution\\\")\\n\\n        try:\\n            from lfx.components.qdrant import QdrantVectorStoreComponent\\n\\n            # Verify it's a class\\n            assert isinstance(QdrantVectorStoreComponent, type)\\n\\n            # Verify it has expected attributes\\n            assert hasattr(QdrantVectorStoreComponent, \\\"display_name\\\")\\n            assert QdrantVectorStoreComponent.display_name == \\\"Qdrant\\\"\\n\\n        except ImportError as e:\\n            if \\\"qdrant_client\\\" in str(e) or \\\"langchain_qdrant\\\" in str(e):\\n                pytest.skip(\\\"Qdrant dependencies not installed (expected in test environment)\\\")\\n            pytest.fail(f\\\"Failed to import QdrantVectorStoreComponent: {e}\\\")\\n        except AttributeError as e:\\n            if \\\"Could not import\\\" in str(e):\\n                pytest.skip(\\\"Qdrant dependencies not installed (expected in test environment)\\\")\\n            raise\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    pytest.main([__file__, \\\"-v\\\"])\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/test_bundle_ssrf_wiring.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a8f73f17252843c8d3b19f6aee3656c94d615a2d52dcd0ec4a82b20f1324ee1a\",\"content\":\"\\\"\\\"\\\"Bundle-free SSRF wiring conformance for ``lfx-bundles`` provider components.\\n\\nThe behavioural SSRF tests for these components must instantiate the component, which needs\\n``lfx-bundles`` installed -- and since #13869 made that metapackage opt-in, they skip in every\\ndefault install. Security regressions that cannot fail are not coverage, so the wiring invariant\\nis asserted here instead, statically: the provider sources live in the repo even when the\\ndistribution is not installed, so this module reads and parses them rather than importing them.\\n\\nPrecedent for static analysis of ``lfx_bundles`` sources: ``test_bundle_shims.py`` and\\n``lfx/tests/unit/extension/migration/test_migration_table_completeness.py``.\\n\\nWhat this pins, per guarded module:\\n\\n* the SSRF guard is imported from ``lfx.utils.ssrf_httpx`` / ``lfx.utils.ssrf_protection``;\\n* every imported guard is actually *called*, not merely imported (an unused import silences\\n  linters while leaving the request unguarded);\\n* no raw network sink (``httpx.get`` / ``httpx.Client`` / ...) appears in the module, which is\\n  how an unguarded request would have to be issued.\\n\\nWhat it deliberately does not pin: ordering (guard strictly before the request) and the runtime\\nblock itself. Those need a live component, and are covered by the behavioural tests that ship\\nwith the bundle in ``src/bundles/lfx-bundles/tests/``. The two layers are complementary -- this\\none runs on every PR, that one runs when the bundle is installed.\\n\\nAdding a provider component that fetches a tenant-controlled URL means adding it to\\n``GUARDED_MODULES``.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport ast\\nfrom pathlib import Path\\n\\nimport pytest\\n\\n# Guard helpers that count as SSRF-protecting a request.\\nGUARD_MODULES = (\\\"lfx.utils.ssrf_httpx\\\", \\\"lfx.utils.ssrf_protection\\\")\\n\\n# Raw network sinks. A guarded module routes through the helpers above instead, so any direct\\n# use here is either an unguarded request or a guard that was refactored away.\\nRAW_SINKS = frozenset({\\\"get\\\", \\\"post\\\", \\\"put\\\", \\\"patch\\\", \\\"delete\\\", \\\"request\\\", \\\"stream\\\", \\\"Client\\\", \\\"AsyncClient\\\"})\\n\\n# module path (relative to the lfx_bundles package) -> guards it must import *and* call.\\n# Mirrors the behavioural coverage that skips without the bundle installed.\\nGUARDED_MODULES: dict[str, set[str]] = {\\n    \\\"deepseek/deepseek.py\\\": {\\\"ssrf_safe_httpx_get\\\", \\\"ssrf_protected_openai_clients_for_url\\\"},\\n    \\\"glean/glean_search_api.py\\\": {\\\"ssrf_safe_httpx_post\\\"},\\n    \\\"git/git.py\\\": {\\\"validate_git_repository_url\\\"},\\n    \\\"git/gitextractor.py\\\": {\\\"validate_git_repository_url\\\"},\\n    \\\"homeassistant/home_assistant_control.py\\\": {\\\"ssrf_safe_httpx_post\\\"},\\n    \\\"homeassistant/list_home_assistant_states.py\\\": {\\\"ssrf_safe_httpx_get\\\"},\\n    \\\"huggingface/huggingface_inference_api.py\\\": {\\\"ssrf_safe_httpx_get\\\", \\\"validate_url_for_ssrf_or_raise\\\"},\\n    \\\"litellm/litellm_proxy.py\\\": {\\\"ssrf_safe_httpx_get\\\", \\\"ssrf_protected_openai_clients_for_url\\\"},\\n    \\\"lmstudio/lmstudioembeddings.py\\\": {\\\"ssrf_safe_async_get\\\", \\\"validate_url_for_ssrf_or_raise\\\"},\\n    \\\"lmstudio/lmstudiomodel.py\\\": {\\\"ssrf_safe_async_get\\\", \\\"ssrf_protected_openai_clients_for_url\\\"},\\n    \\\"xai/xai.py\\\": {\\\"ssrf_safe_httpx_get\\\", \\\"ssrf_protected_openai_clients_for_url\\\"},\\n}\\n\\n\\ndef _bundles_root() -> Path:\\n    \\\"\\\"\\\"Locate ``src/bundles/lfx-bundles/src/lfx_bundles`` by walking up from this file.\\\"\\\"\\\"\\n    for parent in Path(__file__).resolve().parents:\\n        candidate = parent / \\\"src\\\" / \\\"bundles\\\" / \\\"lfx-bundles\\\" / \\\"src\\\" / \\\"lfx_bundles\\\"\\n        if candidate.is_dir():\\n            return candidate\\n    msg = \\\"lfx_bundles source root not found -- run from a repo checkout\\\"\\n    raise AssertionError(msg)\\n\\n\\nBUNDLES_ROOT = _bundles_root()\\n\\n\\ndef _parse(rel_path: str) -> ast.Module:\\n    path = BUNDLES_ROOT / rel_path\\n    assert path.is_file(), (\\n        f\\\"{rel_path} not found under {BUNDLES_ROOT}. If the component moved or was renamed, \\\"\\n        \\\"update GUARDED_MODULES -- do not delete the entry, or the SSRF guard loses its regression net.\\\"\\n    )\\n    return ast.parse(path.read_text(encoding=\\\"utf-8\\\"), filename=str(path))\\n\\n\\ndef _imported_guards(tree: ast.Module) -> set[str]:\\n    return {\\n        alias.name\\n        for node in ast.walk(tree)\\n        if isinstance(node, ast.ImportFrom) and node.module in GUARD_MODULES\\n        for alias in node.names\\n    }\\n\\n\\ndef _called_names(tree: ast.Module) -> set[str]:\\n    \\\"\\\"\\\"Bare names invoked as calls, e.g. ``ssrf_safe_httpx_get(...)``.\\\"\\\"\\\"\\n    return {node.func.id for node in ast.walk(tree) if isinstance(node, ast.Call) and isinstance(node.func, ast.Name)}\\n\\n\\ndef _raw_sink_calls(tree: ast.Module) -> list[str]:\\n    \\\"\\\"\\\"``httpx.<sink>(...)`` style calls -- the shape an unguarded request would take.\\\"\\\"\\\"\\n    found = []\\n    for node in ast.walk(tree):\\n        if not isinstance(node, ast.Call):\\n            continue\\n        func = node.func\\n        if (\\n            isinstance(func, ast.Attribute)\\n            and func.attr in RAW_SINKS\\n            and isinstance(func.value, ast.Name)\\n            and func.value.id == \\\"httpx\\\"\\n        ):\\n            found.append(f\\\"httpx.{func.attr} (line {node.lineno})\\\")\\n    return found\\n\\n\\n@pytest.mark.parametrize(\\\"rel_path\\\", sorted(GUARDED_MODULES))\\ndef test_guard_is_imported(rel_path: str) -> None:\\n    \\\"\\\"\\\"The module imports the SSRF guard its requests are supposed to route through.\\\"\\\"\\\"\\n    imported = _imported_guards(_parse(rel_path))\\n    missing = GUARDED_MODULES[rel_path] - imported\\n    assert not missing, (\\n        f\\\"{rel_path} no longer imports {sorted(missing)} from {GUARD_MODULES}. \\\"\\n        \\\"A tenant-controlled URL reaching the network without this guard is an SSRF regression.\\\"\\n    )\\n\\n\\n@pytest.mark.parametrize(\\\"rel_path\\\", sorted(GUARDED_MODULES))\\ndef test_guard_is_called(rel_path: str) -> None:\\n    \\\"\\\"\\\"Importing the guard is not enough -- it has to be invoked.\\\"\\\"\\\"\\n    tree = _parse(rel_path)\\n    called = _called_names(tree)\\n    expected = GUARDED_MODULES[rel_path] & _imported_guards(tree)\\n    never_called = expected - called\\n    assert not never_called, (\\n        f\\\"{rel_path} imports {sorted(never_called)} but never calls it. \\\"\\n        \\\"An unused guard import passes linting while leaving the request unprotected.\\\"\\n    )\\n\\n\\n@pytest.mark.parametrize(\\\"rel_path\\\", sorted(GUARDED_MODULES))\\ndef test_no_raw_network_sink(rel_path: str) -> None:\\n    \\\"\\\"\\\"No direct ``httpx.*`` call -- guarded modules go through the ssrf_* helpers.\\\"\\\"\\\"\\n    sinks = _raw_sink_calls(_parse(rel_path))\\n    assert not sinks, (\\n        f\\\"{rel_path} calls {sinks} directly instead of the SSRF-safe helper. \\\"\\n        \\\"Route it through lfx.utils.ssrf_httpx so a tenant-supplied host is validated first.\\\"\\n    )\\n\\n\\ndef test_registry_covers_every_declared_guard_user() -> None:\\n    \\\"\\\"\\\"Any bundle module importing a ``ssrf_safe_*`` helper must be in GUARDED_MODULES.\\n\\n    Without this, a new provider can fetch a tenant-controlled URL and silently sit outside the\\n    conformance net -- the registry would still be green because it never heard of the module.\\n    \\\"\\\"\\\"\\n    users = {\\n        str(path.relative_to(BUNDLES_ROOT))\\n        for path in BUNDLES_ROOT.rglob(\\\"*.py\\\")\\n        if \\\"ssrf_safe_\\\" in path.read_text(encoding=\\\"utf-8\\\")\\n    }\\n    unregistered = users - set(GUARDED_MODULES)\\n    assert not unregistered, (\\n        f\\\"these bundle modules use an SSRF-safe helper but are not in GUARDED_MODULES: {sorted(unregistered)}. \\\"\\n        \\\"Add them so the guard cannot be removed unnoticed.\\\"\\n    )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/test_ssrf_guarded_ollama_components.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"304edd69ba5fba076c580d934e63653d2d3802c510e3eed6fbac359aa4a3553a\",\"content\":\"\\\"\\\"\\\"SSRF guard regressions for the Ollama components.\\n\\nThese live apart from ``test_ssrf_guarded_url_components.py`` because Ollama graduated out of\\nthe ``lfx-bundles`` metapackage into ``lfx-ollama``, which *is* a default ``langflow`` dependency.\\nThat file's module-level ``pytest.importorskip(\\\"lfx_bundles\\\")`` would skip these in the default\\ninstall even though the components are present -- so they guard on ``lfx_ollama`` instead.\\n\\nThey also stay out of ``test_chatollama_component.py`` / ``test_ollama_embeddings_component.py``:\\nboth of those classes carry an autouse ``disable_ssrf_protection`` fixture, which is exactly the\\nprotection under test here.\\n\\\"\\\"\\\"\\n\\nimport sys\\nfrom unittest.mock import patch\\n\\nimport pytest\\n\\npytest.importorskip(\\\"lfx_ollama\\\")\\n\\nfrom lfx.components.ollama.ollama import ChatOllamaComponent\\nfrom lfx.components.ollama.ollama_embeddings import OllamaEmbeddingsComponent\\n\\nBLOCKED_URL = \\\"http://169.254.169.254/latest/meta-data\\\"\\n\\n\\n@pytest.fixture(autouse=True)\\ndef enable_ssrf_protection(monkeypatch):\\n    monkeypatch.setenv(\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\", \\\"true\\\")\\n    monkeypatch.delenv(\\\"LANGFLOW_SSRF_ALLOWED_HOSTS\\\", raising=False)\\n\\n\\n# ``ollama.py`` / ``ollama_embeddings.py`` are reachable under several module identities (the\\n# ``lfx.components.ollama.*`` shim, the canonical ``lfx_ollama.components.ollama.*``, and the\\n# runtime ``_lfx_ext.*`` ext-loader copy). Patch on the module the imported class actually lives\\n# in -- a fixed string target misses when an earlier test in the suite resolves it elsewhere.\\n_OLLAMA_MODULE = sys.modules[ChatOllamaComponent.__module__]\\n_OLLAMA_EMBEDDINGS_MODULE = sys.modules[OllamaEmbeddingsComponent.__module__]\\n\\n\\ndef test_ollama_embeddings_build_blocks_metadata_url_before_sdk_client():\\n    component = OllamaEmbeddingsComponent(base_url=BLOCKED_URL, model_name=\\\"model\\\")\\n\\n    with (\\n        patch.object(_OLLAMA_EMBEDDINGS_MODULE, \\\"OllamaEmbeddings\\\") as mock_embeddings,\\n        pytest.raises(ValueError, match=\\\"SSRF Protection\\\"),\\n    ):\\n        component.build_embeddings()\\n\\n    mock_embeddings.assert_not_called()\\n\\n\\ndef test_ollama_build_blocks_metadata_url_before_sdk_client():\\n    component = ChatOllamaComponent(base_url=BLOCKED_URL, model_name=\\\"model\\\", mirostat=\\\"Disabled\\\")\\n\\n    with (\\n        patch.object(_OLLAMA_MODULE, \\\"ChatOllama\\\") as mock_chat_ollama,\\n        pytest.raises(ValueError, match=\\\"SSRF Protection\\\"),\\n    ):\\n        component.build_model()\\n\\n    mock_chat_ollama.assert_not_called()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/tools/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/tools/test_calculator.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b289fe8f458a1a9e7e12253716d1650952e99e5e7baa262d5cde8e17a0723a6e\",\"content\":\"import pytest\\nfrom lfx.components.helpers.calculator_core import CalculatorComponent\\n\\nfrom tests.base import ComponentTestBaseWithoutClient\\n\\n\\nclass TestCalculatorComponent(ComponentTestBaseWithoutClient):\\n    @pytest.fixture\\n    def component_class(self):\\n        return CalculatorComponent\\n\\n    @pytest.fixture\\n    def default_kwargs(self):\\n        return {\\\"expression\\\": \\\"2 + 2\\\", \\\"_session_id\\\": \\\"test_session\\\"}\\n\\n    @pytest.fixture\\n    def file_names_mapping(self):\\n        return []\\n\\n    def test_basic_calculation(self, component_class, default_kwargs):\\n        # Arrange\\n        component = component_class(**default_kwargs)\\n\\n        # Act\\n        result = component.evaluate_expression()\\n\\n        # Assert\\n        assert result.data[\\\"result\\\"] == \\\"4\\\"\\n\\n    def test_complex_calculation(self, component_class):\\n        # Arrange\\n        component = component_class(expression=\\\"4*4*(33/22)+12-20\\\", _session_id=\\\"test_session\\\")\\n\\n        # Act\\n        result = component.evaluate_expression()\\n\\n        # Assert\\n        assert float(result.data[\\\"result\\\"]) == pytest.approx(16)\\n\\n    def test_division_by_zero(self, component_class):\\n        # Arrange\\n        component = component_class(expression=\\\"1/0\\\", _session_id=\\\"test_session\\\")\\n\\n        # Act\\n        result = component.evaluate_expression()\\n\\n        # Assert\\n        assert \\\"error\\\" in result.data\\n        assert result.data[\\\"error\\\"] == \\\"Error: Division by zero\\\"\\n\\n    def test_invalid_expression(self, component_class):\\n        # Arrange\\n        component = component_class(expression=\\\"2 + *\\\", _session_id=\\\"test_session\\\")\\n\\n        # Act\\n        result = component.evaluate_expression()\\n\\n        # Assert\\n        assert \\\"error\\\" in result.data\\n        assert \\\"Invalid expression\\\" in result.data[\\\"error\\\"]\\n\\n    def test_unsupported_operation(self, component_class):\\n        # Arrange\\n        component = component_class(expression=\\\"sqrt(16)\\\", _session_id=\\\"test_session\\\")\\n\\n        # Act\\n        result = component.evaluate_expression()\\n\\n        # Assert\\n        assert \\\"error\\\" in result.data\\n        assert \\\"Unsupported operation\\\" in result.data[\\\"error\\\"]\\n\\n    def test_component_frontend_node(self, component_class, default_kwargs):\\n        # Arrange\\n        component = component_class(**default_kwargs)\\n\\n        # Act\\n        frontend_node = component.to_frontend_node()\\n\\n        # Assert\\n        node_data = frontend_node[\\\"data\\\"][\\\"node\\\"]\\n        assert node_data[\\\"display_name\\\"] == \\\"Calculator\\\"\\n        assert node_data[\\\"description\\\"] == \\\"Perform basic arithmetic operations on a given expression.\\\"\\n        assert node_data[\\\"icon\\\"] == \\\"calculator\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/tools/test_python_repl_tool.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d95151c13a33ef7b8ccf0010fbd57ccd2e95d3d678a80d98ede254b92be689f5\",\"content\":\"import pytest\\nfrom langchain_core.tools import ToolException\\nfrom lfx.components.tools.python_repl import PythonREPLToolComponent\\nfrom lfx.components.utilities.python_repl_core import PythonREPLComponent\\nfrom lfx.graph import Graph\\n\\nfrom tests.base import DID_NOT_EXIST, ComponentTestBaseWithoutClient\\n\\nDYNAMIC_FORMAT_TRAVERSAL_CODE = \\\"\\\"\\\"\\nparts = [\\\"__loader__\\\", \\\"find_spec\\\", \\\"__globals__\\\"]\\nfield = \\\"{0.\\\" + parts[0] + \\\".\\\" + parts[1] + \\\".\\\" + parts[2] + \\\"[sys].modules[os].environ}\\\"\\nprint(\\\"canary_present=\\\" + str(\\\"PVR0800453_CANARY\\\" in field.format(math)))\\n\\\"\\\"\\\"\\n\\n# Sibling formatter sinks: the same __globals__ traversal lives in a *string* argument\\n# (invisible to the AST attribute check) when fed through string.Formatter primitives or\\n# operator.attrgetter. Each leaks os.environ unless the validator rejects the call.\\nFORMATTER_VFORMAT_TRAVERSAL_CODE = \\\"\\\"\\\"\\nf = lambda: 0\\nleaked = string.Formatter().vformat(\\\"{0.__globals__[os].environ[PVR0800453_CANARY]}\\\", (f,), {})\\nprint(\\\"leaked=\\\" + str(leaked))\\n\\\"\\\"\\\"\\n\\nFORMATTER_GET_FIELD_TRAVERSAL_CODE = \\\"\\\"\\\"\\nf = lambda: 0\\nobj, _ = string.Formatter().get_field(\\\"0.__globals__[os].environ[PVR0800453_CANARY]\\\", (f,), {})\\nprint(\\\"leaked=\\\" + str(obj))\\n\\\"\\\"\\\"\\n\\nATTRGETTER_TRAVERSAL_CODE = \\\"\\\"\\\"\\nf = lambda: 0\\nleaked = operator.attrgetter(\\\"__globals__\\\")(f)[\\\"os\\\"].environ[\\\"PVR0800453_CANARY\\\"]\\nprint(\\\"leaked=\\\" + str(leaked))\\n\\\"\\\"\\\"\\n\\n\\nclass TestPythonREPLComponent(ComponentTestBaseWithoutClient):\\n    @pytest.fixture\\n    def component_class(self):\\n        return PythonREPLComponent\\n\\n    @pytest.fixture\\n    def default_kwargs(self):\\n        return {\\n            \\\"global_imports\\\": \\\"math\\\",\\n            \\\"python_code\\\": \\\"print('Hello, World!')\\\",\\n        }\\n\\n    @pytest.fixture\\n    def file_names_mapping(self):\\n        # Component not yet released, mark all versions as non-existent\\n        return [\\n            {\\\"version\\\": \\\"1.0.17\\\", \\\"module\\\": \\\"tools\\\", \\\"file_name\\\": DID_NOT_EXIST},\\n            {\\\"version\\\": \\\"1.0.18\\\", \\\"module\\\": \\\"tools\\\", \\\"file_name\\\": DID_NOT_EXIST},\\n            {\\\"version\\\": \\\"1.0.19\\\", \\\"module\\\": \\\"tools\\\", \\\"file_name\\\": DID_NOT_EXIST},\\n            {\\\"version\\\": \\\"1.1.0\\\", \\\"module\\\": \\\"tools\\\", \\\"file_name\\\": DID_NOT_EXIST},\\n            {\\\"version\\\": \\\"1.1.1\\\", \\\"module\\\": \\\"tools\\\", \\\"file_name\\\": DID_NOT_EXIST},\\n        ]\\n\\n    def test_component_initialization(self, component_class, default_kwargs):\\n        component = component_class(**default_kwargs)\\n        frontend_node = component.to_frontend_node()\\n        node_data = frontend_node[\\\"data\\\"][\\\"node\\\"]\\n\\n        # Test template fields\\n        template = node_data[\\\"template\\\"]\\n        assert \\\"global_imports\\\" in template\\n        assert \\\"python_code\\\" in template\\n\\n        # Test global_imports configuration\\n        global_imports = template[\\\"global_imports\\\"]\\n        assert global_imports[\\\"type\\\"] == \\\"str\\\"\\n        assert global_imports[\\\"value\\\"] == \\\"math\\\"\\n        assert global_imports[\\\"required\\\"] is True\\n\\n        # Test python_code configuration\\n        python_code = template[\\\"python_code\\\"]\\n        # assert python_code[\\\"type\\\"] == \\\"code\\\"  # TODO: Restore when CodeInput is included in component\\n        assert python_code[\\\"type\\\"] == \\\"str\\\"  # TODO: Remove when CodeInput is included in component\\n        assert python_code[\\\"value\\\"] == \\\"print('Hello, World!')\\\"\\n        assert python_code[\\\"required\\\"] is True\\n\\n        # Test base configuration - JSON is the new name (Data is alias for backward compatibility)\\n        assert \\\"JSON\\\" in node_data[\\\"base_classes\\\"]\\n\\n\\nclass TestPythonREPLComponentSecurity:\\n    \\\"\\\"\\\"Regression tests for the __builtins__ sandbox-bypass RCE in the Python Interpreter.\\n\\n    The Global Imports allow-list must not be silently bypassable: dangerous builtins\\n    (__import__, open, eval, ...) and the builtin-free escape gadgets must be blocked,\\n    while ordinary code keeps working.\\n    \\\"\\\"\\\"\\n\\n    def _run(self, code, global_imports=\\\"math\\\"):\\n        return PythonREPLComponent(global_imports=global_imports, python_code=code).run_python_repl().data\\n\\n    def test_legitimate_code_still_runs(self):\\n        \\\"\\\"\\\"The default example (and print()) must keep working after restricting builtins.\\\"\\\"\\\"\\n        assert self._run(\\\"print('Hello, World!')\\\").get(\\\"result\\\") == \\\"Hello, World!\\\"\\n\\n    def test_whitelisted_module_works(self):\\n        \\\"\\\"\\\"A module from Global Imports remains usable.\\\"\\\"\\\"\\n        assert \\\"4.0\\\" in self._run(\\\"print(math.sqrt(16))\\\").get(\\\"result\\\", \\\"\\\")\\n\\n    def test_import_builtin_is_blocked(self):\\n        \\\"\\\"\\\"__import__ is not in the restricted builtins, so the headline RCE payload fails.\\\"\\\"\\\"\\n        rendered = str(self._run('print(__import__(\\\"subprocess\\\").check_output([\\\"echo\\\", \\\"PWNED\\\"]))'))\\n        assert \\\"PWNED\\\" not in rendered\\n        assert \\\"NameError\\\" in rendered\\n\\n    def test_open_builtin_is_blocked(self):\\n        \\\"\\\"\\\"Filesystem access via open() is blocked.\\\"\\\"\\\"\\n        rendered = str(self._run('print(open(\\\"/etc/passwd\\\").read())'))\\n        assert \\\"root:\\\" not in rendered\\n        assert \\\"NameError\\\" in rendered\\n\\n    def test_eval_builtin_is_blocked(self):\\n        \\\"\\\"\\\"eval() is not exposed.\\\"\\\"\\\"\\n        assert \\\"NameError\\\" in str(self._run('print(eval(\\\"1+1\\\"))'))\\n\\n    def test_subclasses_escape_is_blocked(self):\\n        \\\"\\\"\\\"The classic builtin-free escape gadget is rejected before execution.\\\"\\\"\\\"\\n        data = self._run(\\\"print(().__class__.__bases__[0].__subclasses__())\\\")\\n        assert \\\"error\\\" in data\\n        assert \\\"not allowed\\\" in data[\\\"error\\\"]\\n\\n    def test_inline_import_is_blocked(self):\\n        \\\"\\\"\\\"Inline imports are rejected; modules must come from the Global Imports field.\\\"\\\"\\\"\\n        data = self._run(\\\"import os\\\\nprint(os.getcwd())\\\")\\n        assert \\\"error\\\" in data\\n        assert \\\"not allowed\\\" in data[\\\"error\\\"]\\n\\n    def test_format_string_dunder_escape_is_blocked(self):\\n        \\\"\\\"\\\"str.format() dunder traversal (invisible to the AST attr check) is rejected.\\\"\\\"\\\"\\n        data = self._run('f = lambda: 0\\\\nprint(\\\"{0.__globals__}\\\".format(f))')\\n        assert \\\"error\\\" in data\\n        assert \\\"not allowed\\\" in data[\\\"error\\\"]\\n\\n    def test_dynamic_format_string_traversal_is_blocked(self, monkeypatch):\\n        \\\"\\\"\\\"Dynamically-built str.format() fields cannot bypass the AST validator.\\\"\\\"\\\"\\n        monkeypatch.setenv(\\\"PVR0800453_CANARY\\\", \\\"SHOULD_NOT_LEAK\\\")\\n        data = self._run(DYNAMIC_FORMAT_TRAVERSAL_CODE)\\n        assert \\\"error\\\" in data\\n        assert \\\"not allowed\\\" in data[\\\"error\\\"]\\n        assert \\\"SHOULD_NOT_LEAK\\\" not in str(data)\\n\\n    def test_formatter_vformat_traversal_is_blocked(self, monkeypatch):\\n        \\\"\\\"\\\"string.Formatter().vformat carries the dunder chain in a string arg; blocked.\\\"\\\"\\\"\\n        monkeypatch.setenv(\\\"PVR0800453_CANARY\\\", \\\"SHOULD_NOT_LEAK\\\")\\n        data = self._run(FORMATTER_VFORMAT_TRAVERSAL_CODE, global_imports=\\\"math,string\\\")\\n        assert \\\"error\\\" in data\\n        assert \\\"not allowed\\\" in data[\\\"error\\\"]\\n        assert \\\"SHOULD_NOT_LEAK\\\" not in str(data)\\n\\n    def test_formatter_get_field_traversal_is_blocked(self, monkeypatch):\\n        \\\"\\\"\\\"string.Formatter().get_field traverses a dotted string path; blocked.\\\"\\\"\\\"\\n        monkeypatch.setenv(\\\"PVR0800453_CANARY\\\", \\\"SHOULD_NOT_LEAK\\\")\\n        data = self._run(FORMATTER_GET_FIELD_TRAVERSAL_CODE, global_imports=\\\"math,string\\\")\\n        assert \\\"error\\\" in data\\n        assert \\\"not allowed\\\" in data[\\\"error\\\"]\\n        assert \\\"SHOULD_NOT_LEAK\\\" not in str(data)\\n\\n    def test_attrgetter_traversal_is_blocked(self, monkeypatch):\\n        \\\"\\\"\\\"operator.attrgetter('__globals__') reaches os.environ via a string arg; blocked.\\\"\\\"\\\"\\n        monkeypatch.setenv(\\\"PVR0800453_CANARY\\\", \\\"SHOULD_NOT_LEAK\\\")\\n        data = self._run(ATTRGETTER_TRAVERSAL_CODE, global_imports=\\\"math,operator\\\")\\n        assert \\\"error\\\" in data\\n        assert \\\"not allowed\\\" in data[\\\"error\\\"]\\n        assert \\\"SHOULD_NOT_LEAK\\\" not in str(data)\\n\\n    def test_default_global_imports_excludes_pandas(self):\\n        \\\"\\\"\\\"The default allow-list is minimal (no pandas) to avoid bundling a deserialization sink.\\\"\\\"\\\"\\n        template = PythonREPLComponent().to_frontend_node()[\\\"data\\\"][\\\"node\\\"][\\\"template\\\"]\\n        assert template[\\\"global_imports\\\"][\\\"value\\\"] == \\\"math\\\"\\n\\n    def test_execution_refused_when_custom_components_disabled(self, monkeypatch):\\n        \\\"\\\"\\\"GHSA-8qpj-27x8-pwpq: run_python_repl must consult the gate, not just exec.\\n\\n        Locks in the wiring: a refactor dropping ensure_code_execution_enabled() from\\n        run_python_repl would make this fail, independent of the gate's own unit tests.\\n        \\\"\\\"\\\"\\n        from types import SimpleNamespace\\n\\n        monkeypatch.setattr(\\n            \\\"lfx.services.deps.get_settings_service\\\",\\n            lambda: SimpleNamespace(settings=SimpleNamespace(allow_custom_components=False)),\\n        )\\n        data = PythonREPLComponent(global_imports=\\\"math\\\", python_code=\\\"print('SHOULD_NOT_RUN')\\\").run_python_repl().data\\n        assert \\\"error\\\" in data\\n        assert \\\"allow_custom_components\\\" in data[\\\"error\\\"]\\n        # The code must never have executed.\\n        assert \\\"SHOULD_NOT_RUN\\\" not in str(data)\\n\\n\\nclass TestPythonREPLToolComponentToolNameDescription(ComponentTestBaseWithoutClient):\\n    \\\"\\\"\\\"build_tool must honor the \\\"Tool Name\\\" / \\\"Tool Description\\\" inputs.\\n\\n    The class attributes `name = \\\"PythonREPLTool\\\"` and `description = \\\"A tool for...\\\"`\\n    shadow the StrInputs of the same names \u2014 Component.__getattr__ only fires when\\n    normal attribute lookup fails, so self.name/self.description in build_tool always\\n    returned the class attributes and the user's input values were silently ignored.\\n    \\\"\\\"\\\"\\n\\n    @pytest.fixture\\n    def component_class(self):\\n        return PythonREPLToolComponent\\n\\n    @pytest.fixture\\n    def default_kwargs(self):\\n        return {\\n            \\\"name\\\": \\\"python_repl\\\",\\n            \\\"description\\\": \\\"run code\\\",\\n            \\\"global_imports\\\": \\\"math\\\",\\n            \\\"code\\\": \\\"print('x')\\\",\\n        }\\n\\n    @pytest.fixture\\n    def file_names_mapping(self):\\n        return []\\n\\n    def test_tool_uses_name_and_description_inputs(self):\\n        component = PythonREPLToolComponent(\\n            name=\\\"my_custom_repl\\\",\\n            description=\\\"Custom description the agent should see.\\\",\\n            global_imports=\\\"math\\\",\\n            code=\\\"print('x')\\\",\\n        )\\n        tool = component.build_tool()\\n        assert tool.name == \\\"my_custom_repl\\\"\\n        assert tool.description == \\\"Custom description the agent should see.\\\"\\n\\n    def test_tool_uses_input_defaults_when_unset(self):\\n        \\\"\\\"\\\"With no explicit inputs, the input defaults win over the class attributes.\\\"\\\"\\\"\\n        tool = PythonREPLToolComponent().build_tool()\\n        assert tool.name == \\\"python_repl\\\"\\n        assert tool.description.startswith(\\\"A Python shell.\\\")\\n\\n    def test_tool_falls_back_to_input_defaults_when_inputs_empty(self):\\n        \\\"\\\"\\\"Empty explicit inputs fall back to the input defaults.\\\"\\\"\\\"\\n        component = PythonREPLToolComponent(name=\\\"\\\", description=\\\"\\\")\\n        tool = component.build_tool()\\n        assert tool.name == \\\"python_repl\\\"\\n        assert tool.description.startswith(\\\"A Python shell.\\\")\\n\\n    def test_tool_falls_back_to_class_attributes_when_all_values_empty(self):\\n        \\\"\\\"\\\"When both the attribute and the input value are empty, the class attributes back-fill.\\\"\\\"\\\"\\n        component = PythonREPLToolComponent(name=\\\"\\\", description=\\\"\\\")\\n        component._inputs[\\\"name\\\"].value = \\\"\\\"\\n        component._inputs[\\\"description\\\"].value = \\\"\\\"\\n        tool = component.build_tool()\\n        assert tool.name == \\\"PythonREPLTool\\\"\\n        assert tool.description == \\\"A tool for running Python code in a REPL environment.\\\"\\n\\n    def test_tool_coerces_non_string_inputs(self):\\n        \\\"\\\"\\\"StrInput only warns on non-string values; tool metadata must still be strings.\\n\\n        Without coercion a non-string description crashes inside\\n        StructuredTool.from_function (it dedents/strips the description).\\n        \\\"\\\"\\\"\\n        component = PythonREPLToolComponent(name=123, description=456)\\n        tool = component.build_tool()\\n        assert tool.name == \\\"123\\\"\\n        assert tool.description == \\\"456\\\"\\n\\n\\nclass TestPythonREPLToolComponentRunModel:\\n    \\\"\\\"\\\"run_model must execute the Python Code input, not the component's own source.\\n\\n    `BaseComponent.code` is a class-level property returning the component's source;\\n    it shadowed the former StrInput named \\\"code\\\". The runtime field now serializes as\\n    \\\"python_code\\\", while \\\"code\\\" remains accepted as a programmatic compatibility alias.\\n    \\\"\\\"\\\"\\n\\n    def test_run_model_executes_code_input(self):\\n        component = PythonREPLToolComponent(\\n            name=\\\"python_repl\\\",\\n            description=\\\"run code\\\",\\n            global_imports=\\\"math\\\",\\n            code=\\\"print(math.sqrt(16))\\\",\\n        )\\n        results = component.run_model()\\n        assert len(results) == 1\\n        assert \\\"4.0\\\" in results[0].data[\\\"result\\\"]\\n\\n    def test_run_model_uses_default_code_when_unset(self):\\n        results = PythonREPLToolComponent().run_model()\\n        assert \\\"Hello, World!\\\" in results[0].data[\\\"result\\\"]\\n\\n    def test_run_model_does_not_execute_component_source(self):\\n        \\\"\\\"\\\"The input must win over the component's own source.\\n\\n        The component source starts with imports, so passing it to the tool would\\n        raise ToolException(\\\"Imports are not allowed...\\\").\\n        \\\"\\\"\\\"\\n        component = PythonREPLToolComponent(code=\\\"print('input wins')\\\")\\n        results = component.run_model()\\n        assert \\\"input wins\\\" in results[0].data[\\\"result\\\"]\\n\\n    def test_run_model_accepts_legacy_code_setter(self):\\n        component = PythonREPLToolComponent()\\n        component.set(code=\\\"print('legacy setter input')\\\")\\n        results = component.run_model()\\n        assert \\\"legacy setter input\\\" in results[0].data[\\\"result\\\"]\\n\\n    @pytest.mark.asyncio\\n    async def test_run_model_executes_python_code_after_frontend_round_trip(self):\\n        component = PythonREPLToolComponent(python_code=\\\"print('round trip input')\\\", _id=\\\"python-repl\\\")\\n        node = component.to_frontend_node()\\n        graph = Graph.from_payload({\\\"nodes\\\": [node], \\\"edges\\\": []})\\n\\n        _ = [result async for result in graph.async_start()]\\n\\n        output = graph.get_vertex(\\\"python-repl\\\").built_object[\\\"api_run_model\\\"]\\n        assert output[0].data[\\\"result\\\"].strip() == \\\"round trip input\\\"\\n\\n\\nclass TestPythonREPLToolComponentSecurity:\\n    \\\"\\\"\\\"The same hardening applies to the legacy Python REPL *tool* component.\\\"\\\"\\\"\\n\\n    def _func(self, global_imports=\\\"math\\\"):\\n        component = PythonREPLToolComponent(\\n            name=\\\"python_repl\\\",\\n            description=\\\"run code\\\",\\n            global_imports=global_imports,\\n            code=\\\"print('x')\\\",\\n        )\\n        return component.build_tool().func\\n\\n    def test_tool_runs_legitimate_code(self):\\n        assert \\\"hi\\\" in self._func()(\\\"print('hi')\\\")\\n\\n    def test_tool_blocks_inline_import(self):\\n        with pytest.raises(ToolException, match=\\\"not allowed\\\"):\\n            self._func()(\\\"import os\\\")\\n\\n    def test_tool_blocks_subclasses_escape(self):\\n        with pytest.raises(ToolException, match=\\\"not allowed\\\"):\\n            self._func()(\\\"().__class__.__bases__[0].__subclasses__()\\\")\\n\\n    def test_tool_blocks_dynamic_format_string_traversal(self, monkeypatch):\\n        monkeypatch.setenv(\\\"PVR0800453_CANARY\\\", \\\"SHOULD_NOT_LEAK\\\")\\n        with pytest.raises(ToolException, match=\\\"not allowed\\\") as exc_info:\\n            self._func()(DYNAMIC_FORMAT_TRAVERSAL_CODE)\\n        assert \\\"SHOULD_NOT_LEAK\\\" not in str(exc_info.value)\\n\\n    def test_tool_blocks_import_builtin(self):\\n        \\\"\\\"\\\"__import__ is a bare name; PythonREPL surfaces the NameError as a string.\\\"\\\"\\\"\\n        result = self._func()('__import__(\\\"subprocess\\\").check_output([\\\"echo\\\", \\\"PWNED\\\"])')\\n        assert \\\"PWNED\\\" not in result\\n        assert \\\"NameError\\\" in result\\n\\n    def test_tool_invocations_do_not_share_state(self):\\n        \\\"\\\"\\\"Each tool call gets a fresh namespace, so variables do not leak across calls.\\\"\\\"\\\"\\n        func = self._func()\\n        func(\\\"leaked = 12345\\\")\\n        result = func(\\\"print(leaked)\\\")\\n        assert \\\"NameError\\\" in result\\n\\n    def test_execution_refused_when_custom_components_disabled(self, monkeypatch):\\n        \\\"\\\"\\\"GHSA-8qpj-27x8-pwpq: run_python_code must consult the gate, not just exec.\\n\\n        Locks in the wiring: a refactor dropping ensure_code_execution_enabled() from\\n        run_python_code would make this fail, independent of the gate's own unit tests.\\n        \\\"\\\"\\\"\\n        from types import SimpleNamespace\\n\\n        monkeypatch.setattr(\\n            \\\"lfx.services.deps.get_settings_service\\\",\\n            lambda: SimpleNamespace(settings=SimpleNamespace(allow_custom_components=False)),\\n        )\\n        with pytest.raises(ToolException, match=\\\"allow_custom_components\\\"):\\n            self._func()(\\\"print('SHOULD_NOT_RUN')\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/tools/test_searxng.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"73cb6180fb91544f3fa46635f7ebd1251e521498867dfe1c46bf9a97311cb665\",\"content\":\"\\\"\\\"\\\"SSRF protection tests for the legacy SearXNG Search tool component.\\n\\nBoth the config-autocomplete fetch (``update_build_config``) and the agent-invokable\\nsearch tool issue requests to a user-supplied base URL. With SSRF protection enabled\\nthose URLs must be validated so they cannot reach internal services.\\n\\\"\\\"\\\"\\n\\nimport ipaddress\\nimport os\\nimport socket\\nfrom unittest.mock import Mock, patch\\n\\nfrom lfx.components.tools.searxng import SearXNGToolComponent\\nfrom lfx.schema.dotdict import dotdict\\n\\n\\ndef _resolve_public(host, *_args, **_kwargs):\\n    \\\"\\\"\\\"socket.getaddrinfo stub: hostnames resolve to a public IP, literal IPs to themselves.\\\"\\\"\\\"\\n    try:\\n        ipaddress.ip_address(host)\\n    except ValueError:\\n        ip = \\\"93.184.216.34\\\"\\n    else:\\n        ip = host\\n    family = socket.AF_INET6 if \\\":\\\" in ip else socket.AF_INET\\n    return [(family, socket.SOCK_STREAM, 6, \\\"\\\", (ip, 0))]\\n\\n\\nclass TestSearXNGSSRFProtection:\\n    def test_update_build_config_blocks_internal_url(self):\\n        \\\"\\\"\\\"Fetching the SearXNG /config from an internal URL is blocked; no request is made.\\\"\\\"\\\"\\n        component = SearXNGToolComponent()\\n        build_config = dotdict(\\n            {\\n                \\\"url\\\": {\\\"value\\\": \\\"\\\"},\\n                \\\"categories\\\": {\\\"options\\\": [], \\\"value\\\": []},\\n                \\\"language\\\": {\\\"options\\\": []},\\n            }\\n        )\\n\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n            patch(\\\"requests.get\\\") as mock_get,\\n        ):\\n            result = component.update_build_config(build_config, \\\"http://169.254.169.254\\\", \\\"url\\\")\\n\\n        mock_get.assert_not_called()\\n        # The component records the failure rather than fetching internal data.\\n        assert result[\\\"categories\\\"][\\\"options\\\"][0] == \\\"Failed to parse\\\"\\n\\n    def test_search_tool_blocks_internal_url(self):\\n        \\\"\\\"\\\"The agent-invokable search tool blocks an internal base URL; no request is made.\\\"\\\"\\\"\\n        component = SearXNGToolComponent()\\n        component.url = \\\"http://169.254.169.254\\\"\\n        component.categories = [\\\"general\\\"]\\n        component.language = \\\"en\\\"\\n        component.max_results = 5\\n\\n        tool = component.build_tool()\\n\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n            patch(\\\"requests.get\\\") as mock_get,\\n        ):\\n            result = tool.func(query=\\\"secrets\\\")\\n\\n        mock_get.assert_not_called()\\n        assert isinstance(result, list)\\n        assert \\\"Failed to search\\\" in result[0]\\n\\n    def test_search_tool_allows_public_url(self):\\n        \\\"\\\"\\\"A public SearXNG instance still works with SSRF protection enabled.\\\"\\\"\\\"\\n        component = SearXNGToolComponent()\\n        component.url = \\\"http://searx.example.com\\\"\\n        component.categories = [\\\"general\\\"]\\n        component.language = \\\"en\\\"\\n        component.max_results = 5\\n\\n        tool = component.build_tool()\\n\\n        search_response = Mock()\\n        search_response.status_code = 200\\n        search_response.headers = {}\\n        search_response.json = Mock(return_value={\\\"results\\\": [{\\\"title\\\": \\\"a\\\"}, {\\\"title\\\": \\\"b\\\"}]})\\n\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n            patch(\\\"socket.getaddrinfo\\\", side_effect=_resolve_public),\\n            patch(\\\"requests.get\\\", return_value=search_response) as mock_get,\\n        ):\\n            result = tool.func(query=\\\"news\\\")\\n\\n        assert mock_get.call_count == 1\\n        assert len(result) == 2\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/tools/test_serp_api.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"78223a3d154283cdc78bd5c755ba0451da38e5deb1023dfb6341b2267817d36d\",\"content\":\"from unittest.mock import MagicMock, patch\\n\\nimport pytest\\nfrom langchain_core.tools import ToolException\\nfrom langflow.custom import Component\\n\\npytest.importorskip(\\\"lfx_bundles\\\")\\n\\nfrom lfx.components.serpapi.serp import SerpComponent\\nfrom lfx.custom.utils import build_custom_component_template\\nfrom lfx.schema import Data\\nfrom lfx.schema.message import Message\\n\\n\\ndef test_serpapi_initialization():\\n    component = SerpComponent()\\n    assert component.display_name == \\\"Serp Search API\\\"\\n    assert component.description == \\\"Call Serp Search API with result limiting\\\"\\n    assert component.icon == \\\"SerpSearch\\\"\\n\\n\\ndef test_serpapi_template():\\n    serpapi = SerpComponent()\\n    component = Component(_code=serpapi._code)\\n    frontend_node, _ = build_custom_component_template(component)\\n\\n    # Verify basic structure\\n    assert isinstance(frontend_node, dict)\\n\\n    # Verify inputs\\n    assert \\\"template\\\" in frontend_node\\n    input_names = [input_[\\\"name\\\"] for input_ in frontend_node[\\\"template\\\"].values() if isinstance(input_, dict)]\\n\\n    expected_inputs = [\\\"serpapi_api_key\\\", \\\"input_value\\\", \\\"search_params\\\", \\\"max_results\\\", \\\"max_snippet_length\\\"]\\n\\n    for input_name in expected_inputs:\\n        assert input_name in input_names\\n\\n\\n@patch(\\\"lfx.components.serpapi.serp.SerpAPIWrapper\\\")\\ndef test_fetch_content(mock_serpapi_wrapper):\\n    component = SerpComponent()\\n    component.serpapi_api_key = \\\"test-key\\\"\\n    component.input_value = \\\"test query\\\"\\n    component.max_results = 3\\n    component.max_snippet_length = 100\\n\\n    # Mock the SerpAPIWrapper and its results method\\n    mock_instance = MagicMock()\\n    mock_serpapi_wrapper.return_value = mock_instance\\n    mock_instance.results.return_value = {\\n        \\\"organic_results\\\": [\\n            {\\\"title\\\": \\\"Test Result 1\\\", \\\"link\\\": \\\"https://test.com\\\", \\\"snippet\\\": \\\"This is a test result 1\\\"},\\n            {\\\"title\\\": \\\"Test Result 2\\\", \\\"link\\\": \\\"https://test2.com\\\", \\\"snippet\\\": \\\"This is a test result 2\\\"},\\n        ]\\n    }\\n\\n    result = component.fetch_content()\\n\\n    assert isinstance(result, list)\\n    assert len(result) == 2\\n    assert result[0].text == \\\"This is a test result 1\\\"\\n    assert result[0].data[\\\"title\\\"] == \\\"Test Result 1\\\"\\n    assert result[0].data[\\\"link\\\"] == \\\"https://test.com\\\"\\n\\n\\ndef test_fetch_content_text():\\n    component = SerpComponent()\\n    component.fetch_content = MagicMock(\\n        return_value=[\\n            Data(text=\\\"First result\\\", data={\\\"title\\\": \\\"Title 1\\\"}),\\n            Data(text=\\\"Second result\\\", data={\\\"title\\\": \\\"Title 2\\\"}),\\n        ]\\n    )\\n\\n    result = component.fetch_content_text()\\n\\n    assert isinstance(result, Message)\\n    assert result.text == \\\"First result\\\\nSecond result\\\\n\\\"\\n\\n\\ndef test_error_handling():\\n    component = SerpComponent()\\n    component.serpapi_api_key = \\\"test-key\\\"\\n    component.input_value = \\\"test query\\\"\\n\\n    with patch(\\\"lfx.components.serpapi.serp.SerpAPIWrapper\\\") as mock_serpapi:\\n        mock_instance = MagicMock()\\n        mock_serpapi.return_value = mock_instance\\n        mock_instance.results.side_effect = Exception(\\\"API Error\\\")\\n\\n        with pytest.raises(ToolException):\\n            component.fetch_content()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/vectorstores/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/vectorstores/test_cassandra_batch_size.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"6159b0fbf2c3d362adae7bee158b4e47f466ae14785dbd76b85f2da23a45376b\",\"content\":\"\\\"\\\"\\\"Ingesting into the Cassandra vector store must not crash.\\n\\n``build_vector_store`` called ``Cassandra.from_documents(..., batch_size=...)``.\\n``from_documents`` does not declare ``batch_size``, so it landed in ``**kwargs``\\nand was splatted into ``cls(...)`` -- i.e. ``Cassandra.__init__``, which accepts\\nonly ``embedding, session, keyspace, table_name, ttl_seconds, body_index_options,\\nsetup_mode, metadata_indexing``. Every run with anything wired to Ingest Data\\ndied with::\\n\\n    Cassandra.__init__() got an unexpected keyword argument 'batch_size'\\n\\n``batch_size`` is a real parameter of ``Cassandra.add_texts`` (default 16), which\\n``add_documents`` forwards to, so the exposed component field has a correct home\\nand must keep working rather than being dropped.\\n\\nNothing above the storage layer is stubbed: ``cassio.init`` opens a real cluster\\nsession and the cassio table writes rows, so those two are patched and everything\\nelse -- the component, ``Cassandra.__init__``, ``add_documents`` -> ``add_texts`` --\\nruns as shipped. The bug cannot hide behind those patches either, since the\\nTypeError comes from binding arguments to ``__init__`` before its body runs.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom unittest.mock import MagicMock, patch\\n\\nimport pytest\\nfrom langchain_community.vectorstores import Cassandra\\nfrom langchain_core.embeddings import Embeddings, FakeEmbeddings\\nfrom lfx.components.cassandra.cassandra import (\\n    DEFAULT_BATCH_SIZE,\\n    CassandraVectorStoreComponent,\\n)\\nfrom lfx.schema.data import Data\\n\\nMODULE = \\\"lfx.components.cassandra.cassandra\\\"\\nCASSIO_TABLE = \\\"cassio.table.MetadataVectorCassandraTable\\\"\\nBATCH_SIZE = 16\\n\\n\\ndef _component(*, with_documents: bool, setup_mode: str = \\\"Sync\\\") -> CassandraVectorStoreComponent:\\n    component = CassandraVectorStoreComponent()\\n    component.database_ref = \\\"127.0.0.1\\\"\\n    component.username = \\\"user\\\"\\n    component.token = \\\"token\\\"  # noqa: S105\\n    component.keyspace = \\\"test_keyspace\\\"\\n    component.table_name = \\\"test_table\\\"\\n    component.ttl_seconds = 0\\n    component.batch_size = BATCH_SIZE\\n    component.cluster_kwargs = {}\\n    component.setup_mode = setup_mode\\n    component.enable_body_search = False\\n    component.embedding = MagicMock(spec=Embeddings)\\n    component.ingest_data = [Data(text=\\\"hello world\\\")] if with_documents else []\\n    return component\\n\\n\\n@pytest.mark.parametrize((\\\"document_count\\\", \\\"batch_size\\\"), [(1, 16), (5, 2), (40, 16), (5, 0)])\\ndef test_should_ingest_against_the_real_cassandra_implementation(document_count: int, batch_size: int):\\n    \\\"\\\"\\\"The reported failure, checked end to end rather than against a stubbed class.\\n\\n    Only the cassio storage table is patched -- the layer that genuinely needs a\\n    cluster. ``Cassandra.__init__``, ``add_documents`` and ``add_texts`` all run for\\n    real, so a mismatch anywhere in that chain still fails here, not just at the\\n    constructor where the reported TypeError happened to land.\\n    \\\"\\\"\\\"\\n    component = _component(with_documents=False)\\n    component.batch_size = batch_size\\n    component.embedding = FakeEmbeddings(size=8)\\n    component.ingest_data = [Data(text=f\\\"doc {i}\\\") for i in range(document_count)]\\n\\n    table = MagicMock()\\n    table.session = MagicMock()\\n\\n    with patch(\\\"cassio.init\\\"), patch(CASSIO_TABLE, MagicMock(return_value=table)):\\n        store = component.build_vector_store()\\n\\n    assert isinstance(store, Cassandra)\\n    assert table.put_async.call_count == document_count, \\\"not every document reached the store\\\"\\n\\n\\ndef test_should_pass_batch_size_to_add_documents():\\n    \\\"\\\"\\\"The exposed field must keep its meaning, not be silently dropped.\\\"\\\"\\\"\\n    component = _component(with_documents=True)\\n    table = MagicMock()\\n\\n    with patch(\\\"cassio.init\\\"), patch(f\\\"{MODULE}.Cassandra\\\", MagicMock(return_value=table)):\\n        result = component.build_vector_store()\\n\\n    table.add_documents.assert_called_once()\\n    assert table.add_documents.call_args.kwargs[\\\"batch_size\\\"] == BATCH_SIZE\\n    assert result is table\\n\\n\\ndef test_should_ingest_every_document():\\n    component = _component(with_documents=True)\\n    table = MagicMock()\\n\\n    with patch(\\\"cassio.init\\\"), patch(f\\\"{MODULE}.Cassandra\\\", MagicMock(return_value=table)):\\n        component.build_vector_store()\\n\\n    documents = table.add_documents.call_args.kwargs[\\\"documents\\\"]\\n    assert len(documents) == 1\\n    assert documents[0].page_content == \\\"hello world\\\"\\n\\n\\ndef test_should_not_add_documents_when_ingest_data_is_empty():\\n    \\\"\\\"\\\"The search-only path was never broken and must stay untouched.\\\"\\\"\\\"\\n    component = _component(with_documents=False)\\n    table = MagicMock()\\n\\n    with patch(\\\"cassio.init\\\"), patch(f\\\"{MODULE}.Cassandra\\\", MagicMock(return_value=table)) as cls:\\n        result = component.build_vector_store()\\n\\n    table.add_documents.assert_not_called()\\n    assert \\\"batch_size\\\" not in cls.call_args.kwargs\\n    assert result is table\\n\\n\\n@pytest.mark.parametrize((\\\"setup_mode\\\", \\\"expected\\\"), [(\\\"Sync\\\", \\\"SYNC\\\"), (\\\"Async\\\", \\\"SYNC\\\"), (\\\"Off\\\", \\\"OFF\\\")])\\ndef test_should_resolve_setup_mode_for_a_synchronous_ingest(setup_mode: str, expected: str):\\n    \\\"\\\"\\\"ASYNC is unsafe on this path; OFF is not, and it is the one that matters.\\n\\n    ``SetupMode.ASYNC`` makes ``__init__`` hand cassio ``async_setup=True`` plus an\\n    un-awaited coroutine as the vector dimension, while ``add_documents``/``add_texts``\\n    are synchronous -- so it degrades to SYNC. ``SetupMode.OFF`` is honoured because it\\n    is what sets ``skip_provisioning``: forcing SYNC would re-run the table DDL on every\\n    ingest for a pre-provisioned table or a role without CREATE.\\n    \\\"\\\"\\\"\\n    from langchain_community.utilities.cassandra import SetupMode\\n\\n    component = _component(with_documents=True, setup_mode=setup_mode)\\n\\n    with patch(\\\"cassio.init\\\"), patch(f\\\"{MODULE}.Cassandra\\\", MagicMock(return_value=MagicMock())) as cls:\\n        component.build_vector_store()\\n\\n    assert cls.call_args.kwargs[\\\"setup_mode\\\"] is getattr(SetupMode, expected)\\n\\n\\n@pytest.mark.parametrize(\\\"raw_batch_size\\\", [0, None, \\\"\\\"])\\ndef test_should_fall_back_to_the_default_batch_size_when_the_field_is_cleared(raw_batch_size):\\n    \\\"\\\"\\\"``IntInput`` coerces a cleared advanced field to 0.\\n\\n    ``add_texts`` slices with\\n    ``range(0, len(texts), batch_size)`` -- which raises ``range() arg 3 must not be\\n    zero`` only AFTER the table DDL and the embedding-dimension probe have run.\\n    \\\"\\\"\\\"\\n    component = _component(with_documents=True)\\n    component.batch_size = raw_batch_size\\n    table = MagicMock()\\n\\n    with patch(\\\"cassio.init\\\"), patch(f\\\"{MODULE}.Cassandra\\\", MagicMock(return_value=table)):\\n        component.build_vector_store()\\n\\n    assert table.add_documents.call_args.kwargs[\\\"batch_size\\\"] == DEFAULT_BATCH_SIZE\\n\\n\\ndef test_should_clamp_a_negative_batch_size():\\n    \\\"\\\"\\\"A negative batch size makes add_texts iterate an empty range.\\n\\n    It reports success\\n    and writes NOTHING, which is worse than the crash a zero produces.\\n    \\\"\\\"\\\"\\n    component = _component(with_documents=True)\\n    component.batch_size = -1\\n    component.embedding = FakeEmbeddings(size=8)\\n    table = MagicMock()\\n    table.session = MagicMock()\\n\\n    with patch(\\\"cassio.init\\\"), patch(CASSIO_TABLE, MagicMock(return_value=table)):\\n        component.build_vector_store()\\n\\n    assert table.put_async.call_count == 1, \\\"a negative batch size silently dropped the documents\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/vectorstores/test_chroma_vector_store_component.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"9eb9fcdc84155b596c2999433ec37965284718c7fabb7c1b92ac76e7bb7e9a3f\",\"content\":\"from pathlib import Path\\nfrom typing import Any\\nfrom unittest.mock import MagicMock, patch\\n\\nimport pytest\\n\\npytest.importorskip(\\\"lfx_bundles\\\")\\n\\nfrom langchain_core.embeddings import Embeddings\\nfrom lfx.base.vectorstores.chroma_security import (\\n    chroma_client_create_collection_kwargs,\\n    chroma_langchain_collection_kwargs,\\n)\\nfrom lfx.components.chroma import ChromaVectorStoreComponent\\nfrom lfx.schema.data import Data\\n\\nfrom tests.base import ComponentTestBaseWithoutClient, VersionComponentMapping\\n\\n\\nclass _KeywordEmbeddings(Embeddings):\\n    _VOCAB = (\\\"dog\\\", \\\"python\\\", \\\"programming\\\", \\\"machine\\\", \\\"learning\\\", \\\"fox\\\", \\\"cat\\\", \\\"quick\\\", \\\"test\\\", \\\"data\\\")\\n\\n    def _embed(self, text: str) -> list[float]:\\n        normalized_text = text.lower()\\n        return [float(normalized_text.count(term)) for term in self._VOCAB] + [float(len(normalized_text) % 17) / 17.0]\\n\\n    def embed_documents(self, texts: list[str]) -> list[list[float]]:\\n        return [self._embed(text) for text in texts]\\n\\n    def embed_query(self, text: str) -> list[float]:\\n        return self._embed(text)\\n\\n\\ndef test_remote_chroma_server_uses_http_client(monkeypatch: pytest.MonkeyPatch) -> None:\\n    # This test asserts the remote HttpClient wiring (host/port/ssl), not SSRF behavior; the\\n    # connector SSRF guard is covered separately (test_connector_ssrf.py / test_ssrf_protection.py).\\n    # Disable connector SSRF validation so the fake ``chroma.example.com`` host is not DNS-resolved.\\n    monkeypatch.setenv(\\\"LANGFLOW_CONNECTOR_SSRF_VALIDATION_ENABLED\\\", \\\"false\\\")\\n\\n    mock_client = MagicMock()\\n    mock_chroma = MagicMock()\\n    mock_chroma.get.return_value = {\\\"ids\\\": [], \\\"documents\\\": [], \\\"metadatas\\\": []}\\n\\n    with (\\n        patch(\\\"chromadb.HttpClient\\\", return_value=mock_client) as mock_http_client,\\n        patch(\\\"langchain_chroma.Chroma\\\", return_value=mock_chroma) as mock_chroma_class,\\n    ):\\n        component = ChromaVectorStoreComponent().set(\\n            collection_name=\\\"remote_collection\\\",\\n            persist_directory=None,\\n            embedding=None,\\n            chroma_server_host=\\\"chroma.example.com\\\",\\n            chroma_server_http_port=8100,\\n            chroma_server_ssl_enabled=True,\\n            ingest_data=[],\\n            limit=None,\\n        )\\n\\n        assert component.build_vector_store() is mock_chroma\\n\\n    mock_http_client.assert_called_once_with(host=\\\"chroma.example.com\\\", port=8100, ssl=True)\\n    mock_chroma_class.assert_called_once_with(\\n        persist_directory=None,\\n        client=mock_client,\\n        embedding_function=None,\\n        collection_name=\\\"remote_collection\\\",\\n        collection_configuration={\\\"embedding_function\\\": None},\\n    )\\n\\n\\ndef test_chroma_collection_security_kwargs_disable_server_side_embedding_functions() -> None:\\n    assert chroma_langchain_collection_kwargs() == {\\n        \\\"collection_configuration\\\": {\\\"embedding_function\\\": None},\\n    }\\n    assert chroma_client_create_collection_kwargs() == {\\n        \\\"configuration\\\": {\\\"embedding_function\\\": None},\\n        \\\"embedding_function\\\": None,\\n    }\\n\\n\\ndef test_chroma_collection_security_kwargs_are_fresh_dicts() -> None:\\n    first = chroma_langchain_collection_kwargs()\\n    first[\\\"collection_configuration\\\"][\\\"embedding_function\\\"] = \\\"unsafe\\\"\\n\\n    assert chroma_langchain_collection_kwargs() == {\\n        \\\"collection_configuration\\\": {\\\"embedding_function\\\": None},\\n    }\\n\\n\\ndef test_local_chroma_collection_name_is_scoped_by_user(tmp_path: Path) -> None:\\n    mock_chroma = MagicMock()\\n    mock_chroma.get.return_value = {\\\"ids\\\": [], \\\"documents\\\": [], \\\"metadatas\\\": []}\\n\\n    with patch(\\\"langchain_chroma.Chroma\\\", return_value=mock_chroma) as mock_chroma_class:\\n        for user_id in (\\\"owner-user\\\", \\\"attacker-user\\\"):\\n            component = ChromaVectorStoreComponent(_user_id=user_id).set(\\n                collection_name=\\\"shared_collection\\\",\\n                persist_directory=str(tmp_path / \\\"shared\\\"),\\n                embedding=None,\\n                ingest_data=[],\\n                limit=None,\\n            )\\n            component.build_vector_store()\\n\\n    collection_names = [call.kwargs[\\\"collection_name\\\"] for call in mock_chroma_class.call_args_list]\\n    assert len(collection_names) == 2\\n    assert collection_names[0] != \\\"shared_collection\\\"\\n    assert collection_names[1] != \\\"shared_collection\\\"\\n    assert collection_names[0] != collection_names[1]\\n\\n\\ndef test_local_chroma_same_apparent_namespace_isolated_by_user(tmp_path: Path) -> None:\\n    shared_dir = tmp_path / \\\"shared_chroma\\\"\\n    embeddings = _KeywordEmbeddings()\\n\\n    owner_component = ChromaVectorStoreComponent(_user_id=\\\"owner-user\\\").set(\\n        collection_name=\\\"shared_collection\\\",\\n        persist_directory=str(shared_dir),\\n        embedding=embeddings,\\n        ingest_data=[Data(text=\\\"owner-only-vector-private-content\\\")],\\n        allow_duplicates=True,\\n        limit=100,\\n    )\\n    owner_component.build_vector_store()\\n\\n    attacker_component = ChromaVectorStoreComponent(_user_id=\\\"attacker-user\\\").set(\\n        collection_name=\\\"shared_collection\\\",\\n        persist_directory=str(shared_dir),\\n        embedding=embeddings,\\n        ingest_data=[Data(text=\\\"attacker-vector-content\\\")],\\n        allow_duplicates=True,\\n        limit=100,\\n    )\\n    attacker_store = attacker_component.build_vector_store()\\n\\n    documents = attacker_store.get(limit=100)[\\\"documents\\\"]\\n    assert \\\"attacker-vector-content\\\" in documents\\n    assert \\\"owner-only-vector-private-content\\\" not in documents\\n\\n\\nclass TestChromaVectorStoreComponent(ComponentTestBaseWithoutClient):\\n    @pytest.fixture\\n    def component_class(self) -> type[Any]:\\n        \\\"\\\"\\\"Return the component class to test.\\\"\\\"\\\"\\n        return ChromaVectorStoreComponent\\n\\n    @pytest.fixture\\n    def default_kwargs(self, tmp_path: Path) -> dict[str, Any]:\\n        \\\"\\\"\\\"Return the default kwargs for the component.\\\"\\\"\\\"\\n        return {\\n            \\\"embedding\\\": _KeywordEmbeddings(),\\n            \\\"collection_name\\\": \\\"test_collection\\\",\\n            \\\"persist_directory\\\": tmp_path,\\n        }\\n\\n    @pytest.fixture\\n    def file_names_mapping(self) -> list[VersionComponentMapping]:\\n        \\\"\\\"\\\"Return the file names mapping for different versions.\\\"\\\"\\\"\\n        return [\\n            {\\\"version\\\": \\\"1.0.19\\\", \\\"module\\\": \\\"vectorstores\\\", \\\"file_name\\\": \\\"Chroma\\\"},\\n            {\\\"version\\\": \\\"1.1.0\\\", \\\"module\\\": \\\"vectorstores\\\", \\\"file_name\\\": \\\"chroma\\\"},\\n            {\\\"version\\\": \\\"1.1.1\\\", \\\"module\\\": \\\"vectorstores\\\", \\\"file_name\\\": \\\"chroma\\\"},\\n        ]\\n\\n    def test_create_db(self, component_class: type[ChromaVectorStoreComponent], default_kwargs: dict[str, Any]) -> None:\\n        \\\"\\\"\\\"Test the create_collection method.\\\"\\\"\\\"\\n        component: ChromaVectorStoreComponent = component_class().set(**default_kwargs)\\n        component.build_vector_store()\\n        persist_directory = default_kwargs[\\\"persist_directory\\\"]\\n        assert persist_directory.exists()\\n        assert persist_directory.is_dir()\\n        # Assert it isn't empty\\n        assert len(list(persist_directory.iterdir())) > 0\\n        # Assert there's a chroma.sqlite3 file\\n        assert (persist_directory / \\\"chroma.sqlite3\\\").exists()\\n        assert (persist_directory / \\\"chroma.sqlite3\\\").is_file()\\n\\n    def test_create_collection_with_data(\\n        self, component_class: type[ChromaVectorStoreComponent], default_kwargs: dict[str, Any]\\n    ) -> None:\\n        \\\"\\\"\\\"Test the create_collection method with data.\\\"\\\"\\\"\\n        # set ingest_data in default_kwargs to a list of Data objects\\n        test_texts = [\\\"test data 1\\\", \\\"test data 2\\\", \\\"something completely different\\\"]\\n        default_kwargs[\\\"ingest_data\\\"] = [Data(text=text) for text in test_texts]\\n\\n        component: ChromaVectorStoreComponent = component_class().set(**default_kwargs)\\n        vector_store = component.build_vector_store()\\n\\n        # Verify collection exists and has the correct data\\n        collection = vector_store._collection\\n        assert collection.name == default_kwargs[\\\"collection_name\\\"]\\n        assert collection.count() == len(test_texts)\\n\\n    def test_similarity_search(\\n        self, component_class: type[ChromaVectorStoreComponent], default_kwargs: dict[str, Any]\\n    ) -> None:\\n        \\\"\\\"\\\"Test the similarity search functionality through the component.\\\"\\\"\\\"\\n        # Create test data with distinct topics\\n        test_data = [\\n            \\\"The quick brown fox jumps over the lazy dog\\\",\\n            \\\"Python is a popular programming language\\\",\\n            \\\"Machine learning models process data\\\",\\n            \\\"The lazy dog sleeps all day long\\\",\\n        ]\\n        default_kwargs[\\\"ingest_data\\\"] = [Data(text=text) for text in test_data]\\n        default_kwargs[\\\"search_type\\\"] = \\\"Similarity\\\"\\n        default_kwargs[\\\"number_of_results\\\"] = 2\\n\\n        component: ChromaVectorStoreComponent = component_class().set(**default_kwargs)\\n        component.build_vector_store()\\n\\n        # Test similarity search through the component\\n        component.set(search_query=\\\"dog sleeping\\\")\\n        results = component.search_documents()\\n\\n        assert len(results) == 2\\n        # The most relevant results should be about dogs\\n        assert any(\\\"dog\\\" in result.text.lower() for result in results)\\n\\n        # Test with different number of results\\n        component.set(number_of_results=3)\\n        results = component.search_documents()\\n        assert len(results) == 3\\n\\n    def test_mmr_search(\\n        self, component_class: type[ChromaVectorStoreComponent], default_kwargs: dict[str, Any]\\n    ) -> None:\\n        \\\"\\\"\\\"Test the MMR search functionality through the component.\\\"\\\"\\\"\\n        # Create test data with some similar documents\\n        test_data = [\\n            \\\"The quick brown fox jumps\\\",\\n            \\\"The quick brown fox leaps\\\",\\n            \\\"The quick brown fox hops\\\",\\n            \\\"Something completely different about cats\\\",\\n        ]\\n        default_kwargs[\\\"ingest_data\\\"] = [Data(text=text) for text in test_data]\\n        default_kwargs[\\\"search_type\\\"] = \\\"MMR\\\"\\n        default_kwargs[\\\"number_of_results\\\"] = 3\\n\\n        component: ChromaVectorStoreComponent = component_class().set(**default_kwargs)\\n        component.build_vector_store()\\n\\n        # Test MMR search through the component\\n        component.set(search_query=\\\"quick fox\\\")\\n        results = component.search_documents()\\n\\n        assert len(results) == 3\\n        # Results should be diverse but relevant\\n        assert any(\\\"fox\\\" in result.text.lower() for result in results)\\n\\n        # Test with different settings\\n        component.set(number_of_results=2)\\n        diverse_results = component.search_documents()\\n        assert len(diverse_results) == 2\\n\\n    def test_search_with_different_types(\\n        self, component_class: type[ChromaVectorStoreComponent], default_kwargs: dict[str, Any]\\n    ) -> None:\\n        \\\"\\\"\\\"Test search with different search types.\\\"\\\"\\\"\\n        test_data = [\\n            \\\"The quick brown fox jumps over the lazy dog\\\",\\n            \\\"Python is a popular programming language\\\",\\n            \\\"Machine learning models process data\\\",\\n        ]\\n        default_kwargs[\\\"ingest_data\\\"] = [Data(text=text) for text in test_data]\\n        default_kwargs[\\\"number_of_results\\\"] = 2\\n\\n        component: ChromaVectorStoreComponent = component_class().set(**default_kwargs)\\n        component.build_vector_store()\\n\\n        # Test similarity search\\n        component.set(search_type=\\\"Similarity\\\", search_query=\\\"programming languages\\\")\\n        similarity_results = component.search_documents()\\n        assert len(similarity_results) == 2\\n        assert any(\\\"python\\\" in result.text.lower() for result in similarity_results)\\n\\n        # Test MMR search\\n        component.set(search_type=\\\"MMR\\\", search_query=\\\"programming languages\\\")\\n        mmr_results = component.search_documents()\\n        assert len(mmr_results) == 2\\n\\n        # Test with empty query\\n        component.set(search_query=\\\"\\\")\\n        empty_results = component.search_documents()\\n        assert len(empty_results) == 0\\n\\n    def test_search_with_score(\\n        self, component_class: type[ChromaVectorStoreComponent], default_kwargs: dict[str, Any]\\n    ) -> None:\\n        \\\"\\\"\\\"Test the search with score functionality through the component.\\\"\\\"\\\"\\n        test_data = [\\n            \\\"The quick brown fox jumps over the lazy dog\\\",\\n            \\\"Python is a popular programming language\\\",\\n            \\\"Machine learning models process data\\\",\\n        ]\\n        default_kwargs[\\\"ingest_data\\\"] = [Data(text=text) for text in test_data]\\n        default_kwargs[\\\"number_of_results\\\"] = 2\\n\\n        component: ChromaVectorStoreComponent = component_class().set(**default_kwargs)\\n        component.build_vector_store()\\n\\n        # Test search with score through the component\\n        component.set(\\n            search_type=\\\"similarity_score_threshold\\\", search_query=\\\"programming languages\\\", number_of_results=2\\n        )\\n        results = component.search_documents()\\n\\n        assert len(results) == 2\\n        # Results should be sorted by relevance\\n        assert any(\\\"python\\\" in result.text.lower() for result in results)\\n        assert any(\\\"programming\\\" in result.text.lower() for result in results)\\n\\n        # Test with different number of results\\n        component.set(number_of_results=3)\\n        results = component.search_documents()\\n        assert len(results) == 3\\n\\n    def test_duplicate_handling(\\n        self, component_class: type[ChromaVectorStoreComponent], default_kwargs: dict[str, Any]\\n    ) -> None:\\n        \\\"\\\"\\\"Test handling of duplicate documents.\\\"\\\"\\\"\\n        # Create test data with duplicates\\n        test_data = [\\n            Data(text_key=\\\"text\\\", data={\\\"text\\\": \\\"This is a test document\\\"}),\\n            Data(text_key=\\\"text\\\", data={\\\"text\\\": \\\"This is a test document\\\"}),  # Duplicate with exact same data\\n            Data(text_key=\\\"text\\\", data={\\\"text\\\": \\\"This is another document\\\"}),\\n        ]\\n        default_kwargs[\\\"ingest_data\\\"] = test_data\\n        default_kwargs[\\\"allow_duplicates\\\"] = False\\n        default_kwargs[\\\"limit\\\"] = 100  # Set a high enough limit to get all documents\\n\\n        component: ChromaVectorStoreComponent = component_class().set(**default_kwargs)\\n        vector_store = component.build_vector_store()\\n\\n        # Get all documents\\n        results = vector_store.get(limit=100)\\n\\n        documents = results[\\\"documents\\\"]\\n\\n        # The documents are returned in a list structure\\n        assert len(documents) == 3  # All documents are added, even duplicates\\n\\n        # Count unique texts\\n        unique_texts = set(documents)\\n        assert len(unique_texts) == 2  # Should have 2 unique texts\\n\\n        # Test with allow_duplicates=True\\n        test_data = [\\n            Data(text_key=\\\"text\\\", data={\\\"text\\\": \\\"This is a test document\\\"}),\\n            Data(text_key=\\\"text\\\", data={\\\"text\\\": \\\"This is a test document\\\"}),  # Duplicate\\n        ]\\n        default_kwargs[\\\"ingest_data\\\"] = test_data\\n        default_kwargs[\\\"allow_duplicates\\\"] = True\\n        default_kwargs[\\\"collection_name\\\"] = \\\"test_collection_2\\\"  # Use a different collection name\\n\\n        component = component_class().set(**default_kwargs)\\n        vector_store = component.build_vector_store()\\n\\n        # Get all documents\\n        results = vector_store.get(limit=100)\\n        documents = results[\\\"documents\\\"]\\n\\n        # With allow_duplicates=True, we should have both documents\\n        assert len(documents) == 2\\n        assert all(\\\"test document\\\" in doc for doc in documents)\\n\\n        # Verify that we have the expected number of documents\\n        assert vector_store._collection.count() == 2\\n\\n    def test_chroma_collection_to_data(\\n        self, component_class: type[ChromaVectorStoreComponent], default_kwargs: dict[str, Any]\\n    ) -> None:\\n        \\\"\\\"\\\"Test the chroma_collection_to_data function.\\\"\\\"\\\"\\n        from lfx.base.vectorstores.utils import chroma_collection_to_data\\n\\n        # Create a collection with documents and metadata\\n        test_data = [\\n            Data(data={\\\"text\\\": \\\"Document 1\\\", \\\"metadata_field\\\": \\\"value1\\\"}),\\n            Data(data={\\\"text\\\": \\\"Document 2\\\", \\\"metadata_field\\\": \\\"value2\\\"}),\\n        ]\\n        default_kwargs[\\\"ingest_data\\\"] = test_data\\n        component: ChromaVectorStoreComponent = component_class().set(**default_kwargs)\\n        vector_store = component.build_vector_store()\\n\\n        # Get the collection data\\n        collection_dict = vector_store.get()\\n        data_objects = chroma_collection_to_data(collection_dict)\\n\\n        # Verify the conversion\\n        assert len(data_objects) == 2\\n        for data_obj in data_objects:\\n            assert isinstance(data_obj, Data)\\n            assert \\\"id\\\" in data_obj.data\\n            assert \\\"text\\\" in data_obj.data\\n            assert data_obj.data[\\\"text\\\"] in {\\\"Document 1\\\", \\\"Document 2\\\"}\\n            assert \\\"metadata_field\\\" in data_obj.data\\n            assert data_obj.data[\\\"metadata_field\\\"] in {\\\"value1\\\", \\\"value2\\\"}\\n\\n    def test_chroma_collection_to_data_without_metadata(\\n        self, component_class: type[ChromaVectorStoreComponent], default_kwargs: dict[str, Any]\\n    ) -> None:\\n        \\\"\\\"\\\"Test the chroma_collection_to_data function with documents that have no metadata.\\\"\\\"\\\"\\n        from lfx.base.vectorstores.utils import chroma_collection_to_data\\n\\n        # Create a collection with documents but no metadata\\n        test_data = [\\n            Data(data={\\\"text\\\": \\\"Simple document 1\\\"}),\\n            Data(data={\\\"text\\\": \\\"Simple document 2\\\"}),\\n        ]\\n        default_kwargs[\\\"ingest_data\\\"] = test_data\\n        component: ChromaVectorStoreComponent = component_class().set(**default_kwargs)\\n        vector_store = component.build_vector_store()\\n\\n        # Get the collection data\\n        collection_dict = vector_store.get()\\n        data_objects = chroma_collection_to_data(collection_dict)\\n\\n        # Verify the conversion\\n        assert len(data_objects) == 2\\n        for data_obj in data_objects:\\n            assert isinstance(data_obj, Data)\\n            assert \\\"id\\\" in data_obj.data\\n            assert \\\"text\\\" in data_obj.data\\n            assert data_obj.data[\\\"text\\\"] in {\\\"Simple document 1\\\", \\\"Simple document 2\\\"}\\n\\n    def test_chroma_collection_to_data_empty_collection(\\n        self, component_class: type[ChromaVectorStoreComponent], default_kwargs: dict[str, Any]\\n    ) -> None:\\n        \\\"\\\"\\\"Test the chroma_collection_to_data function with an empty collection.\\\"\\\"\\\"\\n        from lfx.base.vectorstores.utils import chroma_collection_to_data\\n\\n        # Create an empty collection\\n        component: ChromaVectorStoreComponent = component_class().set(**default_kwargs)\\n        vector_store = component.build_vector_store()\\n\\n        # Get the collection data\\n        collection_dict = vector_store.get()\\n        data_objects = chroma_collection_to_data(collection_dict)\\n\\n        # Verify the conversion\\n        assert len(data_objects) == 0\\n\\n    def test_metadata_filtering_with_complex_data(\\n        self, component_class: type[ChromaVectorStoreComponent], default_kwargs: dict[str, Any]\\n    ) -> None:\\n        \\\"\\\"\\\"Test that complex metadata is properly filtered and simple types are preserved.\\\"\\\"\\\"\\n        from langflow.base.vectorstores.utils import chroma_collection_to_data\\n\\n        # Create test data that covers the original error scenario and validation\\n        test_data = [\\n            Data(\\n                data={\\n                    \\\"text\\\": \\\"Document with mixed metadata\\\",\\n                    \\\"files\\\": [],  # This empty list was causing the original ChromaDB error\\n                    \\\"tags\\\": [\\\"tag1\\\", \\\"tag2\\\"],  # Lists should be filtered out\\n                    \\\"nested\\\": {\\\"key\\\": \\\"value\\\"},  # Nested objects should be filtered out\\n                    \\\"simple_string\\\": \\\"preserved\\\",\\n                    \\\"simple_int\\\": 42,\\n                    \\\"simple_bool\\\": True,\\n                    \\\"empty_string\\\": \\\"\\\",  # Edge case: empty but valid\\n                    \\\"zero_value\\\": 0,  # Edge case: falsy but valid\\n                }\\n            )\\n        ]\\n\\n        default_kwargs[\\\"ingest_data\\\"] = test_data\\n        default_kwargs[\\\"collection_name\\\"] = \\\"test_metadata_filtering\\\"\\n\\n        # This should not raise an error despite the complex metadata\\n        component: ChromaVectorStoreComponent = component_class().set(**default_kwargs)\\n        vector_store = component.build_vector_store()\\n\\n        # Verify document was added successfully\\n        collection_dict = vector_store.get()\\n        assert len(collection_dict[\\\"documents\\\"]) == 1\\n        assert \\\"Document with mixed metadata\\\" in collection_dict[\\\"documents\\\"][0]\\n\\n        # Verify metadata filtering: simple types preserved, complex types filtered out\\n        data_objects = chroma_collection_to_data(collection_dict)\\n        data_obj = data_objects[0]\\n\\n        # Simple types should be preserved\\n        assert data_obj.data[\\\"simple_string\\\"] == \\\"preserved\\\"\\n        assert data_obj.data[\\\"simple_int\\\"] == 42\\n        assert data_obj.data[\\\"simple_bool\\\"] is True\\n        assert data_obj.data[\\\"empty_string\\\"] == \\\"\\\"\\n        assert data_obj.data[\\\"zero_value\\\"] == 0\\n\\n        # Complex types should be filtered out\\n        assert \\\"files\\\" not in data_obj.data\\n        assert \\\"tags\\\" not in data_obj.data\\n        assert \\\"nested\\\" not in data_obj.data\\n\\n    def test_metadata_filtering_without_community(\\n        self, component_class: type[ChromaVectorStoreComponent], default_kwargs: dict[str, Any], monkeypatch\\n    ) -> None:\\n        \\\"\\\"\\\"Complex metadata must still be filtered when Community is unavailable.\\\"\\\"\\\"\\n        import builtins\\n\\n        original_import = builtins.__import__\\n\\n        def mock_import(name, *args, **kwargs):\\n            if name == \\\"langchain_community.vectorstores.utils\\\":\\n                error_msg = \\\"Mocked import error\\\"\\n                raise ImportError(error_msg)\\n            return original_import(name, *args, **kwargs)\\n\\n        monkeypatch.setattr(builtins, \\\"__import__\\\", mock_import)\\n\\n        # Include container and null metadata that Chroma cannot store.\\n        test_data = [Data(data={\\\"text\\\": \\\"Simple document\\\", \\\"simple_field\\\": \\\"simple_value\\\", \\\"nested\\\": [], \\\"null\\\": None})]\\n        default_kwargs[\\\"ingest_data\\\"] = test_data\\n        default_kwargs[\\\"collection_name\\\"] = \\\"test_fallback\\\"\\n\\n        # Filtering is independent of the retired dependency.\\n        component: ChromaVectorStoreComponent = component_class().set(**default_kwargs)\\n        vector_store = component.build_vector_store()\\n\\n        # Verify document was added\\n        collection_dict = vector_store.get()\\n        assert len(collection_dict[\\\"documents\\\"]) == 1\\n        assert \\\"Simple document\\\" in collection_dict[\\\"documents\\\"][0]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/vectorstores/test_mongodb_atlas.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b72cf9baf62b90ec267afb31fb014a2e3577f510fa6045178842cc2b2a286342\",\"content\":\"import os\\nimport time\\nfrom typing import Any\\nfrom unittest.mock import MagicMock\\n\\nimport pytest\\n\\npytest.importorskip(\\\"lfx_bundles\\\")\\n\\n# Import the module (not just the class) so the unit tests below can patch\\n# MongoDBAtlasVectorSearch on the exact module object the component's methods\\n# read their globals from. Since the bundle move, the same source file can be\\n# materialized under several module identities (lfx.components.mongodb.*,\\n# lfx_bundles.mongodb.*, _lfx_ext.official.mongodb.*) depending on what other\\n# tests in the worker imported first -- patching by dotted name can land on a\\n# different copy than the one this class was loaded from.\\nimport lfx.components.mongodb.mongodb_atlas as mongodb_atlas_mod\\nfrom langchain_community.embeddings.fake import DeterministicFakeEmbedding\\nfrom lfx.schema.data import Data\\nfrom pymongo.collection import Collection\\n\\nfrom tests.base import ComponentTestBaseWithoutClient, VersionComponentMapping\\n\\nMongoVectorStoreComponent = mongodb_atlas_mod.MongoVectorStoreComponent\\n\\n\\n@pytest.mark.api_key_required\\n@pytest.mark.skipif(\\n    not os.environ.get(\\\"MONGODB_ATLAS_URI\\\"), reason=\\\"Environment variable MONGODB_ATLAS_URI is not defined.\\\"\\n)\\nclass TestMongoVectorStoreComponent(ComponentTestBaseWithoutClient):\\n    @pytest.fixture\\n    def component_class(self) -> type[Any]:\\n        \\\"\\\"\\\"Return the component class to test.\\\"\\\"\\\"\\n        return MongoVectorStoreComponent\\n\\n    @pytest.fixture\\n    def default_kwargs(self) -> dict[str, Any]:\\n        \\\"\\\"\\\"Return the default kwargs for the component.\\\"\\\"\\\"\\n        return {\\n            \\\"mongodb_atlas_cluster_uri\\\": os.getenv(\\\"MONGODB_ATLAS_URI\\\"),\\n            \\\"db_name\\\": \\\"test_db\\\",\\n            \\\"collection_name\\\": \\\"test_collection\\\",\\n            \\\"index_name\\\": \\\"test_index\\\",\\n            \\\"enable_mtls\\\": False,\\n            \\\"embedding\\\": DeterministicFakeEmbedding(size=8),\\n            \\\"index_field\\\": \\\"embedding\\\",\\n            \\\"filter_field\\\": \\\"text\\\",\\n            \\\"number_dimensions\\\": 8,\\n            \\\"similarity\\\": \\\"cosine\\\",\\n            \\\"quantization\\\": \\\"scalar\\\",\\n            \\\"insert_mode\\\": \\\"append\\\",\\n            \\\"ingest_data\\\": [Data(data={\\\"text\\\": \\\"test data 1\\\"}), Data(data={\\\"text\\\": \\\"test data 2\\\"})],\\n        }\\n\\n    @pytest.fixture\\n    def file_names_mapping(self) -> list[VersionComponentMapping]:\\n        \\\"\\\"\\\"Return the file names mapping for different versions.\\\"\\\"\\\"\\n        return [\\n            {\\\"version\\\": \\\"1.0.19\\\", \\\"module\\\": \\\"vectorstores\\\", \\\"file_name\\\": \\\"MongoDBAtlasVector\\\"},\\n            {\\\"version\\\": \\\"1.1.0\\\", \\\"module\\\": \\\"vectorstores\\\", \\\"file_name\\\": \\\"mongodb_atlas\\\"},\\n            {\\\"version\\\": \\\"1.1.1\\\", \\\"module\\\": \\\"vectorstores\\\", \\\"file_name\\\": \\\"mongodb_atlas\\\"},\\n        ]\\n\\n    def __create_search_index(\\n        self, component_class: type[MongoVectorStoreComponent], collection: Collection, default_kwargs: dict[str, Any]\\n    ) -> None:\\n        \\\"\\\"\\\"Create a vector search index if it doesn't exist.\\\"\\\"\\\"\\n        component_class().set(**default_kwargs).verify_search_index(collection)\\n\\n        # Verify index was created\\n        indexes = collection.list_search_indexes()\\n        index_names = {idx[\\\"name\\\"]: idx[\\\"type\\\"] for idx in indexes}\\n        index_type = index_names.get(default_kwargs[\\\"index_name\\\"])\\n        assert default_kwargs[\\\"index_name\\\"] in index_names\\n        assert index_type == \\\"vectorSearch\\\"\\n\\n    def test_create_db(self, component_class: type[MongoVectorStoreComponent], default_kwargs: dict[str, Any]) -> None:\\n        \\\"\\\"\\\"Test creating a MongoDB Atlas vector store.\\\"\\\"\\\"\\n        component: MongoVectorStoreComponent = component_class().set(**default_kwargs)\\n        vector_store = component.build_vector_store()\\n        assert vector_store is not None\\n        # Access MongoDB collection through the vector store's internal client\\n        assert vector_store._collection.name == default_kwargs[\\\"collection_name\\\"]\\n        assert vector_store._index_name == default_kwargs[\\\"index_name\\\"]\\n\\n    def test_create_collection_with_data(\\n        self, component_class: type[MongoVectorStoreComponent], default_kwargs: dict[str, Any]\\n    ) -> None:\\n        \\\"\\\"\\\"Test creating a collection with data.\\\"\\\"\\\"\\n        test_texts = [\\\"test data 1\\\", \\\"test data 2\\\", \\\"something completely different\\\"]\\n        default_kwargs[\\\"ingest_data\\\"] = [Data(data={\\\"text\\\": text}) for text in test_texts]\\n        default_kwargs[\\\"insert_mode\\\"] = \\\"overwrite\\\"\\n\\n        component: MongoVectorStoreComponent = component_class().set(**default_kwargs)\\n        vector_store = component.build_vector_store()\\n\\n        # Verify collection exists and has the correct data\\n        collection = vector_store._collection\\n        assert collection.name == default_kwargs[\\\"collection_name\\\"]\\n        assert collection.count_documents({}) == len(test_texts)\\n\\n    def test_similarity_search(\\n        self, component_class: type[MongoVectorStoreComponent], default_kwargs: dict[str, Any]\\n    ) -> None:\\n        \\\"\\\"\\\"Test the similarity search functionality.\\\"\\\"\\\"\\n        # Create test data with distinct topics\\n        test_data = [\\n            \\\"The quick brown fox jumps over the lazy dog\\\",\\n            \\\"Python is a popular programming language\\\",\\n            \\\"Machine learning models process data\\\",\\n            \\\"The lazy dog sleeps all day long\\\",\\n        ]\\n        default_kwargs[\\\"ingest_data\\\"] = [Data(data={\\\"text\\\": text, \\\"metadata\\\": {}}) for text in test_data]\\n        default_kwargs[\\\"number_of_results\\\"] = 2\\n        default_kwargs[\\\"insert_mode\\\"] = \\\"overwrite\\\"\\n\\n        # Create and initialize the component\\n        component: MongoVectorStoreComponent = component_class().set(**default_kwargs)\\n\\n        # Build the vector store first to ensure data is ingested\\n        vector_store = component.build_vector_store()\\n        assert vector_store is not None\\n\\n        # Verify documents were stored with embeddings\\n        documents = list(vector_store._collection.find({}))\\n        assert len(documents) == len(test_data)\\n        for doc in documents:\\n            assert \\\"embedding\\\" in doc\\n            assert isinstance(doc[\\\"embedding\\\"], list)\\n            assert len(doc[\\\"embedding\\\"]) == 8  # Should match our embedding size\\n\\n        self.__create_search_index(component_class, vector_store._collection, default_kwargs)\\n\\n        # Verify index was created\\n        indexes = vector_store._collection.list_search_indexes()\\n        index_names = [idx[\\\"name\\\"] for idx in indexes]\\n        assert default_kwargs[\\\"index_name\\\"] in index_names\\n\\n        # Test similarity search through the component\\n        component.set(search_query=\\\"dog\\\")\\n        results = component.search_documents()\\n        time.sleep(5)  # wait the results come from API\\n\\n        assert len(results) == 2, \\\"Expected 2 results for 'lazy dog' query\\\"\\n        # The most relevant results should be about dogs\\n        assert any(\\\"dog\\\" in result.data[\\\"text\\\"].lower() for result in results)\\n\\n        # Test with different number of results\\n        component.set(number_of_results=3)\\n        results = component.search_documents()\\n        assert len(results) == 3\\n        assert all(\\\"text\\\" in result.data for result in results)\\n\\n    def test_mtls_configuration(\\n        self, component_class: type[MongoVectorStoreComponent], default_kwargs: dict[str, Any]\\n    ) -> None:\\n        \\\"\\\"\\\"Test mTLS configuration handling.\\\"\\\"\\\"\\n        # Test with invalid mTLS configuration\\n        default_kwargs[\\\"enable_mtls\\\"] = True\\n        default_kwargs[\\\"mongodb_atlas_client_cert\\\"] = \\\"invalid-cert-content\\\"\\n\\n        component: MongoVectorStoreComponent = component_class().set(**default_kwargs)\\n        with pytest.raises(ValueError, match=\\\"Failed to connect to MongoDB Atlas\\\"):\\n            component.build_vector_store()\\n\\n    def test_empty_search_query(\\n        self, component_class: type[MongoVectorStoreComponent], default_kwargs: dict[str, Any]\\n    ) -> None:\\n        \\\"\\\"\\\"Test search with empty query.\\\"\\\"\\\"\\n        default_kwargs[\\\"insert_mode\\\"] = \\\"overwrite\\\"\\n        component: MongoVectorStoreComponent = component_class().set(**default_kwargs)\\n\\n        # Test with empty search query\\n        component.set(search_query=\\\"\\\")\\n        results = component.search_documents()\\n        assert len(results) == 0\\n\\n    def test_metadata_handling(\\n        self, component_class: type[MongoVectorStoreComponent], default_kwargs: dict[str, Any]\\n    ) -> None:\\n        \\\"\\\"\\\"Test handling of document metadata.\\\"\\\"\\\"\\n        # Create test data with metadata\\n        test_data = [\\n            Data(data={\\\"text\\\": \\\"Document 1\\\", \\\"metadata\\\": {\\\"category\\\": \\\"test\\\", \\\"priority\\\": 1}}),\\n            Data(data={\\\"text\\\": \\\"Document 2\\\", \\\"metadata\\\": {\\\"category\\\": \\\"test\\\", \\\"priority\\\": 2}}),\\n        ]\\n        default_kwargs[\\\"ingest_data\\\"] = test_data\\n        default_kwargs[\\\"collection_name\\\"] = \\\"test_collection_metadata\\\"\\n\\n        component: MongoVectorStoreComponent = component_class().set(**default_kwargs)\\n        vector_store = component.build_vector_store()\\n\\n        self.__create_search_index(component_class, vector_store._collection, default_kwargs)\\n\\n        # Test search and verify metadata is preserved\\n        component.set(search_query=\\\"Document\\\", number_of_results=2)\\n        results = component.search_documents()\\n\\n        assert len(results) == 2\\n        for result in results:\\n            assert \\\"category\\\" in result.data[\\\"metadata\\\"]\\n            assert result.data[\\\"metadata\\\"][\\\"category\\\"] == \\\"test\\\"\\n            assert \\\"priority\\\" in result.data[\\\"metadata\\\"]\\n            assert isinstance(result.data[\\\"metadata\\\"][\\\"priority\\\"], int)\\n\\n    def test_error_handling(\\n        self, component_class: type[MongoVectorStoreComponent], default_kwargs: dict[str, Any]\\n    ) -> None:\\n        \\\"\\\"\\\"Test error handling for invalid configurations.\\\"\\\"\\\"\\n        component: MongoVectorStoreComponent = component_class().set(**default_kwargs)\\n\\n        # Test with non-existent database\\n        default_kwargs[\\\"mongodb_atlas_cluster_uri\\\"] = os.getenv(\\\"MONGODB_ATLAS_URI\\\")\\n        default_kwargs[\\\"db_name\\\"] = \\\"nonexistent_db\\\"\\n        component = component_class().set(**default_kwargs)\\n\\n        # This should not raise an error as MongoDB creates databases and collections on demand\\n        vector_store = component.build_vector_store()\\n        assert vector_store is not None\\n\\n\\n# CI-runnable unit tests (no live MongoDB Atlas required). These cover the\\n# langchain-community 0.4.2 migration: MongoDBAtlasVectorSearch moved out of\\n# langchain_community.vectorstores into the standalone langchain_mongodb package.\\n# The network boundary (pymongo client + the store class) is mocked.\\ndef _mock_component(mocker, **overrides) -> tuple[MongoVectorStoreComponent, MagicMock, MagicMock]:\\n    mock_client = MagicMock()\\n    mocker.patch(\\\"pymongo.MongoClient\\\", return_value=mock_client)\\n    mock_store_cls = mocker.patch.object(mongodb_atlas_mod, \\\"MongoDBAtlasVectorSearch\\\")\\n    kwargs = {\\n        \\\"mongodb_atlas_cluster_uri\\\": \\\"mongodb://localhost:27017\\\",\\n        \\\"db_name\\\": \\\"test_db\\\",\\n        \\\"collection_name\\\": \\\"test_collection\\\",\\n        \\\"index_name\\\": \\\"test_index\\\",\\n        \\\"enable_mtls\\\": False,\\n    }\\n    kwargs.update(overrides)\\n    component = MongoVectorStoreComponent(**kwargs)\\n    component.embedding = MagicMock()\\n    return component, mock_client, mock_store_cls\\n\\n\\ndef test_mongodb_initialization():\\n    component = MongoVectorStoreComponent()\\n    assert component.display_name == \\\"MongoDB Atlas\\\"\\n    assert component.icon == \\\"MongoDB\\\"\\n    # The class name / identifier must remain stable: it keys saved flows.\\n    assert component.name == \\\"MongoDBAtlasVector\\\"\\n\\n\\ndef test_mongodb_build_vector_store_constructs_atlas_search(mocker):\\n    component, mock_client, mock_store_cls = _mock_component(mocker)\\n\\n    store = component.build_vector_store()\\n\\n    # No ingest data -> the store is constructed directly (no from_documents).\\n    mock_store_cls.assert_called_once()\\n    mock_store_cls.from_documents.assert_not_called()\\n    _, kwargs = mock_store_cls.call_args\\n    assert kwargs[\\\"collection\\\"] is mock_client[\\\"test_db\\\"][\\\"test_collection\\\"]\\n    assert kwargs[\\\"index_name\\\"] == \\\"test_index\\\"\\n    assert kwargs[\\\"embedding\\\"] is component.embedding\\n    assert store is mock_store_cls.return_value\\n\\n\\ndef test_mongodb_build_vector_store_with_documents_uses_from_documents(mocker):\\n    component, mock_client, mock_store_cls = _mock_component(mocker, insert_mode=\\\"append\\\")\\n    component.ingest_data = [Data(data={\\\"text\\\": \\\"hello\\\"})]\\n\\n    component.build_vector_store()\\n\\n    mock_store_cls.from_documents.assert_called_once()\\n    _, kwargs = mock_store_cls.from_documents.call_args\\n    assert kwargs[\\\"collection\\\"] is mock_client[\\\"test_db\\\"][\\\"test_collection\\\"]\\n    assert kwargs[\\\"index_name\\\"] == \\\"test_index\\\"\\n\\n\\ndef test_mongodb_overwrite_insert_mode_clears_collection(mocker):\\n    component, mock_client, mock_store_cls = _mock_component(mocker, insert_mode=\\\"overwrite\\\")\\n    component.ingest_data = [Data(data={\\\"text\\\": \\\"hello\\\"})]\\n\\n    component.build_vector_store()\\n\\n    collection = mock_client.__getitem__.return_value.__getitem__.return_value\\n    collection.delete_many.assert_called_once_with({})\\n    mock_store_cls.from_documents.assert_called_once()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/vectorstores/test_qdrant_vector_store_component.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c5559cf56f6c7501cb5e27f4f2d0af06f6e965661ea8f0d1d0092ad4aa25b522\",\"content\":\"\\\"\\\"\\\"Unit tests for the Qdrant vector store component.\\n\\nFocuses on the stable, deterministic ID generation introduced for #12641\\nso re-ingesting the same content does not create duplicates.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport uuid\\nfrom datetime import datetime, timezone\\nfrom decimal import Decimal\\nfrom unittest.mock import MagicMock, patch\\n\\nimport pytest\\n\\npytest.importorskip(\\\"lfx_bundles\\\")\\n\\nfrom langchain_core.documents import Document\\nfrom langchain_core.embeddings import Embeddings\\nfrom lfx.components.qdrant import QdrantVectorStoreComponent\\nfrom lfx.schema.data import Data\\n\\n\\ndef _make_component(documents: list[Document]) -> QdrantVectorStoreComponent:\\n    return QdrantVectorStoreComponent().set(\\n        collection_name=\\\"test_collection\\\",\\n        embedding=MagicMock(spec=Embeddings),\\n        ingest_data=[Data(text=doc.page_content, data=doc.metadata) for doc in documents],\\n    )\\n\\n\\ndef _captured_ids(documents: list[Document]) -> list[str]:\\n    \\\"\\\"\\\"Run build_vector_store with QdrantVectorStore.from_documents patched and return the ids passed in.\\\"\\\"\\\"\\n    component = _make_component(documents)\\n\\n    captured: dict[str, list[str]] = {}\\n\\n    def fake_from_documents(_docs, *, embedding, ids, **_kwargs):  # noqa: ARG001\\n        captured[\\\"ids\\\"] = ids\\n        return MagicMock()\\n\\n    with patch(\\\"lfx.components.qdrant.qdrant.QdrantVectorStore.from_documents\\\", side_effect=fake_from_documents):\\n        component.build_vector_store()\\n\\n    return captured[\\\"ids\\\"]\\n\\n\\ndef test_qdrant_ids_are_deterministic_uuid5() -> None:\\n    \\\"\\\"\\\"Same content + metadata must always produce the same UUID.\\\"\\\"\\\"\\n    docs = [Document(page_content=\\\"hello world\\\", metadata={\\\"source\\\": \\\"a.txt\\\", \\\"page\\\": 1})]\\n\\n    first = _captured_ids(docs)\\n    second = _captured_ids(docs)\\n\\n    assert first == second\\n    # UUID5 strings: 36 chars including hyphens, version nibble == '5'.\\n    parsed = uuid.UUID(first[0])\\n    assert parsed.version == 5\\n\\n\\ndef test_qdrant_ids_are_metadata_order_independent() -> None:\\n    \\\"\\\"\\\"Two docs with identical content and metadata in different insertion order share an ID.\\\"\\\"\\\"\\n    doc_a = Document(page_content=\\\"same text\\\", metadata={\\\"a\\\": 1, \\\"b\\\": 2, \\\"nested\\\": {\\\"x\\\": 1, \\\"y\\\": 2}})\\n    doc_b = Document(page_content=\\\"same text\\\", metadata={\\\"nested\\\": {\\\"y\\\": 2, \\\"x\\\": 1}, \\\"b\\\": 2, \\\"a\\\": 1})\\n\\n    ids = _captured_ids([doc_a, doc_b])\\n\\n    assert ids[0] == ids[1]\\n\\n\\ndef test_qdrant_ids_differ_for_different_content() -> None:\\n    docs = [\\n        Document(page_content=\\\"first\\\", metadata={\\\"source\\\": \\\"a\\\"}),\\n        Document(page_content=\\\"second\\\", metadata={\\\"source\\\": \\\"a\\\"}),\\n    ]\\n\\n    ids = _captured_ids(docs)\\n\\n    assert ids[0] != ids[1]\\n\\n\\ndef test_qdrant_ids_handle_non_primitive_metadata() -> None:\\n    \\\"\\\"\\\"Non-primitive metadata (datetime, Decimal) must serialize without raising and stay deterministic.\\\"\\\"\\\"\\n    ts = datetime(2026, 5, 11, 12, 0, tzinfo=timezone.utc)\\n    docs = [Document(page_content=\\\"payload\\\", metadata={\\\"ts\\\": ts, \\\"price\\\": Decimal(\\\"9.99\\\")})]\\n\\n    first = _captured_ids(docs)\\n    second = _captured_ids(docs)\\n\\n    assert first == second\\n    uuid.UUID(first[0])  # raises if not a valid UUID\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/vectorstores/test_weaviate.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"75c8564b415f9dd0068b0ec0c57d2862e1336f4488f078b6f0a30b60f32e5457\",\"content\":\"\\\"\\\"\\\"Unit tests for the Weaviate vector store component.\\n\\nThese exercise the langchain-community 0.4.2 migration: the component moved off\\n``langchain_community.vectorstores.Weaviate`` (v3 client) to the standalone\\n``langchain_weaviate.WeaviateVectorStore`` backed by the Weaviate v4 client. The\\nnetwork boundary (the v4 ``connect_*`` helpers and the store class) is mocked so\\nthe migration logic runs in CI without a live Weaviate instance.\\n\\\"\\\"\\\"\\n\\nimport sys\\nfrom unittest.mock import MagicMock\\n\\nimport pytest\\n\\npytest.importorskip(\\\"lfx_bundles\\\")\\n\\nfrom lfx.components.weaviate.weaviate import WeaviateVectorStoreComponent\\nfrom lfx.schema.data import Data\\n\\n# The component moved into lfx-bundles, so ``weaviate.py`` is reachable under several\\n# module identities (the ``lfx.components.weaviate.weaviate`` shim, the canonical\\n# ``lfx_bundles.weaviate.weaviate``, and the runtime ``_lfx_ext.*`` ext-loader copy).\\n# Patch on the module the imported class actually lives in: a fixed string target like\\n# \\\"lfx.components.weaviate.weaviate.WeaviateVectorStore\\\" misses (mock \\\"called 0 times\\\")\\n# when an earlier test in the suite causes the class to resolve to a different identity.\\n_WEAVIATE_MODULE = sys.modules[WeaviateVectorStoreComponent.__module__]\\n\\n\\ndef test_initialization():\\n    component = WeaviateVectorStoreComponent()\\n    assert component.display_name == \\\"Weaviate\\\"\\n    assert component.icon == \\\"Weaviate\\\"\\n    # The class name / identifier must remain stable: it keys saved flows.\\n    assert component.name == \\\"Weaviate\\\"\\n\\n\\ndef test_build_vector_store_requires_capitalized_index():\\n    component = WeaviateVectorStoreComponent(url=\\\"http://localhost:8080\\\", index_name=\\\"lowercase\\\")\\n    with pytest.raises(ValueError, match=\\\"capitalized\\\"):\\n        component.build_vector_store()\\n\\n\\ndef test_connect_client_custom(mocker):\\n    \\\"\\\"\\\"A self-hosted URL routes to the v4 connect_to_custom with derived host/port.\\\"\\\"\\\"\\n    mock_connect = mocker.patch(\\\"weaviate.connect_to_custom\\\", return_value=MagicMock())\\n    component = WeaviateVectorStoreComponent(url=\\\"http://localhost:8080\\\", index_name=\\\"Test\\\")\\n\\n    client = component._connect_client()\\n\\n    mock_connect.assert_called_once()\\n    _, kwargs = mock_connect.call_args\\n    assert kwargs[\\\"http_host\\\"] == \\\"localhost\\\"\\n    assert kwargs[\\\"http_port\\\"] == 8080\\n    assert kwargs[\\\"http_secure\\\"] is False\\n    assert kwargs[\\\"grpc_host\\\"] == \\\"localhost\\\"\\n    assert kwargs[\\\"grpc_port\\\"] == 50051\\n    assert kwargs[\\\"auth_credentials\\\"] is None\\n    assert client is mock_connect.return_value\\n\\n\\ndef test_connect_client_cloud(mocker):\\n    \\\"\\\"\\\"A Weaviate Cloud URL routes to connect_to_weaviate_cloud (gRPC resolved internally).\\\"\\\"\\\"\\n    mock_cloud = mocker.patch(\\\"weaviate.connect_to_weaviate_cloud\\\", return_value=MagicMock())\\n    mock_auth = mocker.patch.object(_WEAVIATE_MODULE, \\\"AuthApiKey\\\", return_value=\\\"AUTH\\\")\\n    component = WeaviateVectorStoreComponent(\\n        url=\\\"https://my-cluster.weaviate.network\\\",\\n        index_name=\\\"Test\\\",\\n        api_key=\\\"test-key\\\",  # pragma: allowlist secret\\n    )\\n\\n    client = component._connect_client()\\n\\n    mock_cloud.assert_called_once_with(cluster_url=\\\"https://my-cluster.weaviate.network\\\", auth_credentials=\\\"AUTH\\\")\\n    mock_auth.assert_called_once_with(\\\"test-key\\\")\\n    assert client is mock_cloud.return_value\\n\\n\\ndef test_connect_client_wraps_errors(mocker):\\n    mocker.patch(\\\"weaviate.connect_to_custom\\\", side_effect=RuntimeError(\\\"boom\\\"))\\n    component = WeaviateVectorStoreComponent(url=\\\"http://localhost:8080\\\", index_name=\\\"Test\\\")\\n\\n    with pytest.raises(ValueError, match=\\\"Failed to connect to Weaviate\\\"):\\n        component._connect_client()\\n\\n\\ndef test_build_vector_store_without_documents(mocker):\\n    mock_client = MagicMock()\\n    mocker.patch.object(WeaviateVectorStoreComponent, \\\"_connect_client\\\", return_value=mock_client)\\n    mock_store_cls = mocker.patch.object(_WEAVIATE_MODULE, \\\"WeaviateVectorStore\\\", return_value=MagicMock())\\n    fake_embedding = MagicMock()\\n\\n    component = WeaviateVectorStoreComponent(url=\\\"http://localhost:8080\\\", index_name=\\\"Test\\\")\\n    component.embedding = fake_embedding\\n\\n    store = component.build_vector_store()\\n\\n    mock_store_cls.assert_called_once_with(\\n        client=mock_client,\\n        index_name=\\\"Test\\\",\\n        text_key=\\\"text\\\",\\n        embedding=fake_embedding,\\n    )\\n    mock_store_cls.from_documents.assert_not_called()\\n    assert store is mock_store_cls.return_value\\n\\n\\ndef test_build_vector_store_with_documents_uses_from_documents(mocker):\\n    mock_client = MagicMock()\\n    mocker.patch.object(WeaviateVectorStoreComponent, \\\"_connect_client\\\", return_value=mock_client)\\n    mock_store_cls = mocker.patch.object(_WEAVIATE_MODULE, \\\"WeaviateVectorStore\\\")\\n    fake_embedding = MagicMock()\\n\\n    component = WeaviateVectorStoreComponent(url=\\\"http://localhost:8080\\\", index_name=\\\"Test\\\")\\n    component.embedding = fake_embedding\\n    component.ingest_data = [Data(data={\\\"text\\\": \\\"hello\\\"})]\\n\\n    component.build_vector_store()\\n\\n    mock_store_cls.from_documents.assert_called_once()\\n    _, kwargs = mock_store_cls.from_documents.call_args\\n    assert kwargs[\\\"client\\\"] is mock_client\\n    assert kwargs[\\\"index_name\\\"] == \\\"Test\\\"\\n    assert kwargs[\\\"text_key\\\"] == \\\"text\\\"\\n    assert kwargs[\\\"embedding\\\"] is fake_embedding\\n\\n\\ndef test_search_documents_empty_query_returns_empty(mocker):\\n    mocker.patch.object(WeaviateVectorStoreComponent, \\\"build_vector_store\\\", return_value=MagicMock())\\n    component = WeaviateVectorStoreComponent(url=\\\"http://localhost:8080\\\", index_name=\\\"Test\\\")\\n    component.search_query = \\\"\\\"\\n\\n    assert component.search_documents() == []\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/core/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"5ea9551222a9c0e15cfe841c056d475622de383a16147533782ce35738482f85\",\"content\":\"\\\"\\\"\\\"Core tests package.\\\"\\\"\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/core/test_celery_app.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"bcb89a3c83096092923ad40ba8d93da496ac0fbe0eca5bb568471026519189ef\",\"content\":\"\\\"\\\"\\\"Unit tests for langflow.core.celery_app module.\\\"\\\"\\\"\\n\\nfrom unittest.mock import MagicMock, patch\\n\\nimport pytest\\n\\n\\n@pytest.mark.skip(reason=\\\"Skipping celery app tests as they cover unused code\\\")\\nclass TestMakeCelery:\\n    \\\"\\\"\\\"Unit tests for the make_celery function.\\\"\\\"\\\"\\n\\n    def test_make_celery_creates_celery_instance(self):\\n        \\\"\\\"\\\"Test that make_celery creates a functional Celery instance.\\\"\\\"\\\"\\n        from langflow.core.celery_app import make_celery\\n\\n        # Create a mock config module\\n        mock_config = MagicMock()\\n        mock_config.broker_url = \\\"memory://\\\"\\n        mock_config.result_backend = \\\"cache+memory://\\\"\\n        mock_config.accept_content = [\\\"json\\\"]\\n\\n        # Mock the import of the config module\\n        with patch.dict(\\\"sys.modules\\\", {\\\"langflow.core.celeryconfig\\\": mock_config}):\\n            # Act - Create a real Celery instance\\n            celery_app = make_celery(\\\"test_app\\\", \\\"langflow.core.celeryconfig\\\")\\n\\n            # Assert - Test actual functionality\\n            assert celery_app.main == \\\"test_app\\\"\\n            assert hasattr(celery_app, \\\"config_from_object\\\")\\n            assert hasattr(celery_app, \\\"send_task\\\")\\n            assert hasattr(celery_app, \\\"control\\\")\\n\\n            # Verify the app can be used (basic functionality)\\n            assert celery_app.conf.broker_url == \\\"memory://\\\"\\n            assert celery_app.conf.result_backend == \\\"cache+memory://\\\"\\n\\n    def test_make_celery_configures_from_object(self):\\n        \\\"\\\"\\\"Test that configuration is actually applied to the Celery instance.\\\"\\\"\\\"\\n        from langflow.core.celery_app import make_celery\\n\\n        # Create a mock config module with specific values\\n        mock_config = MagicMock()\\n        mock_config.broker_url = \\\"redis://test:6379/0\\\"\\n        mock_config.result_backend = \\\"redis://test:6379/0\\\"\\n        mock_config.accept_content = [\\\"json\\\", \\\"pickle\\\"]\\n        mock_config.task_serializer = \\\"json\\\"\\n\\n        with patch.dict(\\\"sys.modules\\\", {\\\"langflow.core.celeryconfig\\\": mock_config}):\\n            celery_app = make_celery(\\\"test_app\\\", \\\"langflow.core.celeryconfig\\\")\\n\\n            # Verify configuration was actually applied\\n            assert celery_app.conf.broker_url == \\\"redis://test:6379/0\\\"\\n            assert celery_app.conf.result_backend == \\\"redis://test:6379/0\\\"\\n            assert celery_app.conf.accept_content == [\\\"json\\\", \\\"pickle\\\"]\\n\\n    def test_make_celery_sets_task_routes(self):\\n        \\\"\\\"\\\"Test that different app names create different Celery instances.\\\"\\\"\\\"\\n        from langflow.core.celery_app import make_celery\\n\\n        mock_config = MagicMock()\\n        mock_config.broker_url = \\\"memory://\\\"\\n        mock_config.result_backend = \\\"cache+memory://\\\"\\n        mock_config.accept_content = [\\\"json\\\"]\\n\\n        with patch.dict(\\\"sys.modules\\\", {\\\"langflow.core.celeryconfig\\\": mock_config}):\\n            app1 = make_celery(\\\"app1\\\", \\\"langflow.core.celeryconfig\\\")\\n            app2 = make_celery(\\\"app2\\\", \\\"langflow.core.celeryconfig\\\")\\n\\n            # Different apps should have different main names\\n            assert app1.main == \\\"app1\\\"\\n            assert app2.main == \\\"app2\\\"\\n            assert app1 is not app2\\n\\n    def test_make_celery_returns_celery_instance(self):\\n        \\\"\\\"\\\"Test that the returned Celery app can perform basic operations.\\\"\\\"\\\"\\n        from langflow.core.celery_app import make_celery\\n\\n        mock_config = MagicMock()\\n        mock_config.broker_url = \\\"memory://\\\"\\n        mock_config.result_backend = \\\"cache+memory://\\\"\\n        mock_config.accept_content = [\\\"json\\\"]\\n\\n        with patch.dict(\\\"sys.modules\\\", {\\\"langflow.core.celeryconfig\\\": mock_config}):\\n            celery_app = make_celery(\\\"test_app\\\", \\\"langflow.core.celeryconfig\\\")\\n\\n            # Test that the app can be inspected\\n            assert celery_app.main == \\\"test_app\\\"\\n\\n            # Test that it has the expected Celery interface\\n            assert hasattr(celery_app, \\\"send_task\\\")\\n            assert hasattr(celery_app, \\\"control\\\")\\n            assert hasattr(celery_app, \\\"conf\\\")\\n\\n            # Test that configuration is accessible\\n            assert hasattr(celery_app.conf, \\\"broker_url\\\")\\n            assert hasattr(celery_app.conf, \\\"result_backend\\\")\\n\\n    def test_make_celery_with_different_app_names(self):\\n        \\\"\\\"\\\"Test that the Celery app can work with actual task definitions.\\\"\\\"\\\"\\n        from langflow.core.celery_app import make_celery\\n\\n        mock_config = MagicMock()\\n        mock_config.broker_url = \\\"memory://\\\"\\n        mock_config.result_backend = \\\"cache+memory://\\\"\\n        mock_config.accept_content = [\\\"json\\\"]\\n\\n        with patch.dict(\\\"sys.modules\\\", {\\\"langflow.core.celeryconfig\\\": mock_config}):\\n            celery_app = make_celery(\\\"test_app\\\", \\\"langflow.core.celeryconfig\\\")\\n\\n            # Define a simple task\\n            @celery_app.task\\n            def test_task(x, y):\\n                return x + y\\n\\n            # Test that the task is registered (Celery uses full module path)\\n            # The task will be registered with the full module path\\n            task_found = False\\n            for task_name in celery_app.tasks:\\n                if task_name.endswith(\\\".test_task\\\"):\\n                    task_found = True\\n                    task_info = celery_app.tasks[task_name]\\n                    assert task_info.name == task_name\\n                    break\\n\\n            assert task_found, \\\"test_task should be registered in celery_app.tasks\\\"\\n\\n    def test_make_celery_with_different_configs(self):\\n        \\\"\\\"\\\"Test that make_celery works with different configuration strings.\\\"\\\"\\\"\\n        from langflow.core.celery_app import make_celery\\n\\n        # Test with different config modules\\n        mock_config1 = MagicMock()\\n        mock_config1.broker_url = \\\"redis://test1:6379/0\\\"\\n        mock_config1.result_backend = \\\"redis://test1:6379/0\\\"\\n        mock_config1.accept_content = [\\\"json\\\"]\\n\\n        mock_config2 = MagicMock()\\n        mock_config2.broker_url = \\\"redis://test2:6379/0\\\"\\n        mock_config2.result_backend = \\\"redis://test2:6379/0\\\"\\n        mock_config2.accept_content = [\\\"pickle\\\"]\\n\\n        with patch.dict(\\\"sys.modules\\\", {\\\"langflow.core.celeryconfig\\\": mock_config1}):\\n            app1 = make_celery(\\\"test_app\\\", \\\"langflow.core.celeryconfig\\\")\\n            assert app1.conf.broker_url == \\\"redis://test1:6379/0\\\"\\n\\n        with patch.dict(\\\"sys.modules\\\", {\\\"langflow.core.celeryconfig\\\": mock_config2}):\\n            app2 = make_celery(\\\"test_app\\\", \\\"langflow.core.celeryconfig\\\")\\n            assert app2.conf.broker_url == \\\"redis://test2:6379/0\\\"\\n\\n    def test_make_celery_function_signature(self):\\n        \\\"\\\"\\\"Test that make_celery function has the expected signature.\\\"\\\"\\\"\\n        import inspect\\n\\n        from langflow.core.celery_app import make_celery\\n\\n        # Assert\\n        sig = inspect.signature(make_celery)\\n        params = list(sig.parameters.keys())\\n        assert len(params) == 2\\n        assert \\\"app_name\\\" in params\\n        assert \\\"config\\\" in params\\n\\n    def test_make_celery_docstring(self):\\n        \\\"\\\"\\\"Test that make_celery function exists and is callable.\\\"\\\"\\\"\\n        from langflow.core.celery_app import make_celery\\n\\n        # Assert\\n        # The function exists and is callable\\n        assert callable(make_celery)\\n        assert make_celery.__name__ == \\\"make_celery\\\"\\n\\n    def test_make_celery_error_handling(self):\\n        \\\"\\\"\\\"Test that make_celery function handles errors appropriately.\\\"\\\"\\\"\\n        from langflow.core.celery_app import make_celery\\n\\n        # Test with invalid config that causes Celery to fail\\n        with patch(\\\"langflow.core.celery_app.Celery\\\") as mock_celery_class:\\n            mock_celery_class.side_effect = Exception(\\\"Celery creation failed\\\")\\n\\n            with pytest.raises(Exception, match=\\\"Celery creation failed\\\"):\\n                make_celery(\\\"test_app\\\", \\\"test.config\\\")\\n\\n    def test_make_celery_configuration_application(self):\\n        \\\"\\\"\\\"Test that the module-level celery_app instance is created correctly.\\\"\\\"\\\"\\n        # This tests the actual instance created at module level\\n        from langflow.core.celery_app import celery_app\\n\\n        # Should be a Celery instance\\n        assert hasattr(celery_app, \\\"main\\\")\\n        assert hasattr(celery_app, \\\"conf\\\")\\n        assert hasattr(celery_app, \\\"send_task\\\")\\n\\n        # Should have the expected app name\\n        assert celery_app.main == \\\"langflow\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/core/test_celeryconfig.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"fc7b2013d1a091a49bb600e1e344671b09c505e0eeadf74d837e7d643341eb9f\",\"content\":\"\\\"\\\"\\\"Unit tests for langflow.core.celeryconfig module.\\\"\\\"\\\"\\n\\nimport importlib\\n\\nimport pytest\\n\\n# Import the module to test\\nfrom langflow.core import celeryconfig\\n\\n\\n@pytest.fixture(autouse=True)\\ndef _restore_celeryconfig_after_test(monkeypatch):\\n    yield\\n    monkeypatch.undo()\\n    importlib.reload(celeryconfig)\\n\\n\\nclass TestCeleryConfigAcceptContent:\\n    \\\"\\\"\\\"Unit tests for accept_content configuration.\\\"\\\"\\\"\\n\\n    def test_accept_content_configuration(self):\\n        \\\"\\\"\\\"Test that accept_content is set to the expected values.\\\"\\\"\\\"\\n        # This should be consistent regardless of environment\\n        expected_content = [\\\"json\\\", \\\"pickle\\\"]\\n        assert celeryconfig.accept_content == expected_content\\n\\n    def test_accept_content_types(self):\\n        \\\"\\\"\\\"Test that accept_content contains the expected content types.\\\"\\\"\\\"\\n        assert \\\"json\\\" in celeryconfig.accept_content\\n        assert \\\"pickle\\\" in celeryconfig.accept_content\\n        assert len(celeryconfig.accept_content) == 2\\n\\n    def test_accept_content_is_list(self):\\n        \\\"\\\"\\\"Test that accept_content is a list type.\\\"\\\"\\\"\\n        assert isinstance(celeryconfig.accept_content, list)\\n\\n    def test_accept_content_contains_strings(self):\\n        \\\"\\\"\\\"Test that accept_content contains only string values.\\\"\\\"\\\"\\n        for content_type in celeryconfig.accept_content:\\n            assert isinstance(content_type, str)\\n\\n\\nclass TestCeleryConfigVariables:\\n    \\\"\\\"\\\"Unit tests for configuration variables.\\\"\\\"\\\"\\n\\n    def test_required_config_variables_exist(self):\\n        \\\"\\\"\\\"Test that all required configuration variables are defined.\\\"\\\"\\\"\\n        required_vars = [\\\"broker_url\\\", \\\"result_backend\\\", \\\"accept_content\\\"]\\n        for var in required_vars:\\n            assert hasattr(celeryconfig, var), f\\\"Missing required config variable: {var}\\\"\\n\\n    def test_config_variables_have_expected_types(self):\\n        \\\"\\\"\\\"Test that configuration variables have the expected types.\\\"\\\"\\\"\\n        assert isinstance(celeryconfig.broker_url, str)\\n        assert isinstance(celeryconfig.result_backend, str)\\n        assert isinstance(celeryconfig.accept_content, list)\\n\\n    def test_broker_url_format(self):\\n        \\\"\\\"\\\"Test that broker_url follows expected format.\\\"\\\"\\\"\\n        broker_url = celeryconfig.broker_url\\n        # Should be either Redis or RabbitMQ format\\n        assert broker_url.startswith((\\\"redis://\\\", \\\"amqp://\\\")), f\\\"Unexpected broker_url format: {broker_url}\\\"\\n\\n    def test_result_backend_format(self):\\n        \\\"\\\"\\\"Test that result_backend follows expected format.\\\"\\\"\\\"\\n        result_backend = celeryconfig.result_backend\\n        # Should be Redis format\\n        assert result_backend.startswith(\\\"redis://\\\"), f\\\"Unexpected result_backend format: {result_backend}\\\"\\n\\n    def test_broker_url_not_empty(self):\\n        \\\"\\\"\\\"Test that broker_url is not an empty string.\\\"\\\"\\\"\\n        assert len(celeryconfig.broker_url) > 0\\n\\n    def test_result_backend_not_empty(self):\\n        \\\"\\\"\\\"Test that result_backend is not an empty string.\\\"\\\"\\\"\\n        assert len(celeryconfig.result_backend) > 0\\n\\n\\nclass TestCeleryConfigStructure:\\n    \\\"\\\"\\\"Unit tests for configuration structure.\\\"\\\"\\\"\\n\\n    def test_broker_url_contains_protocol(self):\\n        \\\"\\\"\\\"Test that broker_url contains a valid protocol.\\\"\\\"\\\"\\n        broker_url = celeryconfig.broker_url\\n        assert \\\"://\\\" in broker_url\\n\\n    def test_result_backend_contains_protocol(self):\\n        \\\"\\\"\\\"Test that result_backend contains a valid protocol.\\\"\\\"\\\"\\n        result_backend = celeryconfig.result_backend\\n        assert \\\"://\\\" in result_backend\\n\\n    def test_broker_url_contains_host(self):\\n        \\\"\\\"\\\"Test that broker_url contains a host component.\\\"\\\"\\\"\\n        broker_url = celeryconfig.broker_url\\n        # Remove protocol part\\n        if \\\"://\\\" in broker_url:\\n            host_part = broker_url.split(\\\"://\\\")[1]\\n            assert len(host_part) > 0\\n\\n    def test_result_backend_contains_host(self):\\n        \\\"\\\"\\\"Test that result_backend contains a host component.\\\"\\\"\\\"\\n        result_backend = celeryconfig.result_backend\\n        # Remove protocol part\\n        if \\\"://\\\" in result_backend:\\n            host_part = result_backend.split(\\\"://\\\")[1]\\n            assert len(host_part) > 0\\n\\n\\nclass TestCeleryConfigValkey:\\n    \\\"\\\"\\\"Unit tests for Valkey broker configuration.\\\"\\\"\\\"\\n\\n    def test_valkey_env_vars_set_broker_and_backend(self, monkeypatch):\\n        monkeypatch.setenv(\\\"LANGFLOW_VALKEY_HOST\\\", \\\"valkey-host\\\")\\n        monkeypatch.setenv(\\\"LANGFLOW_VALKEY_PORT\\\", \\\"6380\\\")\\n        monkeypatch.delenv(\\\"LANGFLOW_REDIS_HOST\\\", raising=False)\\n        monkeypatch.delenv(\\\"LANGFLOW_REDIS_PORT\\\", raising=False)\\n\\n        importlib.reload(celeryconfig)\\n\\n        assert celeryconfig.broker_url == \\\"redis://valkey-host:6380/0\\\"\\n        assert celeryconfig.result_backend == \\\"redis://valkey-host:6380/0\\\"\\n\\n    def test_valkey_takes_precedence_over_redis(self, monkeypatch):\\n        monkeypatch.setenv(\\\"LANGFLOW_VALKEY_HOST\\\", \\\"valkey-host\\\")\\n        monkeypatch.setenv(\\\"LANGFLOW_VALKEY_PORT\\\", \\\"6380\\\")\\n        monkeypatch.setenv(\\\"LANGFLOW_REDIS_HOST\\\", \\\"redis-host\\\")\\n        monkeypatch.setenv(\\\"LANGFLOW_REDIS_PORT\\\", \\\"6379\\\")\\n\\n        importlib.reload(celeryconfig)\\n\\n        assert celeryconfig.broker_url == \\\"redis://valkey-host:6380/0\\\"\\n        assert celeryconfig.result_backend == \\\"redis://valkey-host:6380/0\\\"\\n\\n    def test_without_valkey_preserves_redis_behavior(self, monkeypatch):\\n        monkeypatch.delenv(\\\"LANGFLOW_VALKEY_HOST\\\", raising=False)\\n        monkeypatch.delenv(\\\"LANGFLOW_VALKEY_PORT\\\", raising=False)\\n        monkeypatch.setenv(\\\"LANGFLOW_REDIS_HOST\\\", \\\"redis-host\\\")\\n        monkeypatch.setenv(\\\"LANGFLOW_REDIS_PORT\\\", \\\"6379\\\")\\n\\n        importlib.reload(celeryconfig)\\n\\n        assert celeryconfig.broker_url == \\\"redis://redis-host:6379/0\\\"\\n        assert celeryconfig.result_backend == \\\"redis://redis-host:6379/0\\\"\\n\\n    def test_incomplete_valkey_configuration_falls_back_to_redis(self, monkeypatch):\\n        monkeypatch.setenv(\\\"LANGFLOW_VALKEY_HOST\\\", \\\"valkey-host\\\")\\n        monkeypatch.delenv(\\\"LANGFLOW_VALKEY_PORT\\\", raising=False)\\n        monkeypatch.setenv(\\\"LANGFLOW_REDIS_HOST\\\", \\\"redis-host\\\")\\n        monkeypatch.setenv(\\\"LANGFLOW_REDIS_PORT\\\", \\\"6379\\\")\\n\\n        importlib.reload(celeryconfig)\\n\\n        assert celeryconfig.broker_url == \\\"redis://redis-host:6379/0\\\"\\n        assert celeryconfig.result_backend == \\\"redis://redis-host:6379/0\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/custom/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/custom/component/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/custom/component/test_component_loading_fix.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"30bc9b66b6b8f0a434f2c583dcd8d81c21178b5eff7e85151181532a0dd108bd\",\"content\":\"\\\"\\\"\\\"Tests for the component loading fix that filters out BASE_COMPONENTS_PATH from custom components.\\n\\n- BASE_COMPONENTS_PATH is properly filtered out from custom components paths\\n- Lazy loading mode works correctly\\n- Custom components are loaded only from valid custom paths\\n- No regression in existing functionality\\n\\\"\\\"\\\"\\n\\nimport asyncio\\nfrom unittest.mock import AsyncMock, MagicMock, patch\\n\\nimport pytest\\nfrom lfx.interface.components import (\\n    component_cache,\\n    get_and_cache_all_types_dict,\\n)\\nfrom lfx.services.settings.base import BASE_COMPONENTS_PATH\\nfrom lfx.services.settings.service import SettingsService\\n\\n\\nclass TestComponentLoadingFix:\\n    \\\"\\\"\\\"Test suite for the component loading fix that filters BASE_COMPONENTS_PATH.\\\"\\\"\\\"\\n\\n    @pytest.fixture\\n    def mock_settings_service(self):\\n        \\\"\\\"\\\"Create a mock settings service with configurable options.\\\"\\\"\\\"\\n        settings_service = MagicMock(spec=SettingsService)\\n        settings_service.settings = MagicMock()\\n        settings_service.settings.lazy_load_components = False\\n        settings_service.settings.components_path = []\\n        return settings_service\\n\\n    @pytest.fixture\\n    def mock_custom_paths(self):\\n        \\\"\\\"\\\"Create mock custom component paths.\\\"\\\"\\\"\\n        return [\\\"/custom/path1\\\", \\\"/custom/path2\\\"]\\n\\n    @pytest.fixture\\n    def mock_langflow_components(self):\\n        \\\"\\\"\\\"Create mock langflow components response.\\\"\\\"\\\"\\n        return {\\n            \\\"components\\\": {\\n                \\\"category1\\\": {\\n                    \\\"Component1\\\": {\\\"display_name\\\": \\\"Component1\\\", \\\"type\\\": \\\"category1\\\"},\\n                    \\\"Component2\\\": {\\\"display_name\\\": \\\"Component2\\\", \\\"type\\\": \\\"category1\\\"},\\n                },\\n                \\\"category2\\\": {\\n                    \\\"Component3\\\": {\\\"display_name\\\": \\\"Component3\\\", \\\"type\\\": \\\"category2\\\"},\\n                },\\n            }\\n        }\\n\\n    @pytest.fixture\\n    def mock_custom_components(self):\\n        \\\"\\\"\\\"Create mock custom components response.\\\"\\\"\\\"\\n        return {\\n            \\\"custom_category\\\": {\\n                \\\"CustomComponent1\\\": {\\\"display_name\\\": \\\"CustomComponent1\\\", \\\"type\\\": \\\"custom_category\\\"},\\n                \\\"CustomComponent2\\\": {\\\"display_name\\\": \\\"CustomComponent2\\\", \\\"type\\\": \\\"custom_category\\\"},\\n            }\\n        }\\n\\n    @pytest.fixture(autouse=True)\\n    def clear_component_cache(self):\\n        \\\"\\\"\\\"Clear component cache before each test.\\\"\\\"\\\"\\n        component_cache.all_types_dict = None\\n        yield\\n        component_cache.all_types_dict = None\\n\\n    @pytest.mark.asyncio\\n    async def test_base_components_path_filtering(\\n        self, mock_settings_service, mock_langflow_components, mock_custom_components\\n    ):\\n        \\\"\\\"\\\"Test that BASE_COMPONENTS_PATH is properly filtered out from custom components paths.\\\"\\\"\\\"\\n        # Setup: Include BASE_COMPONENTS_PATH in the components_path list\\n        mock_settings_service.settings.components_path = [BASE_COMPONENTS_PATH, \\\"/custom/path1\\\", \\\"/custom/path2\\\"]\\n        mock_settings_service.settings.lazy_load_components = False\\n\\n        with (\\n            patch(\\\"lfx.interface.components.import_langflow_components\\\", return_value=mock_langflow_components),\\n            patch(\\\"lfx.interface.components.aget_all_types_dict\\\") as mock_aget_all_types_dict,\\n        ):\\n            # Mock aget_all_types_dict to return custom components\\n            mock_aget_all_types_dict.return_value = mock_custom_components\\n\\n            # Execute the function\\n            result = await get_and_cache_all_types_dict(mock_settings_service)\\n\\n            # Verify that aget_all_types_dict was called with filtered paths (BASE_COMPONENTS_PATH excluded)\\n            mock_aget_all_types_dict.assert_called_once_with([\\\"/custom/path1\\\", \\\"/custom/path2\\\"])\\n\\n            # Verify result contains both langflow and custom components\\n            assert \\\"category1\\\" in result\\n            assert \\\"category2\\\" in result\\n            assert \\\"custom_category\\\" in result\\n            assert \\\"Component1\\\" in result[\\\"category1\\\"]\\n            assert \\\"CustomComponent1\\\" in result[\\\"custom_category\\\"]\\n\\n    @pytest.mark.asyncio\\n    async def test_only_base_components_path_in_list(self, mock_settings_service, mock_langflow_components):\\n        \\\"\\\"\\\"Test behavior when components_path contains only BASE_COMPONENTS_PATH.\\\"\\\"\\\"\\n        # Setup: Only BASE_COMPONENTS_PATH in the list\\n        mock_settings_service.settings.components_path = [BASE_COMPONENTS_PATH]\\n        mock_settings_service.settings.lazy_load_components = False\\n\\n        with (\\n            patch(\\\"lfx.interface.components.import_langflow_components\\\", return_value=mock_langflow_components),\\n            patch(\\\"lfx.interface.components.aget_all_types_dict\\\") as mock_aget_all_types_dict,\\n        ):\\n            # Execute the function\\n            result = await get_and_cache_all_types_dict(mock_settings_service)\\n\\n            # Verify that aget_all_types_dict was NOT called (no custom paths after filtering)\\n            mock_aget_all_types_dict.assert_not_called()\\n\\n            # Verify result contains only langflow components\\n            assert \\\"category1\\\" in result\\n            assert \\\"category2\\\" in result\\n            assert \\\"Component1\\\" in result[\\\"category1\\\"]\\n            assert \\\"Component3\\\" in result[\\\"category2\\\"]\\n\\n    @pytest.mark.asyncio\\n    async def test_empty_components_path(self, mock_settings_service, mock_langflow_components):\\n        \\\"\\\"\\\"Test behavior when components_path is empty.\\\"\\\"\\\"\\n        # Setup: Empty components_path\\n        mock_settings_service.settings.components_path = []\\n        mock_settings_service.settings.lazy_load_components = False\\n\\n        with (\\n            patch(\\\"lfx.interface.components.import_langflow_components\\\", return_value=mock_langflow_components),\\n            patch(\\\"lfx.interface.components.aget_all_types_dict\\\") as mock_aget_all_types_dict,\\n        ):\\n            # Execute the function\\n            result = await get_and_cache_all_types_dict(mock_settings_service)\\n\\n            # Verify that aget_all_types_dict was NOT called\\n            mock_aget_all_types_dict.assert_not_called()\\n\\n            # Verify result contains only langflow components\\n            assert \\\"category1\\\" in result\\n            assert \\\"category2\\\" in result\\n            assert \\\"Component1\\\" in result[\\\"category1\\\"]\\n\\n    @pytest.mark.asyncio\\n    async def test_none_components_path(self, mock_settings_service, mock_langflow_components):\\n        \\\"\\\"\\\"Test behavior when components_path is None.\\\"\\\"\\\"\\n        # Setup: None components_path\\n        mock_settings_service.settings.components_path = None\\n        mock_settings_service.settings.lazy_load_components = False\\n\\n        with (\\n            patch(\\\"lfx.interface.components.import_langflow_components\\\", return_value=mock_langflow_components),\\n            patch(\\\"lfx.interface.components.aget_all_types_dict\\\") as mock_aget_all_types_dict,\\n        ):\\n            # Execute the function\\n            result = await get_and_cache_all_types_dict(mock_settings_service)\\n\\n            # Verify that aget_all_types_dict was NOT called\\n            mock_aget_all_types_dict.assert_not_called()\\n\\n            # Verify result contains only langflow components\\n            assert \\\"category1\\\" in result\\n            assert \\\"category2\\\" in result\\n\\n    @pytest.mark.asyncio\\n    async def test_lazy_loading_mode_with_base_path_filtering(self, mock_settings_service, mock_langflow_components):\\n        \\\"\\\"\\\"Test that lazy loading mode uses aget_component_metadata with filtered paths.\\n\\n        Previously this asserted the FULL path list (\\\"not filtered in lazy mode\\\"), which is the\\n        defect: built-ins are already loaded from the prebuilt index, so rescanning\\n        BASE_COMPONENTS_PATH produced metadata-only stubs that replaced them. Every built-in then\\n        read as an unregistered custom component and LANGFLOW_ALLOW_CUSTOM_COMPONENTS=false\\n        rejected every flow. Both branches load custom paths only, as the test name always said.\\n        \\\"\\\"\\\"\\n        # Setup: Enable lazy loading and include BASE_COMPONENTS_PATH\\n        mock_settings_service.settings.lazy_load_components = True\\n        mock_settings_service.settings.components_path = [BASE_COMPONENTS_PATH, \\\"/custom/path1\\\"]\\n\\n        mock_metadata = {\\n            \\\"custom_category\\\": {\\n                \\\"CustomComponent1\\\": {\\\"display_name\\\": \\\"CustomComponent1\\\", \\\"type\\\": \\\"custom_category\\\"},\\n            }\\n        }\\n\\n        with (\\n            patch(\\\"lfx.interface.components.import_langflow_components\\\", return_value=mock_langflow_components),\\n            patch(\\\"lfx.interface.components.aget_component_metadata\\\", return_value=mock_metadata) as mock_aget_metadata,\\n        ):\\n            # Execute the function\\n            result = await get_and_cache_all_types_dict(mock_settings_service)\\n\\n            # Verify that aget_component_metadata was called with the base path filtered out\\n            mock_aget_metadata.assert_called_once_with([\\\"/custom/path1\\\"])\\n\\n            # Verify result contains both langflow and custom components\\n            assert \\\"category1\\\" in result\\n            assert \\\"custom_category\\\" in result\\n\\n    @pytest.mark.asyncio\\n    async def test_multiple_custom_paths_with_base_path(\\n        self, mock_settings_service, mock_langflow_components, mock_custom_components\\n    ):\\n        \\\"\\\"\\\"Test filtering with multiple custom paths and BASE_COMPONENTS_PATH.\\\"\\\"\\\"\\n        # Setup: Multiple paths including BASE_COMPONENTS_PATH\\n        custom_paths = [\\\"/path1\\\", BASE_COMPONENTS_PATH, \\\"/path2\\\", \\\"/path3\\\"]\\n        mock_settings_service.settings.components_path = custom_paths\\n        mock_settings_service.settings.lazy_load_components = False\\n\\n        with (\\n            patch(\\\"lfx.interface.components.import_langflow_components\\\", return_value=mock_langflow_components),\\n            patch(\\n                \\\"lfx.interface.components.aget_all_types_dict\\\", return_value=mock_custom_components\\n            ) as mock_aget_all_types_dict,\\n        ):\\n            # Execute the function\\n            result = await get_and_cache_all_types_dict(mock_settings_service)\\n\\n            # Verify that aget_all_types_dict was called with filtered paths\\n            expected_filtered_paths = [\\\"/path1\\\", \\\"/path2\\\", \\\"/path3\\\"]\\n            mock_aget_all_types_dict.assert_called_once_with(expected_filtered_paths)\\n\\n            # Verify result structure\\n            assert isinstance(result, dict)\\n            assert \\\"category1\\\" in result  # From langflow components\\n            assert \\\"custom_category\\\" in result  # From custom components\\n\\n    @pytest.mark.asyncio\\n    async def test_component_merging_logic(self, mock_settings_service, mock_langflow_components):\\n        \\\"\\\"\\\"Test that langflow and custom components are properly merged.\\n\\n        Merging is per COMPONENT, not per category. This previously asserted that a custom\\n        category \\\"should completely override\\\" the built-in one of the same name, which meant a\\n        custom directory containing a single component under a shared category name (\\\"tools\\\",\\n        \\\"embeddings\\\", \\\"utilities\\\") silently deleted every built-in component in it. Those then\\n        read as unregistered and were rejected under allow_custom_components=false. A same-named\\n        *component* is still overridden, which is what the production comment always described.\\n        \\\"\\\"\\\"\\n        # Setup\\n        mock_settings_service.settings.components_path = [\\\"/custom/path1\\\"]\\n        mock_settings_service.settings.lazy_load_components = False\\n\\n        # Create overlapping component names to test merging behavior\\n        overlapping_custom_components = {\\n            \\\"category1\\\": {  # Same category as langflow\\n                \\\"Component1\\\": {\\\"display_name\\\": \\\"CustomComponent1\\\", \\\"type\\\": \\\"category1\\\"},  # Same name as langflow\\n                \\\"Component4\\\": {\\\"display_name\\\": \\\"Component4\\\", \\\"type\\\": \\\"category1\\\"},  # New component\\n            },\\n            \\\"new_category\\\": {\\n                \\\"NewComponent\\\": {\\\"display_name\\\": \\\"NewComponent\\\", \\\"type\\\": \\\"new_category\\\"},\\n            },\\n        }\\n\\n        with (\\n            patch(\\\"lfx.interface.components.import_langflow_components\\\", return_value=mock_langflow_components),\\n            patch(\\\"lfx.interface.components.aget_all_types_dict\\\", return_value=overlapping_custom_components),\\n        ):\\n            # Execute the function\\n            result = await get_and_cache_all_types_dict(mock_settings_service)\\n\\n            # Verify that custom components override langflow components with same name\\n            assert \\\"category1\\\" in result\\n            assert \\\"category2\\\" in result  # From langflow\\n            assert \\\"new_category\\\" in result  # From custom\\n\\n            # A same-named component is still overridden by the custom one\\n            assert result[\\\"category1\\\"][\\\"Component1\\\"][\\\"display_name\\\"] == \\\"CustomComponent1\\\"\\n\\n            # ...but its built-in siblings survive: the category is supplemented, not replaced\\n            assert \\\"Component2\\\" in result[\\\"category1\\\"], (\\n                \\\"a custom component in a shared category must not delete the built-ins beside it\\\"\\n            )\\n            assert \\\"Component4\\\" in result[\\\"category1\\\"]  # New custom component\\n\\n            # New custom component should be added\\n            assert result[\\\"category1\\\"][\\\"Component4\\\"][\\\"display_name\\\"] == \\\"Component4\\\"\\n\\n            # New category should be added\\n            assert result[\\\"new_category\\\"][\\\"NewComponent\\\"][\\\"display_name\\\"] == \\\"NewComponent\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_component_cache_behavior(self, mock_settings_service, mock_langflow_components):\\n        \\\"\\\"\\\"Test that component cache is properly used and populated.\\\"\\\"\\\"\\n        # Setup\\n        mock_settings_service.settings.components_path = [\\\"/custom/path1\\\"]\\n        mock_settings_service.settings.lazy_load_components = False\\n\\n        with (\\n            patch(\\\"lfx.interface.components.import_langflow_components\\\", return_value=mock_langflow_components),\\n            patch(\\\"lfx.interface.components.aget_all_types_dict\\\", return_value={}),\\n        ):\\n            # First call - should populate cache\\n            result1 = await get_and_cache_all_types_dict(mock_settings_service)\\n\\n            # Verify cache is populated\\n            assert component_cache.all_types_dict is not None\\n            assert component_cache.all_types_dict == result1\\n\\n            # Second call - should use cache\\n            result2 = await get_and_cache_all_types_dict(mock_settings_service)\\n\\n            # Verify same result returned from cache\\n            assert result1 == result2\\n            assert result1 is result2  # Same object reference\\n\\n    @pytest.mark.asyncio\\n    async def test_logging_behavior(self, mock_settings_service, mock_langflow_components, mock_custom_components):\\n        \\\"\\\"\\\"Test that appropriate logging messages are generated.\\\"\\\"\\\"\\n        # Setup\\n        mock_settings_service.settings.components_path = [\\\"/custom/path1\\\"]\\n        mock_settings_service.settings.lazy_load_components = False\\n\\n        with (\\n            patch(\\\"lfx.interface.components.import_langflow_components\\\", return_value=mock_langflow_components),\\n            patch(\\\"lfx.interface.components.aget_all_types_dict\\\", return_value=mock_custom_components),\\n            patch(\\\"lfx.interface.components.logger\\\") as mock_logger,\\n        ):\\n            # Configure async mock methods\\n            mock_logger.adebug = AsyncMock()\\n\\n            # Execute the function\\n            await get_and_cache_all_types_dict(mock_settings_service)\\n\\n            # Verify debug logging calls\\n            mock_logger.adebug.assert_any_call(\\\"Building components cache\\\")\\n\\n            # Verify total component count logging\\n            debug_calls = [call.args[0] for call in mock_logger.adebug.call_args_list]\\n            total_count_logs = [log for log in debug_calls if \\\"Loaded\\\" in log and \\\"components\\\" in log]\\n            assert len(total_count_logs) >= 1\\n\\n    @pytest.mark.asyncio\\n    async def test_error_handling_in_custom_component_loading(self, mock_settings_service, mock_langflow_components):\\n        \\\"\\\"\\\"Test error handling when custom component loading fails.\\\"\\\"\\\"\\n        # Setup\\n        mock_settings_service.settings.components_path = [\\\"/custom/path1\\\"]\\n        mock_settings_service.settings.lazy_load_components = False\\n\\n        with (\\n            patch(\\\"lfx.interface.components.import_langflow_components\\\", return_value=mock_langflow_components),\\n            patch(\\\"lfx.interface.components.aget_all_types_dict\\\", side_effect=Exception(\\\"Custom loading failed\\\")),\\n            pytest.raises(Exception, match=\\\"Custom loading failed\\\"),\\n        ):\\n            # Execute the function - should raise exception when custom component loading fails\\n            await get_and_cache_all_types_dict(mock_settings_service)\\n\\n    @pytest.mark.asyncio\\n    async def test_base_components_path_constant_value(self):\\n        \\\"\\\"\\\"Test that BASE_COMPONENTS_PATH has expected value and behavior.\\\"\\\"\\\"\\n        # Verify BASE_COMPONENTS_PATH is defined and has expected characteristics\\n        assert BASE_COMPONENTS_PATH is not None\\n        assert isinstance(BASE_COMPONENTS_PATH, str)\\n        assert len(BASE_COMPONENTS_PATH) > 0\\n\\n        # Should be an absolute path containing \\\"langflow\\\" and \\\"components\\\"\\n        assert \\\"langflow\\\" in BASE_COMPONENTS_PATH.lower()\\n        assert \\\"components\\\" in BASE_COMPONENTS_PATH.lower()\\n\\n    @pytest.mark.asyncio\\n    async def test_path_filtering_edge_cases(self, mock_settings_service, mock_langflow_components):\\n        \\\"\\\"\\\"Test edge cases in path filtering logic.\\\"\\\"\\\"\\n        # Setup\\n        mock_settings_service.settings.lazy_load_components = False\\n\\n        # Test with duplicate BASE_COMPONENTS_PATH\\n        mock_settings_service.settings.components_path = [BASE_COMPONENTS_PATH, \\\"/custom/path\\\", BASE_COMPONENTS_PATH]\\n\\n        with (\\n            patch(\\\"lfx.interface.components.import_langflow_components\\\", return_value=mock_langflow_components),\\n            patch(\\\"lfx.interface.components.aget_all_types_dict\\\", return_value={}) as mock_aget_all_types_dict,\\n        ):\\n            # Clear cache for fresh test\\n            component_cache.all_types_dict = None\\n\\n            # Execute the function\\n            await get_and_cache_all_types_dict(mock_settings_service)\\n\\n            # Verify that both instances of BASE_COMPONENTS_PATH are filtered out\\n            mock_aget_all_types_dict.assert_called_once_with([\\\"/custom/path\\\"])\\n\\n    @pytest.mark.asyncio\\n    async def test_component_count_calculation(self, mock_settings_service, mock_langflow_components):\\n        \\\"\\\"\\\"Test that component count calculation works correctly.\\\"\\\"\\\"\\n        # Setup with known component counts\\n        mock_settings_service.settings.components_path = [\\\"/custom/path1\\\"]\\n        mock_settings_service.settings.lazy_load_components = False\\n\\n        # Mock custom components with known count\\n        mock_custom_components = {\\n            \\\"custom_cat1\\\": {\\n                \\\"CustomComp1\\\": {\\\"display_name\\\": \\\"CustomComp1\\\"},\\n                \\\"CustomComp2\\\": {\\\"display_name\\\": \\\"CustomComp2\\\"},\\n            },\\n            \\\"custom_cat2\\\": {\\n                \\\"CustomComp3\\\": {\\\"display_name\\\": \\\"CustomComp3\\\"},\\n            },\\n        }\\n\\n        with (\\n            patch(\\\"lfx.interface.components.import_langflow_components\\\", return_value=mock_langflow_components),\\n            patch(\\\"lfx.interface.components.aget_all_types_dict\\\", return_value=mock_custom_components),\\n        ):\\n            # Execute the function\\n            result = await get_and_cache_all_types_dict(mock_settings_service)\\n\\n            # Verify result structure\\n            assert len(result) >= 2  # At least langflow categories + custom categories\\n\\n            # Verify custom components are present\\n            assert \\\"custom_cat1\\\" in result\\n            assert \\\"custom_cat2\\\" in result\\n            assert \\\"CustomComp1\\\" in result[\\\"custom_cat1\\\"]\\n            assert \\\"CustomComp3\\\" in result[\\\"custom_cat2\\\"]\\n\\n    @pytest.mark.asyncio\\n    async def test_async_concurrency_safety(\\n        self, mock_settings_service, mock_langflow_components, mock_custom_components\\n    ):\\n        \\\"\\\"\\\"Test that concurrent calls to get_and_cache_all_types_dict are safe.\\\"\\\"\\\"\\n        # Setup\\n        mock_settings_service.settings.components_path = [\\\"/custom/path1\\\"]\\n        mock_settings_service.settings.lazy_load_components = False\\n\\n        with (\\n            patch(\\\"lfx.interface.components.import_langflow_components\\\", return_value=mock_langflow_components),\\n            patch(\\\"lfx.interface.components.aget_all_types_dict\\\", return_value=mock_custom_components),\\n        ):\\n            # Execute multiple concurrent calls\\n            tasks = [get_and_cache_all_types_dict(mock_settings_service) for _ in range(3)]\\n            results = await asyncio.gather(*tasks)\\n\\n            # Verify all results are identical (cache working properly)\\n            first_result = results[0]\\n            for result in results[1:]:\\n                assert result == first_result\\n                # Results should be consistent, though reference may vary due to concurrency\\n\\n    @pytest.mark.asyncio\\n    async def test_integration_with_real_base_components_path(self, mock_settings_service):\\n        \\\"\\\"\\\"Integration test with real BASE_COMPONENTS_PATH to ensure filtering works.\\\"\\\"\\\"\\n        # Setup with real BASE_COMPONENTS_PATH value\\n        mock_settings_service.settings.components_path = [BASE_COMPONENTS_PATH, \\\"/custom/test\\\"]\\n        mock_settings_service.settings.lazy_load_components = False\\n\\n        # This test should work with real langflow components\\n        with patch(\\\"lfx.interface.components.aget_all_types_dict\\\", return_value={}) as mock_aget_all_types_dict:\\n            # Execute the function\\n            result = await get_and_cache_all_types_dict(mock_settings_service)\\n\\n            # Verify BASE_COMPONENTS_PATH was filtered out\\n            mock_aget_all_types_dict.assert_called_once_with([\\\"/custom/test\\\"])\\n\\n            # Verify we got real langflow components\\n            assert isinstance(result, dict)\\n            assert len(result) >= 0  # Should not have langflow components\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/custom/custom_component/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/events/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/events/test_event_manager.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"31ef76009b9da229110a8ec2f7a3706c209d32cdaa125ca34b310cec7ea7fe50\",\"content\":\"import asyncio\\nimport json\\nimport time\\nimport uuid\\n\\nimport pytest\\nfrom langflow.events.event_manager import EventManager\\nfrom lfx.schema.log import LoggableType\\n\\n\\nclass TestEventManager:\\n    # Registering an event with a valid name and callback using a mock callback function\\n    def test_register_event_with_valid_name_and_callback_with_mock_callback(self):\\n        def mock_callback(event_type: str, data: LoggableType):\\n            pass\\n\\n        queue = asyncio.Queue()\\n        manager = EventManager(queue)\\n        manager.register_event(\\\"on_test_event\\\", \\\"test_type\\\", mock_callback)\\n        assert \\\"on_test_event\\\" in manager.events\\n        assert manager.events[\\\"on_test_event\\\"].func == mock_callback\\n\\n    # Registering an event with an empty name\\n\\n    def test_register_event_with_empty_name(self):\\n        queue = asyncio.Queue()\\n        manager = EventManager(queue)\\n        with pytest.raises(ValueError, match=\\\"Event name cannot be empty\\\"):\\n            manager.register_event(\\\"\\\", \\\"test_type\\\")\\n\\n    # Registering an event with a valid name and no callback\\n    def test_register_event_with_valid_name_and_no_callback(self):\\n        queue = asyncio.Queue()\\n        manager = EventManager(queue)\\n        manager.register_event(\\\"on_test_event\\\", \\\"test_type\\\")\\n        assert \\\"on_test_event\\\" in manager.events\\n        assert manager.events[\\\"on_test_event\\\"].func == manager.send_event\\n\\n    # Accessing a non-registered event callback via __getattr__ with the recommended fix\\n    def test_accessing_non_registered_event_callback_with_recommended_fix(self):\\n        queue = asyncio.Queue()\\n        manager = EventManager(queue)\\n        result = manager.non_registered_event\\n        assert result == manager.noop\\n\\n    # Accessing a registered event callback via __getattr__\\n    def test_accessing_registered_event_callback(self):\\n        def mock_callback(event_type: str, data: LoggableType):\\n            pass\\n\\n        queue = asyncio.Queue()\\n        manager = EventManager(queue)\\n        manager.register_event(\\\"on_test_event\\\", \\\"test_type\\\", mock_callback)\\n        assert manager.on_test_event.func == mock_callback\\n\\n    # Handling a large number of events in the queue\\n    def test_handling_large_number_of_events(self):\\n        def mock_queue_put_nowait(item):\\n            pass\\n\\n        queue = asyncio.Queue()\\n        queue.put_nowait = mock_queue_put_nowait\\n        manager = EventManager(queue)\\n\\n        for i in range(1000):\\n            manager.register_event(f\\\"on_test_event_{i}\\\", \\\"test_type\\\", manager.noop)\\n\\n        assert len(manager.events) == 1000\\n\\n    # Testing registration of an event with an invalid name with the recommended fix\\n    def test_register_event_with_invalid_name_fixed(self):\\n        def mock_callback(event_type, data):\\n            pass\\n\\n        queue = asyncio.Queue()\\n        manager = EventManager(queue)\\n        with pytest.raises(ValueError, match=\\\"Event name cannot be empty\\\"):\\n            manager.register_event(\\\"\\\", \\\"test_type\\\", mock_callback)\\n        with pytest.raises(ValueError, match=\\\"Event name must start with 'on_'\\\"):\\n            manager.register_event(\\\"invalid_name\\\", \\\"test_type\\\", mock_callback)\\n\\n    # Sending an event with complex data and verifying successful event transmission\\n    async def test_sending_event_with_complex_data(self):\\n        queue = asyncio.Queue()\\n\\n        manager = EventManager(queue)\\n        manager.register_event(\\\"on_test_event\\\", \\\"test_type\\\", manager.noop)\\n        data = {\\\"key\\\": \\\"value\\\", \\\"nested\\\": [1, 2, 3]}\\n        manager.send_event(event_type=\\\"test_type\\\", data=data)\\n        event_id, str_data, event_time = await queue.get()\\n        assert event_id is not None\\n        assert str_data is not None\\n        assert event_time <= time.time()\\n\\n    # Sending an event with None data\\n    def test_sending_event_with_none_data(self):\\n        queue = asyncio.Queue()\\n        manager = EventManager(queue)\\n        manager.register_event(\\\"on_test_event\\\", \\\"test_type\\\")\\n        assert \\\"on_test_event\\\" in manager.events\\n        assert manager.events[\\\"on_test_event\\\"].func.__name__ == \\\"send_event\\\"\\n\\n    # Ensuring thread-safety when accessing the events dictionary\\n    async def test_thread_safety_accessing_events_dictionary(self):\\n        def mock_callback(event_type: str, data: LoggableType):\\n            pass\\n\\n        async def register_events(manager):\\n            manager.register_event(\\\"on_test_event_1\\\", \\\"test_type_1\\\", mock_callback)\\n            manager.register_event(\\\"on_test_event_2\\\", \\\"test_type_2\\\", mock_callback)\\n\\n        async def access_events(manager):\\n            assert \\\"on_test_event_1\\\" in manager.events\\n            assert \\\"on_test_event_2\\\" in manager.events\\n\\n        queue = asyncio.Queue()\\n        manager = EventManager(queue)\\n\\n        await asyncio.gather(register_events(manager), access_events(manager))\\n\\n    # Checking the performance impact of frequent event registrations\\n    def test_performance_impact_frequent_registrations(self):\\n        def mock_callback(event_type: str, data: LoggableType):\\n            pass\\n\\n        queue = asyncio.Queue()\\n        manager = EventManager(queue)\\n        for i in range(1000):\\n            manager.register_event(f\\\"on_test_event_{i}\\\", \\\"test_type\\\", mock_callback)\\n        assert len(manager.events) == 1000\\n\\n    # Verifying the uniqueness of event IDs for each event triggered using await with asyncio decorator\\n    async def test_event_id_uniqueness_with_await(self):\\n        queue = asyncio.Queue()\\n        manager = EventManager(queue)\\n        manager.register_event(\\\"on_test_event\\\", \\\"test_type\\\")\\n        manager.on_test_event(data={\\\"data_1\\\": \\\"value_1\\\"})\\n        manager.on_test_event(data={\\\"data_2\\\": \\\"value_2\\\"})\\n        try:\\n            event_id_1, _, _ = await queue.get()\\n            event_id_2, _, _ = await queue.get()\\n        except asyncio.TimeoutError:\\n            pytest.fail(\\\"Test timed out while waiting for queue items\\\")\\n\\n        assert event_id_1 != event_id_2\\n\\n    # Ensuring the queue receives the correct event data format\\n    async def test_queue_receives_correct_event_data_format(self):\\n        def mock_queue_put_nowait(data):\\n            pass\\n\\n        async def mock_queue_get():\\n            return (uuid.uuid4(), b'{\\\"event\\\": \\\"test_type\\\", \\\"data\\\": \\\"test_data\\\"}\\\\n\\\\n', time.time())\\n\\n        queue = asyncio.Queue()\\n        queue.put_nowait = mock_queue_put_nowait\\n        queue.get = mock_queue_get\\n\\n        manager = EventManager(queue)\\n        manager.register_event(\\\"on_test_event\\\", \\\"test_type\\\", manager.noop)\\n        event_data = \\\"test_data\\\"\\n        manager.send_event(event_type=\\\"test_type\\\", data=event_data)\\n\\n        event_id, str_data, _ = await queue.get()\\n        assert isinstance(event_id, uuid.UUID)\\n        assert isinstance(str_data, bytes)\\n        assert json.loads(str_data.decode(\\\"utf-8\\\")) == {\\\"event\\\": \\\"test_type\\\", \\\"data\\\": event_data}\\n\\n    # Registering an event without specifying the event_type argument and providing the event_type argument\\n    def test_register_event_without_event_type_argument_fixed(self):\\n        class MockQueue:\\n            def __init__(self):\\n                self.data = []\\n\\n            def put_nowait(self, item):\\n                self.data.append(item)\\n\\n        queue = MockQueue()\\n        event_manager = EventManager(queue)\\n        event_manager.register_event(\\\"on_test_event\\\", \\\"test_event_type\\\", callback=event_manager.noop)\\n        event_manager.send_event(event_type=\\\"test_type\\\", data={\\\"key\\\": \\\"value\\\"})\\n\\n        assert len(queue.data) == 1\\n        event_id, str_data, timestamp = queue.data[0]\\n        # event_id follows this pattern: f\\\"{event_type}-{uuid.uuid4()}\\\"\\n        event_type_from_id = event_id.split(\\\"-\\\")[0]\\n        assert event_type_from_id == \\\"test_type\\\"\\n        uuid_from_id = event_id.split(event_type_from_id)[1]\\n        assert isinstance(uuid_from_id, str)\\n        # assert that the uuid_from_id is a valid uuid\\n        try:\\n            uuid.UUID(uuid_from_id)\\n        except ValueError:\\n            pytest.fail(f\\\"Invalid UUID: {uuid_from_id}\\\")\\n        assert isinstance(str_data, bytes)\\n        assert isinstance(timestamp, float)\\n\\n    # Accessing a non-registered event callback via __getattr__\\n    def test_accessing_non_registered_callback(self):\\n        class MockQueue:\\n            def __init__(self):\\n                pass\\n\\n            def put_nowait(self, item):\\n                pass\\n\\n        queue = MockQueue()\\n        event_manager = EventManager(queue)\\n\\n        # Accessing a non-registered event callback should return the 'noop' function\\n        callback = event_manager.on_non_existing_event\\n        assert callback.__name__ == \\\"noop\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/exceptions/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/exceptions/test_api.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"7d83bcb77cecb1252c6fb0eadebfaac8c9451e422725bb6c3eb0b834101e6b7d\",\"content\":\"from unittest.mock import Mock, patch\\n\\nfrom langflow.exceptions.api import APIException, ExceptionBody\\nfrom langflow.services.database.models.flow.model import Flow\\n\\n\\ndef test_api_exception():\\n    mock_exception = Exception(\\\"Test exception\\\")\\n    mock_flow = Mock(spec=Flow)\\n    mock_outdated_components = [\\\"component1\\\", \\\"component2\\\"]\\n    mock_suggestion_message = \\\"Update component1, component2\\\"\\n    mock_component_versions = {\\n        \\\"component1\\\": \\\"1.0\\\",\\n        \\\"component2\\\": \\\"1.0\\\",\\n    }\\n    # Expected result\\n\\n    with (\\n        patch(\\n            \\\"langflow.services.database.models.flow.utils.get_outdated_components\\\",\\n            return_value=mock_outdated_components,\\n        ),\\n        patch(\\\"langflow.api.utils.get_suggestion_message\\\", return_value=mock_suggestion_message),\\n        patch(\\n            \\\"langflow.services.database.models.flow.utils.get_components_versions\\\",\\n            return_value=mock_component_versions,\\n        ),\\n    ):\\n        # Create an APIException instance\\n        api_exception = APIException(mock_exception, mock_flow)\\n\\n        # Expected body\\n        expected_body = ExceptionBody(\\n            message=\\\"Test exception\\\",\\n            suggestion=\\\"The flow contains 2 outdated components. \\\"\\n            \\\"We recommend updating the following components: component1, component2.\\\",\\n        )\\n\\n        # Assert the status code\\n        assert api_exception.status_code == 500\\n\\n        # Assert the detail\\n        assert api_exception.detail == expected_body.model_dump_json()\\n\\n\\ndef test_api_exception_no_flow():\\n    # Mock data\\n    mock_exception = Exception(\\\"Test exception\\\")\\n\\n    # Create an APIException instance without a flow\\n    api_exception = APIException(mock_exception)\\n\\n    # Expected body\\n    expected_body = ExceptionBody(message=\\\"Test exception\\\")\\n\\n    # Assert the status code\\n    assert api_exception.status_code == 500\\n\\n    # Assert the detail\\n    assert api_exception.detail == expected_body.model_dump_json()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/groq/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b3b088d4030e4e6c5f321ca1969619a9c8574dbf3674e560c267dd99a2e1f9fd\",\"content\":\"\\\"\\\"\\\"Tests for Groq dynamic model discovery and integration.\\\"\\\"\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/groq/conftest.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"925d719ca203862ae0d8438e46d8e0512106b5a7de270a1725c41bb832132ee9\",\"content\":\"import importlib.util\\nimport json\\nimport os\\nimport sys\\nimport tempfile\\nfrom datetime import datetime, timedelta, timezone\\nfrom pathlib import Path\\nfrom types import ModuleType\\nfrom unittest.mock import MagicMock, Mock\\n\\nimport pytest\\nimport requests\\n\\n\\n# Pytest configuration for custom markers and API key handling\\ndef pytest_configure(config):\\n    \\\"\\\"\\\"Register custom markers.\\\"\\\"\\\"\\n    config.addinivalue_line(\\\"markers\\\", \\\"requires_api_key: mark test as requiring a real GROQ_API_KEY from environment\\\")\\n\\n\\ndef pytest_collection_modifyitems(config, items):  # noqa: ARG001\\n    \\\"\\\"\\\"Skip tests marked with requires_api_key if GROQ_API_KEY is not set.\\\"\\\"\\\"\\n    skip_no_api_key = pytest.mark.skip(reason=\\\"GROQ_API_KEY not found in environment (.env)\\\")\\n\\n    for item in items:\\n        if \\\"requires_api_key\\\" in item.keywords and not os.getenv(\\\"GROQ_API_KEY\\\"):\\n            item.add_marker(skip_no_api_key)\\n\\n\\n@pytest.fixture(autouse=True)\\ndef fake_groq(monkeypatch):\\n    if importlib.util.find_spec(\\\"groq\\\") is not None:\\n        return\\n\\n    groq = ModuleType(\\\"groq\\\")\\n    groq.Groq = MagicMock(name=\\\"Groq\\\")\\n    monkeypatch.setitem(sys.modules, \\\"groq\\\", groq)\\n\\n\\n@pytest.fixture\\ndef real_groq_api_key():\\n    \\\"\\\"\\\"Get real GROQ_API_KEY from environment if available.\\\"\\\"\\\"\\n    api_key = os.getenv(\\\"GROQ_API_KEY\\\")\\n    if not api_key:\\n        pytest.skip(\\\"GROQ_API_KEY not found in environment\\\")\\n    return api_key\\n\\n\\n@pytest.fixture\\ndef mock_api_key():\\n    \\\"\\\"\\\"Provide a mock API key for testing.\\\"\\\"\\\"\\n    return \\\"gsk_test_api_key_1234567890\\\"\\n\\n\\n@pytest.fixture\\ndef mock_invalid_api_key():\\n    \\\"\\\"\\\"Provide an invalid API key for testing.\\\"\\\"\\\"\\n    return \\\"invalid_key\\\"\\n\\n\\n@pytest.fixture\\ndef mock_groq_models_response():\\n    \\\"\\\"\\\"Mock response from Groq models API.\\\"\\\"\\\"\\n    return {\\n        \\\"data\\\": [\\n            {\\\"id\\\": \\\"llama-3.1-8b-instant\\\", \\\"object\\\": \\\"model\\\"},\\n            {\\\"id\\\": \\\"llama-3.3-70b-versatile\\\", \\\"object\\\": \\\"model\\\"},\\n            {\\\"id\\\": \\\"mixtral-8x7b-32768\\\", \\\"object\\\": \\\"model\\\"},\\n            {\\\"id\\\": \\\"gemma-7b-it\\\", \\\"object\\\": \\\"model\\\"},\\n            {\\\"id\\\": \\\"whisper-large-v3\\\", \\\"object\\\": \\\"model\\\"},\\n            {\\\"id\\\": \\\"distil-whisper-large-v3-en\\\", \\\"object\\\": \\\"model\\\"},\\n            {\\\"id\\\": \\\"meta-llama/llama-guard-4-12b\\\", \\\"object\\\": \\\"model\\\"},\\n            {\\\"id\\\": \\\"meta-llama/llama-prompt-guard-2-86m\\\", \\\"object\\\": \\\"model\\\"},\\n        ]\\n    }\\n\\n\\n@pytest.fixture\\ndef mock_llm_models():\\n    \\\"\\\"\\\"List of LLM models (excluding audio, TTS, guards).\\\"\\\"\\\"\\n    return [\\n        \\\"llama-3.1-8b-instant\\\",\\n        \\\"llama-3.3-70b-versatile\\\",\\n        \\\"mixtral-8x7b-32768\\\",\\n        \\\"gemma-7b-it\\\",\\n    ]\\n\\n\\n@pytest.fixture\\ndef mock_non_llm_models():\\n    \\\"\\\"\\\"List of non-LLM models (audio, TTS, guards).\\\"\\\"\\\"\\n    return [\\n        \\\"whisper-large-v3\\\",\\n        \\\"distil-whisper-large-v3-en\\\",\\n        \\\"meta-llama/llama-guard-4-12b\\\",\\n        \\\"meta-llama/llama-prompt-guard-2-86m\\\",\\n    ]\\n\\n\\n@pytest.fixture\\ndef mock_tool_calling_models():\\n    \\\"\\\"\\\"List of models that support tool calling.\\\"\\\"\\\"\\n    return [\\\"llama-3.1-8b-instant\\\", \\\"llama-3.3-70b-versatile\\\", \\\"mixtral-8x7b-32768\\\"]\\n\\n\\n@pytest.fixture\\ndef mock_non_tool_calling_models():\\n    \\\"\\\"\\\"List of models that don't support tool calling.\\\"\\\"\\\"\\n    return [\\\"gemma-7b-it\\\"]\\n\\n\\n@pytest.fixture\\ndef temp_cache_dir():\\n    \\\"\\\"\\\"Create a temporary directory for cache files.\\\"\\\"\\\"\\n    with tempfile.TemporaryDirectory() as tmpdir:\\n        yield Path(tmpdir)\\n\\n\\n@pytest.fixture\\ndef mock_cache_file(temp_cache_dir):\\n    \\\"\\\"\\\"Create a mock cache file with valid data.\\\"\\\"\\\"\\n    cache_file = temp_cache_dir / \\\".cache\\\" / \\\"groq_models_cache.json\\\"\\n    cache_file.parent.mkdir(parents=True, exist_ok=True)\\n\\n    cache_data = {\\n        \\\"cached_at\\\": datetime.now(timezone.utc).isoformat(),\\n        \\\"models\\\": {\\n            \\\"llama-3.1-8b-instant\\\": {\\n                \\\"name\\\": \\\"llama-3.1-8b-instant\\\",\\n                \\\"provider\\\": \\\"Meta\\\",\\n                \\\"tool_calling\\\": True,\\n                \\\"preview\\\": False,\\n                \\\"last_tested\\\": datetime.now(timezone.utc).isoformat(),\\n            },\\n            \\\"llama-3.3-70b-versatile\\\": {\\n                \\\"name\\\": \\\"llama-3.3-70b-versatile\\\",\\n                \\\"provider\\\": \\\"Meta\\\",\\n                \\\"tool_calling\\\": True,\\n                \\\"preview\\\": False,\\n                \\\"last_tested\\\": datetime.now(timezone.utc).isoformat(),\\n            },\\n        },\\n    }\\n\\n    with cache_file.open(\\\"w\\\") as f:\\n        json.dump(cache_data, f)\\n\\n    return cache_file\\n\\n\\n@pytest.fixture\\ndef mock_expired_cache_file(temp_cache_dir):\\n    \\\"\\\"\\\"Create a mock cache file with expired data.\\\"\\\"\\\"\\n    cache_file = temp_cache_dir / \\\".cache\\\" / \\\"groq_models_cache.json\\\"\\n    cache_file.parent.mkdir(parents=True, exist_ok=True)\\n\\n    # Set cache time to 25 hours ago (beyond 24 hour expiry)\\n    expired_time = datetime.now(timezone.utc) - timedelta(hours=25)\\n\\n    cache_data = {\\n        \\\"cached_at\\\": expired_time.isoformat(),\\n        \\\"models\\\": {\\n            \\\"llama-3.1-8b-instant\\\": {\\n                \\\"name\\\": \\\"llama-3.1-8b-instant\\\",\\n                \\\"provider\\\": \\\"Meta\\\",\\n                \\\"tool_calling\\\": True,\\n                \\\"preview\\\": False,\\n                \\\"last_tested\\\": expired_time.isoformat(),\\n            }\\n        },\\n    }\\n\\n    with cache_file.open(\\\"w\\\") as f:\\n        json.dump(cache_data, f)\\n\\n    return cache_file\\n\\n\\n@pytest.fixture\\ndef mock_corrupted_cache_file(temp_cache_dir):\\n    \\\"\\\"\\\"Create a corrupted cache file (invalid JSON).\\\"\\\"\\\"\\n    cache_file = temp_cache_dir / \\\".cache\\\" / \\\"groq_models_cache.json\\\"\\n    cache_file.parent.mkdir(parents=True, exist_ok=True)\\n\\n    with cache_file.open(\\\"w\\\") as f:\\n        f.write(\\\"{ invalid json content }\\\")\\n\\n    return cache_file\\n\\n\\n@pytest.fixture\\ndef mock_requests_get_success(mock_groq_models_response):\\n    \\\"\\\"\\\"Mock successful requests.get for Groq API.\\\"\\\"\\\"\\n\\n    def _mock_get(_url, *_args, **_kwargs):\\n        response = Mock()\\n        response.status_code = 200\\n        response.json.return_value = mock_groq_models_response\\n        response.raise_for_status = Mock()\\n        return response\\n\\n    return _mock_get\\n\\n\\n@pytest.fixture\\ndef mock_requests_get_failure():\\n    \\\"\\\"\\\"Mock failed requests.get for Groq API.\\\"\\\"\\\"\\n\\n    def _mock_get(_url, *_args, **_kwargs):\\n        msg = \\\"Connection error\\\"\\n        raise requests.RequestException(msg)\\n\\n    return _mock_get\\n\\n\\n@pytest.fixture\\ndef mock_requests_get_timeout():\\n    \\\"\\\"\\\"Mock timeout for requests.get.\\\"\\\"\\\"\\n\\n    def _mock_get(_url, *_args, **_kwargs):\\n        msg = \\\"Request timeout\\\"\\n        raise requests.Timeout(msg)\\n\\n    return _mock_get\\n\\n\\n@pytest.fixture\\ndef mock_requests_get_unauthorized():\\n    \\\"\\\"\\\"Mock unauthorized response (401) for requests.get.\\\"\\\"\\\"\\n\\n    def _mock_get(_url, *_args, **_kwargs):\\n        response = Mock()\\n        response.status_code = 401\\n        response.raise_for_status.side_effect = requests.HTTPError(\\\"401 Unauthorized\\\")\\n        return response\\n\\n    return _mock_get\\n\\n\\n@pytest.fixture\\ndef mock_groq_client_tool_calling_success():\\n    \\\"\\\"\\\"Mock successful Groq client for tool calling test.\\\"\\\"\\\"\\n\\n    def _create_mock_client(*_args, **_kwargs):\\n        mock_client = MagicMock()\\n        mock_response = MagicMock()\\n        mock_client.chat.completions.create.return_value = mock_response\\n        return mock_client\\n\\n    return _create_mock_client\\n\\n\\n@pytest.fixture\\ndef mock_groq_client_tool_calling_failure():\\n    \\\"\\\"\\\"Mock Groq client that raises error for tool calling.\\\"\\\"\\\"\\n\\n    def _create_mock_client(*_args, **_kwargs):\\n        mock_client = MagicMock()\\n        mock_client.chat.completions.create.side_effect = ValueError(\\\"tool calling not supported for this model\\\")\\n        return mock_client\\n\\n    return _create_mock_client\\n\\n\\n@pytest.fixture\\ndef mock_groq_client_rate_limit():\\n    \\\"\\\"\\\"Mock Groq client that raises rate limit error.\\\"\\\"\\\"\\n\\n    def _create_mock_client(*_args, **_kwargs):\\n        mock_client = MagicMock()\\n        mock_client.chat.completions.create.side_effect = RuntimeError(\\\"Rate limit exceeded\\\")\\n        return mock_client\\n\\n    return _create_mock_client\\n\\n\\n@pytest.fixture\\ndef mock_groq_client_chat_not_supported():\\n    \\\"\\\"\\\"Mock Groq client that raises 'does not support chat completions' error.\\\"\\\"\\\"\\n\\n    def _create_mock_client(*_args, **_kwargs):\\n        mock_client = MagicMock()\\n        mock_client.chat.completions.create.side_effect = ValueError(\\n            \\\"Error: model 'some-model' does not support chat completions\\\"\\n        )\\n        return mock_client\\n\\n    return _create_mock_client\\n\\n\\n@pytest.fixture\\ndef mock_groq_client_chat_terms_required():\\n    \\\"\\\"\\\"Mock Groq client that raises a terms_required error.\\\"\\\"\\\"\\n\\n    def _create_mock_client(*_args, **_kwargs):\\n        mock_client = MagicMock()\\n        mock_client.chat.completions.create.side_effect = ValueError(\\n            \\\"Error: model_terms_required - please accept the terms\\\"\\n        )\\n        return mock_client\\n\\n    return _create_mock_client\\n\\n\\n@pytest.fixture\\ndef sample_models_metadata():\\n    \\\"\\\"\\\"Sample model metadata dictionary for testing.\\\"\\\"\\\"\\n    return {\\n        \\\"llama-3.1-8b-instant\\\": {\\n            \\\"name\\\": \\\"llama-3.1-8b-instant\\\",\\n            \\\"provider\\\": \\\"Meta\\\",\\n            \\\"tool_calling\\\": True,\\n            \\\"preview\\\": False,\\n            \\\"last_tested\\\": datetime.now(timezone.utc).isoformat(),\\n        },\\n        \\\"llama-3.3-70b-versatile\\\": {\\n            \\\"name\\\": \\\"llama-3.3-70b-versatile\\\",\\n            \\\"provider\\\": \\\"Meta\\\",\\n            \\\"tool_calling\\\": True,\\n            \\\"preview\\\": False,\\n            \\\"last_tested\\\": datetime.now(timezone.utc).isoformat(),\\n        },\\n        \\\"gemma-7b-it\\\": {\\n            \\\"name\\\": \\\"gemma-7b-it\\\",\\n            \\\"provider\\\": \\\"Google\\\",\\n            \\\"tool_calling\\\": False,\\n            \\\"preview\\\": False,\\n            \\\"last_tested\\\": datetime.now(timezone.utc).isoformat(),\\n        },\\n        \\\"llama-3.2-1b-preview\\\": {\\n            \\\"name\\\": \\\"llama-3.2-1b-preview\\\",\\n            \\\"provider\\\": \\\"Meta\\\",\\n            \\\"tool_calling\\\": False,\\n            \\\"preview\\\": True,\\n            \\\"last_tested\\\": datetime.now(timezone.utc).isoformat(),\\n        },\\n        \\\"whisper-large-v3\\\": {\\n            \\\"name\\\": \\\"whisper-large-v3\\\",\\n            \\\"provider\\\": \\\"OpenAI\\\",\\n            \\\"not_supported\\\": True,\\n            \\\"last_tested\\\": datetime.now(timezone.utc).isoformat(),\\n        },\\n    }\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/groq/test_groq_chat_completion.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"89c60ed8a918f602d105c295342839e4f9df5ea306486d2ca2f8156ed76f814a\",\"content\":\"\\\"\\\"\\\"Tests for Groq _test_chat_completion method.\\\"\\\"\\\"\\n\\nimport sys\\nfrom unittest.mock import MagicMock, Mock, patch\\n\\nimport pytest\\nfrom lfx.base.models.groq_model_discovery import GroqModelDiscovery\\n\\n\\nclass TestChatCompletionDetection:\\n    \\\"\\\"\\\"Test _test_chat_completion method.\\\"\\\"\\\"\\n\\n    @patch(\\\"groq.Groq\\\")\\n    def test_chat_completion_success(self, mock_groq, mock_api_key, mock_groq_client_tool_calling_success):\\n        \\\"\\\"\\\"Test successful chat completion returns True.\\\"\\\"\\\"\\n        mock_groq.return_value = mock_groq_client_tool_calling_success()\\n\\n        discovery = GroqModelDiscovery(api_key=mock_api_key)\\n        result = discovery._test_chat_completion(\\\"llama-3.1-8b-instant\\\")\\n\\n        assert result is True\\n\\n    @patch(\\\"groq.Groq\\\")\\n    def test_chat_completion_not_supported(self, mock_groq, mock_api_key, mock_groq_client_chat_not_supported):\\n        \\\"\\\"\\\"Test model that does not support chat completions returns False.\\\"\\\"\\\"\\n        mock_groq.return_value = mock_groq_client_chat_not_supported()\\n\\n        discovery = GroqModelDiscovery(api_key=mock_api_key)\\n        result = discovery._test_chat_completion(\\\"speech-model\\\")\\n\\n        assert result is False\\n\\n    @patch(\\\"groq.Groq\\\")\\n    def test_chat_completion_terms_required_returns_none(\\n        self, mock_groq, mock_api_key, mock_groq_client_chat_terms_required\\n    ):\\n        \\\"\\\"\\\"Test that access/entitlement errors cause _test_chat_completion to return None.\\\"\\\"\\\"\\n        mock_groq.return_value = mock_groq_client_chat_terms_required()\\n\\n        discovery = GroqModelDiscovery(api_key=mock_api_key)\\n        result = discovery._test_chat_completion(\\\"gated-model\\\")\\n\\n        assert result is None\\n\\n    @patch(\\\"groq.Groq\\\")\\n    def test_chat_completion_transient_error_returns_none(self, mock_groq, mock_api_key, mock_groq_client_rate_limit):\\n        \\\"\\\"\\\"Test that transient errors (e.g. rate limits) return None (indeterminate).\\\"\\\"\\\"\\n        mock_groq.return_value = mock_groq_client_rate_limit()\\n\\n        discovery = GroqModelDiscovery(api_key=mock_api_key)\\n        result = discovery._test_chat_completion(\\\"llama-3.1-8b-instant\\\")\\n\\n        assert result is None\\n\\n    def test_chat_completion_import_error_raises(self, mock_api_key):\\n        \\\"\\\"\\\"Test that ImportError propagates when the groq package is not installed.\\\"\\\"\\\"\\n        # Simulate groq not being installed by hiding it from sys.modules\\n        with patch.dict(sys.modules, {\\\"groq\\\": None}):\\n            discovery = GroqModelDiscovery(api_key=mock_api_key)\\n            with pytest.raises(ImportError):\\n                discovery._test_chat_completion(\\\"test-model\\\")\\n\\n    @patch(\\\"lfx.base.models.groq_model_discovery.requests.get\\\")\\n    @patch(\\\"groq.Groq\\\")\\n    def test_chat_failure_marks_model_not_supported(\\n        self,\\n        mock_groq,\\n        mock_get,\\n        mock_api_key,\\n        temp_cache_dir,\\n    ):\\n        \\\"\\\"\\\"Test that a model failing the chat test is marked not_supported in get_models.\\\"\\\"\\\"\\n        mock_response = Mock()\\n        mock_response.json.return_value = {\\n            \\\"data\\\": [\\n                {\\\"id\\\": \\\"llama-3.1-8b-instant\\\", \\\"object\\\": \\\"model\\\"},\\n                {\\\"id\\\": \\\"speech-model-v1\\\", \\\"object\\\": \\\"model\\\"},\\n            ]\\n        }\\n        mock_response.raise_for_status = Mock()\\n        mock_get.return_value = mock_response\\n\\n        # First Groq() call: chat test for llama (succeeds)\\n        # Second Groq() call: tool test for llama (succeeds)\\n        # Third Groq() call: chat test for speech-model (fails with \\\"does not support chat completions\\\")\\n        call_count = [0]\\n\\n        def create_mock_client(*_args, **_kwargs):\\n            mock_client = MagicMock()\\n            if call_count[0] <= 1:\\n                # chat + tool test for llama: succeed\\n                mock_client.chat.completions.create.return_value = MagicMock()\\n            else:\\n                # chat test for speech-model: fails\\n                mock_client.chat.completions.create.side_effect = ValueError(\\n                    \\\"Error: model 'speech-model-v1' does not support chat completions\\\"\\n                )\\n            call_count[0] += 1\\n            return mock_client\\n\\n        mock_groq.side_effect = create_mock_client\\n\\n        discovery = GroqModelDiscovery(api_key=mock_api_key)\\n        discovery.CACHE_FILE = temp_cache_dir / \\\".cache\\\" / \\\"test_cache.json\\\"\\n\\n        models = discovery.get_models(force_refresh=True)\\n\\n        # llama should be a normal LLM model with tool_calling\\n        assert \\\"tool_calling\\\" in models[\\\"llama-3.1-8b-instant\\\"]\\n        assert models[\\\"llama-3.1-8b-instant\\\"].get(\\\"not_supported\\\") is None\\n\\n        # speech-model should be marked not_supported\\n        assert models[\\\"speech-model-v1\\\"][\\\"not_supported\\\"] is True\\n        assert \\\"tool_calling\\\" not in models[\\\"speech-model-v1\\\"]\\n\\n    @patch(\\\"lfx.base.models.groq_model_discovery.requests.get\\\")\\n    @patch(\\\"groq.Groq\\\")\\n    def test_transient_chat_error_does_not_exclude_model(\\n        self,\\n        mock_groq,\\n        mock_get,\\n        mock_api_key,\\n        temp_cache_dir,\\n    ):\\n        \\\"\\\"\\\"Test that transient chat errors (rate limits) don't incorrectly exclude models.\\\"\\\"\\\"\\n        mock_response = Mock()\\n        mock_response.json.return_value = {\\n            \\\"data\\\": [\\n                {\\\"id\\\": \\\"rate-limited-model\\\", \\\"object\\\": \\\"model\\\"},\\n            ]\\n        }\\n        mock_response.raise_for_status = Mock()\\n        mock_get.return_value = mock_response\\n\\n        # First Groq() call: chat test hits rate limit (transient error)\\n        # Second Groq() call: tool test succeeds\\n        call_count = [0]\\n\\n        def create_mock_client(*_args, **_kwargs):\\n            mock_client = MagicMock()\\n            if call_count[0] == 0:\\n                mock_client.chat.completions.create.side_effect = RuntimeError(\\\"Rate limit exceeded\\\")\\n            else:\\n                mock_client.chat.completions.create.return_value = MagicMock()\\n            call_count[0] += 1\\n            return mock_client\\n\\n        mock_groq.side_effect = create_mock_client\\n\\n        discovery = GroqModelDiscovery(api_key=mock_api_key)\\n        discovery.CACHE_FILE = temp_cache_dir / \\\".cache\\\" / \\\"test_cache.json\\\"\\n\\n        models = discovery.get_models(force_refresh=True)\\n\\n        # Model should NOT be excluded \u2014 it should be treated as a normal LLM\\n        assert \\\"tool_calling\\\" in models[\\\"rate-limited-model\\\"]\\n        assert models[\\\"rate-limited-model\\\"].get(\\\"not_supported\\\") is None\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/groq/test_groq_constants.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d484d0cbf9bb591009d4b279fc1ccc33b65be9df235c051fe9a1440b8527cf96\",\"content\":\"\\\"\\\"\\\"Tests for Groq constants and fallback models.\\n\\nTests cover:\\n- Fallback model structure and integrity\\n- Model categorization (production, preview, deprecated, unsupported)\\n- Backward compatibility constants\\n- Model metadata completeness\\n\\\"\\\"\\\"\\n\\n\\nclass TestGroqConstantsStructure:\\n    \\\"\\\"\\\"Test the structure and integrity of Groq constants.\\\"\\\"\\\"\\n\\n    def test_groq_models_detailed_exists(self):\\n        \\\"\\\"\\\"Test that GROQ_MODELS_DETAILED constant exists.\\\"\\\"\\\"\\n        from lfx.base.models.groq_constants import GROQ_MODELS_DETAILED\\n\\n        assert isinstance(GROQ_MODELS_DETAILED, list)\\n        assert len(GROQ_MODELS_DETAILED) > 0\\n\\n    def test_groq_models_detailed_structure(self):\\n        \\\"\\\"\\\"Test that each model in GROQ_MODELS_DETAILED has required fields.\\\"\\\"\\\"\\n        from lfx.base.models.groq_constants import GROQ_MODELS_DETAILED\\n\\n        required_fields = [\\\"name\\\", \\\"provider\\\", \\\"icon\\\"]\\n\\n        for model in GROQ_MODELS_DETAILED:\\n            assert isinstance(model, dict)\\n            for field in required_fields:\\n                assert field in model, f\\\"Model {model.get('name', 'unknown')} missing field: {field}\\\"\\n\\n    def test_groq_production_models_exists(self):\\n        \\\"\\\"\\\"Test that GROQ_PRODUCTION_MODELS constant exists.\\\"\\\"\\\"\\n        from lfx.base.models.groq_constants import GROQ_PRODUCTION_MODELS\\n\\n        assert isinstance(GROQ_PRODUCTION_MODELS, list)\\n        assert len(GROQ_PRODUCTION_MODELS) >= 2  # Should have at least fallback models\\n\\n    def test_groq_preview_models_exists(self):\\n        \\\"\\\"\\\"Test that GROQ_PREVIEW_MODELS constant exists.\\\"\\\"\\\"\\n        from lfx.base.models.groq_constants import GROQ_PREVIEW_MODELS\\n\\n        assert isinstance(GROQ_PREVIEW_MODELS, list)\\n\\n    def test_deprecated_groq_models_exists(self):\\n        \\\"\\\"\\\"Test that DEPRECATED_GROQ_MODELS constant exists.\\\"\\\"\\\"\\n        from lfx.base.models.groq_constants import DEPRECATED_GROQ_MODELS\\n\\n        assert isinstance(DEPRECATED_GROQ_MODELS, list)\\n\\n    def test_unsupported_groq_models_exists(self):\\n        \\\"\\\"\\\"Test that UNSUPPORTED_GROQ_MODELS constant exists.\\\"\\\"\\\"\\n        from lfx.base.models.groq_constants import UNSUPPORTED_GROQ_MODELS\\n\\n        assert isinstance(UNSUPPORTED_GROQ_MODELS, list)\\n        assert len(UNSUPPORTED_GROQ_MODELS) > 0\\n\\n    def test_tool_calling_unsupported_groq_models_exists(self):\\n        \\\"\\\"\\\"Test that TOOL_CALLING_UNSUPPORTED_GROQ_MODELS constant exists.\\\"\\\"\\\"\\n        from lfx.base.models.groq_constants import TOOL_CALLING_UNSUPPORTED_GROQ_MODELS\\n\\n        assert isinstance(TOOL_CALLING_UNSUPPORTED_GROQ_MODELS, list)\\n\\n    def test_groq_models_combined_list(self):\\n        \\\"\\\"\\\"Test that GROQ_MODELS is the combination of production and preview.\\\"\\\"\\\"\\n        from lfx.base.models.groq_constants import GROQ_MODELS, GROQ_PREVIEW_MODELS, GROQ_PRODUCTION_MODELS\\n\\n        combined = GROQ_PRODUCTION_MODELS + GROQ_PREVIEW_MODELS\\n        assert combined == GROQ_MODELS\\n\\n    def test_model_names_alias(self):\\n        \\\"\\\"\\\"Test that MODEL_NAMES is an alias for GROQ_MODELS.\\\"\\\"\\\"\\n        from lfx.base.models.groq_constants import GROQ_MODELS, MODEL_NAMES\\n\\n        assert MODEL_NAMES == GROQ_MODELS\\n\\n\\nclass TestFallbackProductionModels:\\n    \\\"\\\"\\\"Test fallback production models.\\\"\\\"\\\"\\n\\n    def test_fallback_models_present(self):\\n        \\\"\\\"\\\"Test that essential fallback models are present.\\\"\\\"\\\"\\n        from lfx.base.models.groq_constants import GROQ_PRODUCTION_MODELS\\n\\n        # Essential fallback models mentioned in the code\\n        assert \\\"llama-3.1-8b-instant\\\" in GROQ_PRODUCTION_MODELS\\n        assert \\\"llama-3.3-70b-versatile\\\" in GROQ_PRODUCTION_MODELS\\n\\n    def test_fallback_models_have_metadata(self):\\n        \\\"\\\"\\\"Test that fallback models have complete metadata.\\\"\\\"\\\"\\n        from lfx.base.models.groq_constants import GROQ_MODELS_DETAILED\\n\\n        fallback_names = [\\\"llama-3.1-8b-instant\\\", \\\"llama-3.3-70b-versatile\\\"]\\n\\n        for model in GROQ_MODELS_DETAILED:\\n            if model[\\\"name\\\"] in fallback_names:\\n                assert model.get(\\\"provider\\\") is not None\\n                assert model.get(\\\"icon\\\") is not None\\n                # Fallback models should support tool calling\\n                assert model.get(\\\"tool_calling\\\") is True\\n                # Should not be deprecated or unsupported\\n                assert model.get(\\\"deprecated\\\", False) is False\\n                assert model.get(\\\"not_supported\\\", False) is False\\n                assert model.get(\\\"preview\\\", False) is False\\n\\n    def test_production_models_not_deprecated(self):\\n        \\\"\\\"\\\"Test that production models are not deprecated.\\\"\\\"\\\"\\n        from lfx.base.models.groq_constants import GROQ_MODELS_DETAILED, GROQ_PRODUCTION_MODELS\\n\\n        for model in GROQ_MODELS_DETAILED:\\n            if model[\\\"name\\\"] in GROQ_PRODUCTION_MODELS:\\n                assert model.get(\\\"deprecated\\\", False) is False\\n\\n    def test_production_models_not_unsupported(self):\\n        \\\"\\\"\\\"Test that production models are not marked as unsupported.\\\"\\\"\\\"\\n        from lfx.base.models.groq_constants import GROQ_MODELS_DETAILED, GROQ_PRODUCTION_MODELS\\n\\n        for model in GROQ_MODELS_DETAILED:\\n            if model[\\\"name\\\"] in GROQ_PRODUCTION_MODELS:\\n                assert model.get(\\\"not_supported\\\", False) is False\\n\\n    def test_production_models_not_preview(self):\\n        \\\"\\\"\\\"Test that production models are not preview models.\\\"\\\"\\\"\\n        from lfx.base.models.groq_constants import GROQ_MODELS_DETAILED, GROQ_PRODUCTION_MODELS\\n\\n        for model in GROQ_MODELS_DETAILED:\\n            if model[\\\"name\\\"] in GROQ_PRODUCTION_MODELS:\\n                assert model.get(\\\"preview\\\", False) is False\\n\\n\\nclass TestDeprecatedModels:\\n    \\\"\\\"\\\"Test deprecated models handling.\\\"\\\"\\\"\\n\\n    def test_deprecated_models_marked_correctly(self):\\n        \\\"\\\"\\\"Test that deprecated models have the deprecated flag.\\\"\\\"\\\"\\n        from lfx.base.models.groq_constants import DEPRECATED_GROQ_MODELS, GROQ_MODELS_DETAILED\\n\\n        for model in GROQ_MODELS_DETAILED:\\n            if model[\\\"name\\\"] in DEPRECATED_GROQ_MODELS:\\n                assert model.get(\\\"deprecated\\\") is True\\n\\n    def test_deprecated_models_not_in_production(self):\\n        \\\"\\\"\\\"Test that deprecated models are not in production list.\\\"\\\"\\\"\\n        from lfx.base.models.groq_constants import DEPRECATED_GROQ_MODELS, GROQ_PRODUCTION_MODELS\\n\\n        for model_name in DEPRECATED_GROQ_MODELS:\\n            assert model_name not in GROQ_PRODUCTION_MODELS\\n\\n    def test_deprecated_models_examples(self):\\n        \\\"\\\"\\\"Test that known deprecated models are in the list.\\\"\\\"\\\"\\n        from lfx.base.models.groq_constants import DEPRECATED_GROQ_MODELS\\n\\n        # Examples from the PR changes\\n        expected_deprecated = [\\n            \\\"gemma2-9b-it\\\",\\n            \\\"gemma-7b-it\\\",\\n            \\\"llama3-70b-8192\\\",\\n            \\\"llama3-8b-8192\\\",\\n            \\\"llama-guard-3-8b\\\",\\n        ]\\n\\n        for model in expected_deprecated:\\n            assert model in DEPRECATED_GROQ_MODELS\\n\\n\\nclass TestUnsupportedModels:\\n    \\\"\\\"\\\"Test unsupported (non-LLM) models.\\\"\\\"\\\"\\n\\n    def test_unsupported_models_marked_correctly(self):\\n        \\\"\\\"\\\"Test that unsupported models have the not_supported flag.\\\"\\\"\\\"\\n        from lfx.base.models.groq_constants import GROQ_MODELS_DETAILED, UNSUPPORTED_GROQ_MODELS\\n\\n        for model in GROQ_MODELS_DETAILED:\\n            if model[\\\"name\\\"] in UNSUPPORTED_GROQ_MODELS:\\n                assert model.get(\\\"not_supported\\\") is True\\n\\n    def test_unsupported_models_not_in_production(self):\\n        \\\"\\\"\\\"Test that unsupported models are not in production list.\\\"\\\"\\\"\\n        from lfx.base.models.groq_constants import GROQ_PRODUCTION_MODELS, UNSUPPORTED_GROQ_MODELS\\n\\n        for model_name in UNSUPPORTED_GROQ_MODELS:\\n            assert model_name not in GROQ_PRODUCTION_MODELS\\n\\n    def test_unsupported_models_not_in_main_list(self):\\n        \\\"\\\"\\\"Test that unsupported models are not in GROQ_MODELS.\\\"\\\"\\\"\\n        from lfx.base.models.groq_constants import GROQ_MODELS, UNSUPPORTED_GROQ_MODELS\\n\\n        for model_name in UNSUPPORTED_GROQ_MODELS:\\n            assert model_name not in GROQ_MODELS\\n\\n    def test_audio_models_unsupported(self):\\n        \\\"\\\"\\\"Test that audio models are marked as unsupported.\\\"\\\"\\\"\\n        from lfx.base.models.groq_constants import UNSUPPORTED_GROQ_MODELS\\n\\n        audio_models = [\\n            \\\"whisper-large-v3\\\",\\n            \\\"whisper-large-v3-turbo\\\",\\n            \\\"distil-whisper-large-v3-en\\\",\\n        ]\\n\\n        for model in audio_models:\\n            assert model in UNSUPPORTED_GROQ_MODELS\\n\\n    def test_tts_models_unsupported(self):\\n        \\\"\\\"\\\"Test that TTS models are marked as unsupported.\\\"\\\"\\\"\\n        from lfx.base.models.groq_constants import UNSUPPORTED_GROQ_MODELS\\n\\n        tts_models = [\\\"playai-tts\\\", \\\"playai-tts-arabic\\\"]\\n\\n        for model in tts_models:\\n            assert model in UNSUPPORTED_GROQ_MODELS\\n\\n    def test_guard_models_unsupported(self):\\n        \\\"\\\"\\\"Test that guard/safeguard models are marked as unsupported.\\\"\\\"\\\"\\n        from lfx.base.models.groq_constants import UNSUPPORTED_GROQ_MODELS\\n\\n        guard_models = [\\n            \\\"meta-llama/llama-guard-4-12b\\\",\\n            \\\"meta-llama/llama-prompt-guard-2-86m\\\",\\n            \\\"meta-llama/llama-prompt-guard-2-22m\\\",\\n            \\\"openai/gpt-oss-safeguard-20b\\\",\\n        ]\\n\\n        for model in guard_models:\\n            assert model in UNSUPPORTED_GROQ_MODELS\\n\\n    def test_safeguard_model_unsupported(self):\\n        \\\"\\\"\\\"Test that safeguard models like mistral-saba are marked as unsupported.\\\"\\\"\\\"\\n        from lfx.base.models.groq_constants import UNSUPPORTED_GROQ_MODELS\\n\\n        assert \\\"mistral-saba-24b\\\" in UNSUPPORTED_GROQ_MODELS\\n\\n\\nclass TestPreviewModels:\\n    \\\"\\\"\\\"Test preview models handling.\\\"\\\"\\\"\\n\\n    def test_preview_models_marked_correctly(self):\\n        \\\"\\\"\\\"Test that preview models have the preview flag.\\\"\\\"\\\"\\n        from lfx.base.models.groq_constants import GROQ_MODELS_DETAILED, GROQ_PREVIEW_MODELS\\n\\n        for model in GROQ_MODELS_DETAILED:\\n            if model[\\\"name\\\"] in GROQ_PREVIEW_MODELS:\\n                assert model.get(\\\"preview\\\") is True\\n\\n    def test_preview_models_not_in_production(self):\\n        \\\"\\\"\\\"Test that preview models are separate from production.\\\"\\\"\\\"\\n        from lfx.base.models.groq_constants import GROQ_PREVIEW_MODELS, GROQ_PRODUCTION_MODELS\\n\\n        for model_name in GROQ_PREVIEW_MODELS:\\n            assert model_name not in GROQ_PRODUCTION_MODELS\\n\\n    def test_preview_models_in_main_list(self):\\n        \\\"\\\"\\\"Test that preview models are included in GROQ_MODELS.\\\"\\\"\\\"\\n        from lfx.base.models.groq_constants import GROQ_MODELS, GROQ_PREVIEW_MODELS\\n\\n        for model_name in GROQ_PREVIEW_MODELS:\\n            assert model_name in GROQ_MODELS\\n\\n\\nclass TestToolCallingModels:\\n    \\\"\\\"\\\"Test tool calling support categorization.\\\"\\\"\\\"\\n\\n    def test_tool_calling_unsupported_not_in_production(self):\\n        \\\"\\\"\\\"Test that models without tool calling are tracked.\\\"\\\"\\\"\\n        from lfx.base.models.groq_constants import (\\n            GROQ_MODELS_DETAILED,\\n            TOOL_CALLING_UNSUPPORTED_GROQ_MODELS,\\n        )\\n\\n        for model in GROQ_MODELS_DETAILED:\\n            if model[\\\"name\\\"] in TOOL_CALLING_UNSUPPORTED_GROQ_MODELS:\\n                # These models should explicitly not support tool calling\\n                assert model.get(\\\"tool_calling\\\", False) is False\\n                # And should not be deprecated or unsupported\\n                assert model.get(\\\"deprecated\\\", False) is False\\n                assert model.get(\\\"not_supported\\\", False) is False\\n\\n\\nclass TestModelCategorization:\\n    \\\"\\\"\\\"Test that model categorization is mutually exclusive.\\\"\\\"\\\"\\n\\n    def test_no_overlap_production_deprecated(self):\\n        \\\"\\\"\\\"Test no overlap between production and deprecated models.\\\"\\\"\\\"\\n        from lfx.base.models.groq_constants import DEPRECATED_GROQ_MODELS, GROQ_PRODUCTION_MODELS\\n\\n        overlap = set(GROQ_PRODUCTION_MODELS) & set(DEPRECATED_GROQ_MODELS)\\n        assert len(overlap) == 0, f\\\"Found overlap: {overlap}\\\"\\n\\n    def test_no_overlap_production_unsupported(self):\\n        \\\"\\\"\\\"Test no overlap between production and unsupported models.\\\"\\\"\\\"\\n        from lfx.base.models.groq_constants import GROQ_PRODUCTION_MODELS, UNSUPPORTED_GROQ_MODELS\\n\\n        overlap = set(GROQ_PRODUCTION_MODELS) & set(UNSUPPORTED_GROQ_MODELS)\\n        assert len(overlap) == 0, f\\\"Found overlap: {overlap}\\\"\\n\\n    def test_no_overlap_preview_deprecated(self):\\n        \\\"\\\"\\\"Test no overlap between preview and deprecated models.\\\"\\\"\\\"\\n        from lfx.base.models.groq_constants import DEPRECATED_GROQ_MODELS, GROQ_PREVIEW_MODELS\\n\\n        overlap = set(GROQ_PREVIEW_MODELS) & set(DEPRECATED_GROQ_MODELS)\\n        assert len(overlap) == 0, f\\\"Found overlap: {overlap}\\\"\\n\\n    def test_no_overlap_preview_unsupported(self):\\n        \\\"\\\"\\\"Test no overlap between preview and unsupported models.\\\"\\\"\\\"\\n        from lfx.base.models.groq_constants import GROQ_PREVIEW_MODELS, UNSUPPORTED_GROQ_MODELS\\n\\n        overlap = set(GROQ_PREVIEW_MODELS) & set(UNSUPPORTED_GROQ_MODELS)\\n        assert len(overlap) == 0, f\\\"Found overlap: {overlap}\\\"\\n\\n    def test_all_models_categorized(self):\\n        \\\"\\\"\\\"Test that all models in GROQ_MODELS_DETAILED are categorized.\\\"\\\"\\\"\\n        from lfx.base.models.groq_constants import (\\n            DEPRECATED_GROQ_MODELS,\\n            GROQ_MODELS,\\n            GROQ_MODELS_DETAILED,\\n            UNSUPPORTED_GROQ_MODELS,\\n        )\\n\\n        for model in GROQ_MODELS_DETAILED:\\n            model_name = model[\\\"name\\\"]\\n\\n            # Each model should be in exactly one category\\n            in_main = model_name in GROQ_MODELS\\n            is_deprecated = model_name in DEPRECATED_GROQ_MODELS\\n            is_unsupported = model_name in UNSUPPORTED_GROQ_MODELS\\n\\n            categories = sum([in_main, is_deprecated, is_unsupported])\\n\\n            assert categories == 1, f\\\"Model {model_name} is in {categories} categories (should be exactly 1)\\\"\\n\\n\\nclass TestProviderMetadata:\\n    \\\"\\\"\\\"Test provider metadata for models.\\\"\\\"\\\"\\n\\n    def test_all_models_have_provider(self):\\n        \\\"\\\"\\\"Test that all models have a provider field.\\\"\\\"\\\"\\n        from lfx.base.models.groq_constants import GROQ_MODELS_DETAILED\\n\\n        for model in GROQ_MODELS_DETAILED:\\n            assert \\\"provider\\\" in model\\n            assert isinstance(model[\\\"provider\\\"], str)\\n            assert len(model[\\\"provider\\\"]) > 0\\n\\n    def test_all_models_have_icon(self):\\n        \\\"\\\"\\\"Test that all models have an icon field.\\\"\\\"\\\"\\n        from lfx.base.models.groq_constants import GROQ_MODELS_DETAILED\\n\\n        for model in GROQ_MODELS_DETAILED:\\n            assert \\\"icon\\\" in model\\n            assert isinstance(model[\\\"icon\\\"], str)\\n            assert len(model[\\\"icon\\\"]) > 0\\n\\n    def test_provider_values_reasonable(self):\\n        \\\"\\\"\\\"Test that provider values are from expected set.\\\"\\\"\\\"\\n        from lfx.base.models.groq_constants import GROQ_MODELS_DETAILED\\n\\n        for model in GROQ_MODELS_DETAILED:\\n            # Just ensure provider is a non-empty string\\n            # (actual values may vary)\\n            assert isinstance(model[\\\"provider\\\"], str)\\n            assert len(model[\\\"provider\\\"]) > 0\\n\\n\\nclass TestBackwardCompatibility:\\n    \\\"\\\"\\\"Test backward compatibility of constants.\\\"\\\"\\\"\\n\\n    def test_groq_models_is_list(self):\\n        \\\"\\\"\\\"Test that GROQ_MODELS is a list for backward compatibility.\\\"\\\"\\\"\\n        from lfx.base.models.groq_constants import GROQ_MODELS\\n\\n        assert isinstance(GROQ_MODELS, list)\\n\\n    def test_groq_models_contains_strings(self):\\n        \\\"\\\"\\\"Test that GROQ_MODELS contains model name strings.\\\"\\\"\\\"\\n        from lfx.base.models.groq_constants import GROQ_MODELS\\n\\n        for model in GROQ_MODELS:\\n            assert isinstance(model, str)\\n            assert len(model) > 0\\n\\n    def test_no_duplicates_in_groq_models(self):\\n        \\\"\\\"\\\"Test that GROQ_MODELS has no duplicates.\\\"\\\"\\\"\\n        from lfx.base.models.groq_constants import GROQ_MODELS\\n\\n        assert len(GROQ_MODELS) == len(set(GROQ_MODELS))\\n\\n    def test_no_duplicates_in_groq_models_detailed(self):\\n        \\\"\\\"\\\"Test that GROQ_MODELS_DETAILED has no duplicate model names.\\\"\\\"\\\"\\n        from lfx.base.models.groq_constants import GROQ_MODELS_DETAILED\\n\\n        model_names = [model[\\\"name\\\"] for model in GROQ_MODELS_DETAILED]\\n        assert len(model_names) == len(set(model_names))\\n\\n\\nclass TestFallbackListMinimalSize:\\n    \\\"\\\"\\\"Test that fallback lists are minimal but sufficient.\\\"\\\"\\\"\\n\\n    def test_production_models_minimal(self):\\n        \\\"\\\"\\\"Test that production models list is minimal (2 fallback models).\\\"\\\"\\\"\\n        from lfx.base.models.groq_constants import GROQ_PRODUCTION_MODELS\\n\\n        # According to the code comments, should have minimal fallback set\\n        # At least 2 models as per the fallback in discovery module\\n        assert len(GROQ_PRODUCTION_MODELS) >= 2\\n\\n    def test_fallback_models_match_discovery(self):\\n        \\\"\\\"\\\"Test that fallback models in constants match those in discovery module.\\\"\\\"\\\"\\n        from lfx.base.models.groq_constants import GROQ_PRODUCTION_MODELS\\n\\n        # The discovery module defines these as fallback\\n        discovery_fallback = [\\\"llama-3.1-8b-instant\\\", \\\"llama-3.3-70b-versatile\\\"]\\n\\n        for model in discovery_fallback:\\n            assert model in GROQ_PRODUCTION_MODELS\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/groq/test_groq_convenience_function.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a2c449de7d3566f0ca3842ba0e041e6a2a1ea5e6753ba3505ef18d84cc994d57\",\"content\":\"\\\"\\\"\\\"Tests for the get_groq_models() convenience function.\\\"\\\"\\\"\\n\\nfrom unittest.mock import patch\\n\\nfrom lfx.base.models.groq_model_discovery import GroqModelDiscovery, get_groq_models\\n\\n\\nclass TestGetGroqModelsConvenienceFunction:\\n    \\\"\\\"\\\"Test the convenience function get_groq_models().\\\"\\\"\\\"\\n\\n    @patch.object(GroqModelDiscovery, \\\"get_models\\\")\\n    def test_get_groq_models_with_api_key(self, mock_get_models, mock_api_key):\\n        \\\"\\\"\\\"Test get_groq_models() function with API key.\\\"\\\"\\\"\\n        mock_get_models.return_value = {\\\"llama-3.1-8b-instant\\\": {}}\\n\\n        models = get_groq_models(api_key=mock_api_key)\\n\\n        assert \\\"llama-3.1-8b-instant\\\" in models\\n        mock_get_models.assert_called_once_with(force_refresh=False)\\n\\n    @patch.object(GroqModelDiscovery, \\\"get_models\\\")\\n    def test_get_groq_models_without_api_key(self, mock_get_models):\\n        \\\"\\\"\\\"Test get_groq_models() function without API key.\\\"\\\"\\\"\\n        mock_get_models.return_value = {\\\"llama-3.1-8b-instant\\\": {}}\\n\\n        models = get_groq_models()\\n\\n        assert \\\"llama-3.1-8b-instant\\\" in models\\n        mock_get_models.assert_called_once_with(force_refresh=False)\\n\\n    @patch.object(GroqModelDiscovery, \\\"get_models\\\")\\n    def test_get_groq_models_force_refresh(self, mock_get_models, mock_api_key):\\n        \\\"\\\"\\\"Test get_groq_models() with force_refresh.\\\"\\\"\\\"\\n        mock_get_models.return_value = {\\\"llama-3.1-8b-instant\\\": {}}\\n\\n        models = get_groq_models(api_key=mock_api_key, force_refresh=True)\\n\\n        assert \\\"llama-3.1-8b-instant\\\" in models\\n        mock_get_models.assert_called_once_with(force_refresh=True)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/groq/test_groq_discovery_errors.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b67a458a482a3077734bac1e6fe6d980a28f39cc4493ceb928d8e383ad83b0cd\",\"content\":\"\\\"\\\"\\\"Tests for error handling in Groq model discovery.\\\"\\\"\\\"\\n\\nimport json\\nimport sys\\nfrom unittest.mock import Mock, patch\\n\\nimport pytest\\nfrom lfx.base.models.groq_model_discovery import GroqModelDiscovery\\n\\n\\nclass TestGroqModelDiscoveryErrors:\\n    \\\"\\\"\\\"Test error handling in model discovery.\\\"\\\"\\\"\\n\\n    def test_no_api_key_returns_fallback(self):\\n        \\\"\\\"\\\"Test that missing API key returns fallback models.\\\"\\\"\\\"\\n        discovery = GroqModelDiscovery(api_key=None)\\n        models = discovery.get_models(force_refresh=True)\\n\\n        # Should return minimal fallback list\\n        assert \\\"llama-3.1-8b-instant\\\" in models\\n        assert \\\"llama-3.3-70b-versatile\\\" in models\\n        assert len(models) == 2\\n\\n    @patch(\\\"lfx.base.models.groq_model_discovery.requests.get\\\")\\n    def test_api_connection_error_returns_fallback(self, mock_get, mock_api_key, mock_requests_get_failure):\\n        \\\"\\\"\\\"Test that API connection errors return fallback models.\\\"\\\"\\\"\\n        mock_get.side_effect = mock_requests_get_failure\\n\\n        discovery = GroqModelDiscovery(api_key=mock_api_key)\\n        models = discovery.get_models(force_refresh=True)\\n\\n        # Should return fallback models\\n        assert \\\"llama-3.1-8b-instant\\\" in models\\n        assert \\\"llama-3.3-70b-versatile\\\" in models\\n\\n    @patch(\\\"lfx.base.models.groq_model_discovery.requests.get\\\")\\n    def test_api_timeout_returns_fallback(self, mock_get, mock_api_key, mock_requests_get_timeout):\\n        \\\"\\\"\\\"Test that API timeouts return fallback models.\\\"\\\"\\\"\\n        mock_get.side_effect = mock_requests_get_timeout\\n\\n        discovery = GroqModelDiscovery(api_key=mock_api_key)\\n        models = discovery.get_models(force_refresh=True)\\n\\n        # Should return fallback models\\n        assert \\\"llama-3.1-8b-instant\\\" in models\\n        assert \\\"llama-3.3-70b-versatile\\\" in models\\n\\n    @patch(\\\"lfx.base.models.groq_model_discovery.requests.get\\\")\\n    def test_api_unauthorized_returns_fallback(self, mock_get, mock_api_key, mock_requests_get_unauthorized):\\n        \\\"\\\"\\\"Test that unauthorized API requests return fallback models.\\\"\\\"\\\"\\n        mock_get.side_effect = mock_requests_get_unauthorized\\n\\n        discovery = GroqModelDiscovery(api_key=mock_api_key)\\n        models = discovery.get_models(force_refresh=True)\\n\\n        # Should return fallback models\\n        assert \\\"llama-3.1-8b-instant\\\" in models\\n        assert \\\"llama-3.3-70b-versatile\\\" in models\\n\\n    @patch(\\\"lfx.base.models.groq_model_discovery.requests.get\\\")\\n    def test_invalid_api_response_returns_fallback(self, mock_get, mock_api_key):\\n        \\\"\\\"\\\"Test that invalid API response structure returns fallback models.\\\"\\\"\\\"\\n        # Mock response with missing 'data' field\\n        mock_response = Mock()\\n        mock_response.json.return_value = {\\\"error\\\": \\\"invalid\\\"}\\n        mock_response.raise_for_status = Mock()\\n        mock_get.return_value = mock_response\\n\\n        discovery = GroqModelDiscovery(api_key=mock_api_key)\\n        models = discovery.get_models(force_refresh=True)\\n\\n        # Should return fallback models\\n        assert \\\"llama-3.1-8b-instant\\\" in models\\n\\n    def test_corrupted_cache_returns_none(self, mock_api_key, mock_corrupted_cache_file):\\n        \\\"\\\"\\\"Test that corrupted cache file returns None.\\\"\\\"\\\"\\n        discovery = GroqModelDiscovery(api_key=mock_api_key)\\n        discovery.CACHE_FILE = mock_corrupted_cache_file\\n\\n        loaded = discovery._load_cache()\\n\\n        assert loaded is None\\n\\n    def test_cache_missing_fields_returns_none(self, mock_api_key, temp_cache_dir):\\n        \\\"\\\"\\\"Test that cache with missing required fields returns None.\\\"\\\"\\\"\\n        cache_file = temp_cache_dir / \\\".cache\\\" / \\\"invalid_cache.json\\\"\\n        cache_file.parent.mkdir(parents=True, exist_ok=True)\\n\\n        # Cache missing 'cached_at' field\\n        cache_data = {\\\"models\\\": {\\\"llama-3.1-8b-instant\\\": {}}}\\n\\n        with cache_file.open(\\\"w\\\") as f:\\n            json.dump(cache_data, f)\\n\\n        discovery = GroqModelDiscovery(api_key=mock_api_key)\\n        discovery.CACHE_FILE = cache_file\\n\\n        loaded = discovery._load_cache()\\n\\n        assert loaded is None\\n\\n    def test_cache_save_failure_logs_warning(self, mock_api_key, temp_cache_dir, sample_models_metadata):\\n        \\\"\\\"\\\"Test that cache save failures are logged but don't crash.\\\"\\\"\\\"\\n        discovery = GroqModelDiscovery(api_key=mock_api_key)\\n        # Set cache file to a path that can't be written (directory instead of file)\\n        discovery.CACHE_FILE = temp_cache_dir\\n\\n        # This should not raise an exception\\n        discovery._save_cache(sample_models_metadata)\\n\\n    @patch(\\\"lfx.base.models.groq_model_discovery.requests.get\\\")\\n    def test_import_error_during_chat_test_returns_fallback(self, mock_get, mock_api_key, temp_cache_dir):\\n        \\\"\\\"\\\"Test that get_models returns fallback models when groq is not installed.\\n\\n        Both _test_chat_completion and _test_tool_calling re-raise ImportError when\\n        the groq package is absent. get_models catches it and falls back to hardcoded\\n        model metadata instead of crashing.\\n        \\\"\\\"\\\"\\n        mock_response = Mock()\\n        mock_response.json.return_value = {\\\"data\\\": [{\\\"id\\\": \\\"llama-3.1-8b-instant\\\", \\\"object\\\": \\\"model\\\"}]}\\n        mock_response.raise_for_status = Mock()\\n        mock_get.return_value = mock_response\\n\\n        with patch.dict(sys.modules, {\\\"groq\\\": None}):\\n            discovery = GroqModelDiscovery(api_key=mock_api_key)\\n            discovery.CACHE_FILE = temp_cache_dir / \\\".cache\\\" / \\\"test_cache.json\\\"\\n            models = discovery.get_models(force_refresh=True)\\n\\n        # Should return the hardcoded fallback list, not an empty dict\\n        assert \\\"llama-3.1-8b-instant\\\" in models\\n        assert \\\"llama-3.3-70b-versatile\\\" in models\\n        assert len(models) == 2  # exactly the two fallback models\\n\\n    @patch(\\\"groq.Groq\\\")\\n    def test_tool_calling_import_error_raises(self, mock_groq, mock_api_key):\\n        \\\"\\\"\\\"Test that ImportError during tool calling test is re-raised.\\\"\\\"\\\"\\n        mock_groq.side_effect = ImportError(\\\"groq module not found\\\")\\n\\n        discovery = GroqModelDiscovery(api_key=mock_api_key)\\n        with pytest.raises(ImportError):\\n            discovery._test_tool_calling(\\\"test-model\\\")\\n\\n    @patch(\\\"groq.Groq\\\")\\n    def test_tool_calling_rate_limit_returns_none(self, mock_groq, mock_api_key, mock_groq_client_rate_limit):\\n        \\\"\\\"\\\"Test that rate limit errors return None (indeterminate).\\\"\\\"\\\"\\n        mock_groq.return_value = mock_groq_client_rate_limit()\\n\\n        discovery = GroqModelDiscovery(api_key=mock_api_key)\\n        result = discovery._test_tool_calling(\\\"test-model\\\")\\n\\n        assert result is None\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/groq/test_groq_discovery_success.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d7f19a35b745754f24a9dd9219a48a77b480af86720fb6bc3ad596832795f33e\",\"content\":\"\\\"\\\"\\\"Tests for successful Groq model discovery operations.\\\"\\\"\\\"\\n\\nfrom unittest.mock import Mock, patch\\n\\nfrom lfx.base.models.groq_model_discovery import GroqModelDiscovery\\n\\n\\nclass TestGroqModelDiscoverySuccess:\\n    \\\"\\\"\\\"Test successful model discovery operations.\\\"\\\"\\\"\\n\\n    def test_init_with_api_key(self, mock_api_key):\\n        \\\"\\\"\\\"Test initialization with API key.\\\"\\\"\\\"\\n        discovery = GroqModelDiscovery(api_key=mock_api_key)\\n        assert discovery.api_key == mock_api_key\\n        assert discovery.base_url == \\\"https://api.groq.com\\\"\\n\\n    def test_init_without_api_key(self):\\n        \\\"\\\"\\\"Test initialization without API key.\\\"\\\"\\\"\\n        discovery = GroqModelDiscovery()\\n        assert discovery.api_key is None\\n        assert discovery.base_url == \\\"https://api.groq.com\\\"\\n\\n    def test_init_with_custom_base_url(self, mock_api_key):\\n        \\\"\\\"\\\"Test initialization with custom base URL.\\\"\\\"\\\"\\n        custom_url = \\\"https://custom.groq.com\\\"\\n        discovery = GroqModelDiscovery(api_key=mock_api_key, base_url=custom_url)\\n        assert discovery.base_url == custom_url\\n\\n    @patch(\\\"lfx.base.models.groq_model_discovery.requests.get\\\")\\n    @patch(\\\"groq.Groq\\\")\\n    def test_fetch_available_models_success(\\n        self, mock_groq, mock_get, mock_api_key, mock_groq_models_response, mock_groq_client_tool_calling_success\\n    ):\\n        \\\"\\\"\\\"Test successfully fetching models from API.\\\"\\\"\\\"\\n        # Mock API response\\n        mock_response = Mock()\\n        mock_response.status_code = 200\\n        mock_response.json.return_value = mock_groq_models_response\\n        mock_response.raise_for_status = Mock()\\n        mock_get.return_value = mock_response\\n\\n        # Mock tool calling tests\\n        mock_groq.return_value = mock_groq_client_tool_calling_success()\\n\\n        discovery = GroqModelDiscovery(api_key=mock_api_key)\\n        models = discovery._fetch_available_models()\\n\\n        assert isinstance(models, list)\\n        assert len(models) == 8\\n        assert \\\"llama-3.1-8b-instant\\\" in models\\n        assert \\\"whisper-large-v3\\\" in models\\n        mock_get.assert_called_once()\\n\\n    @patch(\\\"lfx.base.models.groq_model_discovery.requests.get\\\")\\n    @patch(\\\"groq.Groq\\\")\\n    def test_get_models_categorizes_llm_and_non_llm(\\n        self,\\n        mock_groq,\\n        mock_get,\\n        mock_api_key,\\n        mock_groq_models_response,\\n        mock_groq_client_tool_calling_success,\\n        temp_cache_dir,\\n    ):\\n        \\\"\\\"\\\"Test that models are correctly categorized as LLM vs non-LLM.\\\"\\\"\\\"\\n        # Mock API response\\n        mock_response = Mock()\\n        mock_response.json.return_value = mock_groq_models_response\\n        mock_response.raise_for_status = Mock()\\n        mock_get.return_value = mock_response\\n\\n        # Mock tool calling tests to always succeed\\n        mock_groq.return_value = mock_groq_client_tool_calling_success()\\n\\n        discovery = GroqModelDiscovery(api_key=mock_api_key)\\n        discovery.CACHE_FILE = temp_cache_dir / \\\".cache\\\" / \\\"test_cache.json\\\"\\n\\n        models = discovery.get_models(force_refresh=True)\\n\\n        # LLM models should be in the result\\n        assert \\\"llama-3.1-8b-instant\\\" in models\\n        assert \\\"llama-3.3-70b-versatile\\\" in models\\n        assert \\\"mixtral-8x7b-32768\\\" in models\\n        assert \\\"gemma-7b-it\\\" in models\\n\\n        # Non-LLM models should be marked as not_supported\\n        assert models[\\\"whisper-large-v3\\\"][\\\"not_supported\\\"] is True\\n        assert models[\\\"distil-whisper-large-v3-en\\\"][\\\"not_supported\\\"] is True\\n        assert models[\\\"meta-llama/llama-guard-4-12b\\\"][\\\"not_supported\\\"] is True\\n        assert models[\\\"meta-llama/llama-prompt-guard-2-86m\\\"][\\\"not_supported\\\"] is True\\n\\n        # LLM models should have tool_calling field\\n        assert \\\"tool_calling\\\" in models[\\\"llama-3.1-8b-instant\\\"]\\n        assert \\\"tool_calling\\\" in models[\\\"mixtral-8x7b-32768\\\"]\\n\\n    @patch(\\\"groq.Groq\\\")\\n    def test_tool_calling_detection_success(self, mock_groq, mock_api_key, mock_groq_client_tool_calling_success):\\n        \\\"\\\"\\\"Test successful tool calling detection.\\\"\\\"\\\"\\n        mock_groq.return_value = mock_groq_client_tool_calling_success()\\n\\n        discovery = GroqModelDiscovery(api_key=mock_api_key)\\n        result = discovery._test_tool_calling(\\\"llama-3.1-8b-instant\\\")\\n\\n        assert result is True\\n\\n    @patch(\\\"groq.Groq\\\")\\n    def test_tool_calling_detection_not_supported(self, mock_groq, mock_api_key, mock_groq_client_tool_calling_failure):\\n        \\\"\\\"\\\"Test tool calling detection when model doesn't support tools.\\\"\\\"\\\"\\n        mock_groq.return_value = mock_groq_client_tool_calling_failure()\\n\\n        discovery = GroqModelDiscovery(api_key=mock_api_key)\\n        result = discovery._test_tool_calling(\\\"gemma-7b-it\\\")\\n\\n        assert result is False\\n\\n    def test_cache_save_and_load(self, mock_api_key, sample_models_metadata, temp_cache_dir):\\n        \\\"\\\"\\\"Test saving and loading cache.\\\"\\\"\\\"\\n        discovery = GroqModelDiscovery(api_key=mock_api_key)\\n        discovery.CACHE_FILE = temp_cache_dir / \\\".cache\\\" / \\\"test_cache.json\\\"\\n\\n        # Save cache\\n        discovery._save_cache(sample_models_metadata)\\n\\n        # Verify file was created\\n        assert discovery.CACHE_FILE.exists()\\n\\n        # Load cache\\n        loaded = discovery._load_cache()\\n\\n        assert loaded is not None\\n        assert len(loaded) == len(sample_models_metadata)\\n        assert \\\"llama-3.1-8b-instant\\\" in loaded\\n        assert loaded[\\\"llama-3.1-8b-instant\\\"][\\\"tool_calling\\\"] is True\\n\\n    def test_cache_respects_expiration(self, mock_api_key, mock_expired_cache_file):\\n        \\\"\\\"\\\"Test that expired cache returns None.\\\"\\\"\\\"\\n        discovery = GroqModelDiscovery(api_key=mock_api_key)\\n        discovery.CACHE_FILE = mock_expired_cache_file\\n\\n        loaded = discovery._load_cache()\\n\\n        assert loaded is None\\n\\n    @patch(\\\"lfx.base.models.groq_model_discovery.requests.get\\\")\\n    @patch(\\\"groq.Groq\\\")\\n    def test_get_models_uses_cache_when_available(self, mock_groq, mock_get, mock_api_key, mock_cache_file):\\n        \\\"\\\"\\\"Test that get_models uses cache when available and not expired.\\\"\\\"\\\"\\n        discovery = GroqModelDiscovery(api_key=mock_api_key)\\n        discovery.CACHE_FILE = mock_cache_file\\n\\n        models = discovery.get_models(force_refresh=False)\\n\\n        # Should use cache, not call API\\n        mock_get.assert_not_called()\\n        mock_groq.assert_not_called()\\n\\n        assert \\\"llama-3.1-8b-instant\\\" in models\\n        assert \\\"llama-3.3-70b-versatile\\\" in models\\n\\n    @patch(\\\"lfx.base.models.groq_model_discovery.requests.get\\\")\\n    @patch(\\\"groq.Groq\\\")\\n    def test_force_refresh_bypasses_cache(\\n        self,\\n        mock_groq,\\n        mock_get,\\n        mock_api_key,\\n        mock_groq_models_response,\\n        mock_groq_client_tool_calling_success,\\n        mock_cache_file,\\n    ):\\n        \\\"\\\"\\\"Test that force_refresh bypasses cache and fetches fresh data.\\\"\\\"\\\"\\n        # Mock API response\\n        mock_response = Mock()\\n        mock_response.json.return_value = mock_groq_models_response\\n        mock_response.raise_for_status = Mock()\\n        mock_get.return_value = mock_response\\n\\n        # Mock tool calling\\n        mock_groq.return_value = mock_groq_client_tool_calling_success()\\n\\n        discovery = GroqModelDiscovery(api_key=mock_api_key)\\n        discovery.CACHE_FILE = mock_cache_file\\n\\n        models = discovery.get_models(force_refresh=True)\\n\\n        # Should call API despite cache\\n        mock_get.assert_called()\\n        assert len(models) > 0\\n\\n    def test_provider_name_extraction(self, mock_api_key):\\n        \\\"\\\"\\\"Test provider name extraction from model IDs.\\\"\\\"\\\"\\n        discovery = GroqModelDiscovery(api_key=mock_api_key)\\n\\n        # Models with slash notation\\n        assert discovery._get_provider_name(\\\"meta-llama/llama-3.1-8b\\\") == \\\"Meta\\\"\\n        assert discovery._get_provider_name(\\\"openai/gpt-oss-safeguard-20b\\\") == \\\"OpenAI\\\"\\n        assert discovery._get_provider_name(\\\"qwen/qwen3-32b\\\") == \\\"Alibaba Cloud\\\"\\n        assert discovery._get_provider_name(\\\"moonshotai/moonshot-v1\\\") == \\\"Moonshot AI\\\"\\n        assert discovery._get_provider_name(\\\"groq/groq-model\\\") == \\\"Groq\\\"\\n\\n        # Models with prefixes\\n        assert discovery._get_provider_name(\\\"llama-3.1-8b-instant\\\") == \\\"Meta\\\"\\n        assert discovery._get_provider_name(\\\"llama3-70b-8192\\\") == \\\"Meta\\\"\\n        assert discovery._get_provider_name(\\\"qwen-2.5-32b\\\") == \\\"Alibaba Cloud\\\"\\n        assert discovery._get_provider_name(\\\"allam-1-13b\\\") == \\\"SDAIA\\\"\\n\\n        # Unknown providers default to Groq\\n        assert discovery._get_provider_name(\\\"unknown-model\\\") == \\\"Groq\\\"\\n\\n    def test_skip_patterns(self, mock_api_key):\\n        \\\"\\\"\\\"Test that SKIP_PATTERNS correctly identify non-LLM models.\\\"\\\"\\\"\\n        discovery = GroqModelDiscovery(api_key=mock_api_key)\\n\\n        skip_models = [\\n            \\\"whisper-large-v3\\\",\\n            \\\"whisper-large-v3-turbo\\\",\\n            \\\"distil-whisper-large-v3-en\\\",\\n            \\\"playai-tts\\\",\\n            \\\"playai-tts-arabic\\\",\\n            \\\"meta-llama/llama-guard-4-12b\\\",\\n            \\\"meta-llama/llama-prompt-guard-2-86m\\\",\\n            \\\"openai/gpt-oss-safeguard-20b\\\",\\n            \\\"mistral-saba-24b\\\",  # safeguard model\\n        ]\\n\\n        for model in skip_models:\\n            should_skip = any(pattern in model.lower() for pattern in discovery.SKIP_PATTERNS)\\n            assert should_skip, f\\\"Model {model} should be skipped but wasn't\\\"\\n\\n        # LLM models should not be skipped\\n        llm_models = [\\\"llama-3.1-8b-instant\\\", \\\"mixtral-8x7b-32768\\\", \\\"gemma-7b-it\\\"]\\n        for model in llm_models:\\n            should_skip = any(pattern in model.lower() for pattern in discovery.SKIP_PATTERNS)\\n            assert not should_skip, f\\\"Model {model} should not be skipped\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/groq/test_groq_integration.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a5511ff7a41d0e045bf22357a9b3586ff5e42abf1f3a7ce816372b914bd4a06b\",\"content\":\"\\\"\\\"\\\"Integration tests for Groq component with dynamic model discovery.\\n\\nTests cover:\\n- Success paths: get_models with/without API key, tool_model_enabled filtering\\n- Error paths: invalid API key, discovery failures, missing dependencies\\n- Edge cases: empty results, build config updates\\n\\\"\\\"\\\"\\n\\nfrom unittest.mock import patch\\n\\nimport pytest\\n\\npytest.importorskip(\\\"lfx_bundles\\\")\\n\\n# Capture the module object ONCE and bind both the class and every patch\\n# target from it. groq lives in the lfx-bundles metapackage now, so the\\n# same source file can materialize under several sys.modules identities\\n# (shim path, lfx_bundles path, extension-loader path) depending on test\\n# order; dotted-name @patch resolves through sys.modules at call time and\\n# can land on a different module object than the one that defined the\\n# class, leaving the real get_groq_models in the instance's __globals__.\\nimport lfx.components.groq.groq as groq_module\\n\\n\\nclass TestGroqModelIntegration:\\n    \\\"\\\"\\\"Test the GroqModel component integration with dynamic discovery.\\\"\\\"\\\"\\n\\n    @pytest.fixture\\n    def groq_model_instance(self):\\n        \\\"\\\"\\\"Create a GroqModel instance for testing.\\\"\\\"\\\"\\n        return groq_module.GroqModel()\\n\\n    def test_groq_model_initialization(self, groq_model_instance):\\n        \\\"\\\"\\\"Test GroqModel initializes with correct attributes.\\\"\\\"\\\"\\n        assert groq_model_instance.display_name == \\\"Groq\\\"\\n        assert groq_model_instance.description == \\\"Generate text using Groq.\\\"\\n        assert groq_model_instance.icon == \\\"Groq\\\"\\n        assert groq_model_instance.name == \\\"GroqModel\\\"\\n\\n    def test_groq_model_has_required_inputs(self, groq_model_instance):\\n        \\\"\\\"\\\"Test that GroqModel has all required inputs.\\\"\\\"\\\"\\n        input_names = [inp.name for inp in groq_model_instance.inputs]\\n\\n        assert \\\"api_key\\\" in input_names\\n        assert \\\"base_url\\\" in input_names\\n        assert \\\"max_tokens\\\" in input_names\\n        assert \\\"temperature\\\" in input_names\\n        assert \\\"model_name\\\" in input_names\\n        assert \\\"tool_model_enabled\\\" in input_names\\n\\n    @patch.object(groq_module, \\\"get_groq_models\\\")\\n    def test_get_models_with_api_key(self, mock_get_groq_models, groq_model_instance, mock_api_key):\\n        \\\"\\\"\\\"Test get_models() with valid API key.\\\"\\\"\\\"\\n        mock_get_groq_models.return_value = {\\n            \\\"llama-3.1-8b-instant\\\": {\\\"tool_calling\\\": True, \\\"not_supported\\\": False},\\n            \\\"llama-3.3-70b-versatile\\\": {\\\"tool_calling\\\": True, \\\"not_supported\\\": False},\\n            \\\"gemma-7b-it\\\": {\\\"tool_calling\\\": False, \\\"not_supported\\\": False},\\n            \\\"whisper-large-v3\\\": {\\\"not_supported\\\": True},\\n        }\\n\\n        groq_model_instance.api_key = mock_api_key\\n\\n        models = groq_model_instance.get_models()\\n\\n        # Should exclude not_supported models\\n        assert \\\"llama-3.1-8b-instant\\\" in models\\n        assert \\\"llama-3.3-70b-versatile\\\" in models\\n        assert \\\"gemma-7b-it\\\" in models\\n        assert \\\"whisper-large-v3\\\" not in models\\n\\n        # Verify get_groq_models was called with api_key\\n        mock_get_groq_models.assert_called_once_with(api_key=mock_api_key)\\n\\n    @patch.object(groq_module, \\\"get_groq_models\\\")\\n    def test_get_models_without_api_key(self, mock_get_groq_models, groq_model_instance):\\n        \\\"\\\"\\\"Test get_models() without API key.\\\"\\\"\\\"\\n        mock_get_groq_models.return_value = {\\n            \\\"llama-3.1-8b-instant\\\": {\\\"tool_calling\\\": True, \\\"not_supported\\\": False},\\n            \\\"llama-3.3-70b-versatile\\\": {\\\"tool_calling\\\": True, \\\"not_supported\\\": False},\\n        }\\n\\n        models = groq_model_instance.get_models()\\n\\n        assert len(models) > 0\\n        # Verify get_groq_models was called with None\\n        mock_get_groq_models.assert_called_once_with(api_key=None)\\n\\n    @patch.object(groq_module, \\\"get_groq_models\\\")\\n    def test_get_models_with_tool_model_enabled(self, mock_get_groq_models, groq_model_instance, mock_api_key):\\n        \\\"\\\"\\\"Test get_models() with tool_model_enabled=True filters correctly.\\\"\\\"\\\"\\n        mock_get_groq_models.return_value = {\\n            \\\"llama-3.1-8b-instant\\\": {\\\"tool_calling\\\": True, \\\"not_supported\\\": False},\\n            \\\"llama-3.3-70b-versatile\\\": {\\\"tool_calling\\\": True, \\\"not_supported\\\": False},\\n            \\\"gemma-7b-it\\\": {\\\"tool_calling\\\": False, \\\"not_supported\\\": False},\\n            \\\"mixtral-8x7b-32768\\\": {\\\"tool_calling\\\": True, \\\"not_supported\\\": False},\\n        }\\n\\n        groq_model_instance.api_key = mock_api_key\\n\\n        models = groq_model_instance.get_models(tool_model_enabled=True)\\n\\n        # Should only include tool_calling models\\n        assert \\\"llama-3.1-8b-instant\\\" in models\\n        assert \\\"llama-3.3-70b-versatile\\\" in models\\n        assert \\\"mixtral-8x7b-32768\\\" in models\\n        assert \\\"gemma-7b-it\\\" not in models\\n\\n    @patch.object(groq_module, \\\"get_groq_models\\\")\\n    def test_get_models_with_tool_model_disabled(self, mock_get_groq_models, groq_model_instance, mock_api_key):\\n        \\\"\\\"\\\"Test get_models() with tool_model_enabled=False returns all models.\\\"\\\"\\\"\\n        mock_get_groq_models.return_value = {\\n            \\\"llama-3.1-8b-instant\\\": {\\\"tool_calling\\\": True, \\\"not_supported\\\": False},\\n            \\\"gemma-7b-it\\\": {\\\"tool_calling\\\": False, \\\"not_supported\\\": False},\\n        }\\n\\n        groq_model_instance.api_key = mock_api_key\\n\\n        models = groq_model_instance.get_models(tool_model_enabled=False)\\n\\n        # Should include all non-unsupported models\\n        assert \\\"llama-3.1-8b-instant\\\" in models\\n        assert \\\"gemma-7b-it\\\" in models\\n\\n    @patch.object(groq_module, \\\"get_groq_models\\\")\\n    def test_get_models_error_falls_back_to_constants(self, mock_get_groq_models, groq_model_instance, mock_api_key):\\n        \\\"\\\"\\\"Test that get_models() falls back to GROQ_MODELS on error.\\\"\\\"\\\"\\n        # Simulate error in get_groq_models\\n        mock_get_groq_models.side_effect = ValueError(\\\"API error\\\")\\n\\n        groq_model_instance.api_key = mock_api_key\\n\\n        models = groq_model_instance.get_models()\\n\\n        # Should return fallback models from groq_constants.py\\n        assert isinstance(models, list)\\n        assert len(models) > 0\\n\\n    @patch.object(groq_module, \\\"get_groq_models\\\")\\n    def test_update_build_config_with_api_key(self, mock_get_groq_models, groq_model_instance, mock_api_key):\\n        \\\"\\\"\\\"Test update_build_config updates model list when API key is provided.\\\"\\\"\\\"\\n        mock_get_groq_models.return_value = {\\n            \\\"llama-3.1-8b-instant\\\": {\\\"tool_calling\\\": True, \\\"not_supported\\\": False},\\n            \\\"llama-3.3-70b-versatile\\\": {\\\"tool_calling\\\": True, \\\"not_supported\\\": False},\\n        }\\n\\n        groq_model_instance.api_key = mock_api_key\\n        groq_model_instance.tool_model_enabled = False\\n\\n        build_config = {}\\n        result = groq_model_instance.update_build_config(build_config, mock_api_key, \\\"api_key\\\")\\n\\n        assert \\\"model_name\\\" in result\\n        assert \\\"options\\\" in result[\\\"model_name\\\"]\\n        assert \\\"llama-3.1-8b-instant\\\" in result[\\\"model_name\\\"][\\\"options\\\"]\\n        assert \\\"llama-3.3-70b-versatile\\\" in result[\\\"model_name\\\"][\\\"options\\\"]\\n        assert \\\"value\\\" in result[\\\"model_name\\\"]\\n\\n    @patch.object(groq_module, \\\"get_groq_models\\\")\\n    def test_update_build_config_with_tool_model_enabled(self, mock_get_groq_models, groq_model_instance, mock_api_key):\\n        \\\"\\\"\\\"Test update_build_config filters models when tool_model_enabled changes.\\\"\\\"\\\"\\n        mock_get_groq_models.return_value = {\\n            \\\"llama-3.1-8b-instant\\\": {\\\"tool_calling\\\": True, \\\"not_supported\\\": False},\\n            \\\"gemma-7b-it\\\": {\\\"tool_calling\\\": False, \\\"not_supported\\\": False},\\n        }\\n\\n        groq_model_instance.api_key = mock_api_key\\n        groq_model_instance.tool_model_enabled = True\\n\\n        build_config = {}\\n        result = groq_model_instance.update_build_config(build_config, \\\"true\\\", \\\"tool_model_enabled\\\")\\n\\n        # When tool_model_enabled is True, should only show tool models\\n        assert \\\"model_name\\\" in result\\n        models = result[\\\"model_name\\\"][\\\"options\\\"]\\n        # Note: The actual filtering happens in get_models(), so we need to check that too\\n        assert len(models) > 0\\n\\n    @patch.object(groq_module, \\\"get_groq_models\\\")\\n    def test_update_build_config_with_model_name(self, mock_get_groq_models, groq_model_instance, mock_api_key):\\n        \\\"\\\"\\\"Test update_build_config when model_name field is updated.\\\"\\\"\\\"\\n        mock_get_groq_models.return_value = {\\n            \\\"llama-3.1-8b-instant\\\": {\\\"tool_calling\\\": True, \\\"not_supported\\\": False},\\n            \\\"llama-3.3-70b-versatile\\\": {\\\"tool_calling\\\": True, \\\"not_supported\\\": False},\\n        }\\n\\n        groq_model_instance.api_key = mock_api_key\\n        groq_model_instance.tool_model_enabled = False\\n\\n        build_config = {}\\n        result = groq_model_instance.update_build_config(build_config, \\\"llama-3.1-8b-instant\\\", \\\"model_name\\\")\\n\\n        assert \\\"model_name\\\" in result\\n        assert \\\"options\\\" in result[\\\"model_name\\\"]\\n\\n    @patch.object(groq_module, \\\"get_groq_models\\\")\\n    def test_update_build_config_with_base_url(self, mock_get_groq_models, groq_model_instance, mock_api_key):\\n        \\\"\\\"\\\"Test update_build_config when base_url field is updated.\\\"\\\"\\\"\\n        mock_get_groq_models.return_value = {\\n            \\\"llama-3.1-8b-instant\\\": {\\\"tool_calling\\\": True, \\\"not_supported\\\": False},\\n        }\\n\\n        groq_model_instance.api_key = mock_api_key\\n        groq_model_instance.tool_model_enabled = False\\n\\n        build_config = {}\\n        result = groq_model_instance.update_build_config(build_config, \\\"https://custom.groq.com\\\", \\\"base_url\\\")\\n\\n        assert \\\"model_name\\\" in result\\n\\n    def test_update_build_config_with_empty_api_key(self, groq_model_instance):\\n        \\\"\\\"\\\"Test update_build_config with empty API key doesn't update.\\\"\\\"\\\"\\n        groq_model_instance.api_key = \\\"\\\"\\n\\n        build_config = {}\\n        result = groq_model_instance.update_build_config(build_config, \\\"\\\", \\\"api_key\\\")\\n\\n        # Should not update model_name when api_key is empty\\n        assert result == build_config\\n\\n    @patch.object(groq_module, \\\"get_groq_models\\\")\\n    def test_update_build_config_error_handling(self, mock_get_groq_models, groq_model_instance, mock_api_key):\\n        \\\"\\\"\\\"Test update_build_config handles errors gracefully.\\\"\\\"\\\"\\n        # Simulate error\\n        mock_get_groq_models.side_effect = ValueError(\\\"API error\\\")\\n\\n        groq_model_instance.api_key = mock_api_key\\n        groq_model_instance.tool_model_enabled = False\\n\\n        build_config = {}\\n        result = groq_model_instance.update_build_config(build_config, mock_api_key, \\\"api_key\\\")\\n\\n        # Should still return a build config with fallback models\\n        assert \\\"model_name\\\" in result\\n        assert \\\"options\\\" in result[\\\"model_name\\\"]\\n\\n    def test_build_model_success(self, groq_model_instance, mock_api_key):\\n        \\\"\\\"\\\"Test build_model creates ChatGroq instance.\\\"\\\"\\\"\\n        groq_model_instance.api_key = mock_api_key\\n        groq_model_instance.model_name = \\\"llama-3.1-8b-instant\\\"\\n        groq_model_instance.base_url = \\\"https://api.groq.com\\\"\\n        groq_model_instance.max_tokens = 1000\\n        groq_model_instance.temperature = 0.7\\n        groq_model_instance.n = 1\\n        groq_model_instance.stream = False\\n\\n        with patch(\\\"langchain_groq.ChatGroq\\\") as mock_chat_groq:\\n            groq_model_instance.build_model()\\n\\n            mock_chat_groq.assert_called_once()\\n            call_kwargs = mock_chat_groq.call_args[1]\\n\\n            assert call_kwargs[\\\"model\\\"] == \\\"llama-3.1-8b-instant\\\"\\n            assert call_kwargs[\\\"max_tokens\\\"] == 1000\\n            assert call_kwargs[\\\"temperature\\\"] == 0.7\\n            assert call_kwargs[\\\"base_url\\\"] == \\\"https://api.groq.com\\\"\\n            assert call_kwargs[\\\"n\\\"] == 1\\n            assert call_kwargs[\\\"streaming\\\"] is False\\n\\n    def test_build_model_without_langchain_groq(self, groq_model_instance, mock_api_key):\\n        \\\"\\\"\\\"Test build_model raises ImportError when langchain-groq is not installed.\\\"\\\"\\\"\\n        groq_model_instance.api_key = mock_api_key\\n        groq_model_instance.model_name = \\\"llama-3.1-8b-instant\\\"\\n\\n        # Mock the import itself to raise ImportError\\n        import sys\\n\\n        with (\\n            patch.dict(sys.modules, {\\\"langchain_groq\\\": None}),\\n            pytest.raises(ImportError, match=\\\"langchain-groq is not installed\\\"),\\n        ):\\n            groq_model_instance.build_model()\\n\\n\\nclass TestGroqModelEdgeCases:\\n    \\\"\\\"\\\"Test edge cases in Groq component.\\\"\\\"\\\"\\n\\n    @pytest.fixture\\n    def groq_model_instance(self):\\n        \\\"\\\"\\\"Create a GroqModel instance for testing.\\\"\\\"\\\"\\n        return groq_module.GroqModel()\\n\\n    @patch.object(groq_module, \\\"get_groq_models\\\")\\n    def test_get_models_with_all_models_filtered_out(self, mock_get_groq_models, groq_model_instance, mock_api_key):\\n        \\\"\\\"\\\"Test get_models when all models are filtered out by tool_model_enabled.\\\"\\\"\\\"\\n        mock_get_groq_models.return_value = {\\n            \\\"gemma-7b-it\\\": {\\\"tool_calling\\\": False, \\\"not_supported\\\": False},\\n            \\\"another-model\\\": {\\\"tool_calling\\\": False, \\\"not_supported\\\": False},\\n        }\\n\\n        groq_model_instance.api_key = mock_api_key\\n\\n        models = groq_model_instance.get_models(tool_model_enabled=True)\\n\\n        # Should return empty list when all models are filtered\\n        assert len(models) == 0\\n\\n    @patch.object(groq_module, \\\"get_groq_models\\\")\\n    def test_get_models_with_only_unsupported_models(self, mock_get_groq_models, groq_model_instance, mock_api_key):\\n        \\\"\\\"\\\"Test get_models when only unsupported models are returned.\\\"\\\"\\\"\\n        mock_get_groq_models.return_value = {\\n            \\\"whisper-large-v3\\\": {\\\"not_supported\\\": True},\\n            \\\"playai-tts\\\": {\\\"not_supported\\\": True},\\n        }\\n\\n        groq_model_instance.api_key = mock_api_key\\n\\n        models = groq_model_instance.get_models()\\n\\n        # Should filter out all not_supported models\\n        assert len(models) == 0\\n\\n    @patch.object(groq_module, \\\"get_groq_models\\\")\\n    def test_get_models_with_mixed_metadata(self, mock_get_groq_models, groq_model_instance, mock_api_key):\\n        \\\"\\\"\\\"Test get_models with mixed metadata (some fields missing).\\\"\\\"\\\"\\n        mock_get_groq_models.return_value = {\\n            \\\"llama-3.1-8b-instant\\\": {\\\"tool_calling\\\": True},  # Missing not_supported\\n            \\\"gemma-7b-it\\\": {\\\"not_supported\\\": False},  # Missing tool_calling\\n            \\\"mixtral-8x7b-32768\\\": {\\\"tool_calling\\\": True, \\\"not_supported\\\": False},  # Complete\\n        }\\n\\n        groq_model_instance.api_key = mock_api_key\\n\\n        models = groq_model_instance.get_models()\\n\\n        # Should handle missing fields gracefully\\n        assert \\\"llama-3.1-8b-instant\\\" in models\\n        assert \\\"gemma-7b-it\\\" in models\\n        assert \\\"mixtral-8x7b-32768\\\" in models\\n\\n    @patch.object(groq_module, \\\"get_groq_models\\\")\\n    def test_get_models_with_none_tool_model_enabled(self, mock_get_groq_models, groq_model_instance, mock_api_key):\\n        \\\"\\\"\\\"Test get_models with tool_model_enabled=None (default).\\\"\\\"\\\"\\n        mock_get_groq_models.return_value = {\\n            \\\"llama-3.1-8b-instant\\\": {\\\"tool_calling\\\": True, \\\"not_supported\\\": False},\\n            \\\"gemma-7b-it\\\": {\\\"tool_calling\\\": False, \\\"not_supported\\\": False},\\n        }\\n\\n        groq_model_instance.api_key = mock_api_key\\n\\n        models = groq_model_instance.get_models(tool_model_enabled=None)\\n\\n        # Should return all models (not filter by tool_calling)\\n        assert \\\"llama-3.1-8b-instant\\\" in models\\n        assert \\\"gemma-7b-it\\\" in models\\n\\n    def test_update_build_config_with_unrelated_field(self, groq_model_instance, mock_api_key):\\n        \\\"\\\"\\\"Test update_build_config with field that doesn't trigger updates.\\\"\\\"\\\"\\n        groq_model_instance.api_key = mock_api_key\\n\\n        build_config = {\\\"existing\\\": \\\"value\\\"}\\n        result = groq_model_instance.update_build_config(build_config, \\\"0.7\\\", \\\"temperature\\\")\\n\\n        # Should return unchanged build_config for unrelated fields\\n        assert result == build_config\\n\\n    @patch.object(groq_module, \\\"get_groq_models\\\")\\n    def test_get_models_key_error_falls_back(self, mock_get_groq_models, groq_model_instance, mock_api_key):\\n        \\\"\\\"\\\"Test get_models handles KeyError and falls back.\\\"\\\"\\\"\\n        mock_get_groq_models.side_effect = KeyError(\\\"Missing key\\\")\\n\\n        groq_model_instance.api_key = mock_api_key\\n\\n        models = groq_model_instance.get_models()\\n\\n        # Should fall back to GROQ_MODELS\\n        assert isinstance(models, list)\\n\\n    @patch.object(groq_module, \\\"get_groq_models\\\")\\n    def test_get_models_type_error_falls_back(self, mock_get_groq_models, groq_model_instance, mock_api_key):\\n        \\\"\\\"\\\"Test get_models handles TypeError and falls back.\\\"\\\"\\\"\\n        mock_get_groq_models.side_effect = TypeError(\\\"Type error\\\")\\n\\n        groq_model_instance.api_key = mock_api_key\\n\\n        models = groq_model_instance.get_models()\\n\\n        # Should fall back to GROQ_MODELS\\n        assert isinstance(models, list)\\n\\n    @patch.object(groq_module, \\\"get_groq_models\\\")\\n    def test_get_models_import_error_falls_back(self, mock_get_groq_models, groq_model_instance, mock_api_key):\\n        \\\"\\\"\\\"Test get_models handles ImportError and falls back.\\\"\\\"\\\"\\n        mock_get_groq_models.side_effect = ImportError(\\\"Import error\\\")\\n\\n        groq_model_instance.api_key = mock_api_key\\n\\n        models = groq_model_instance.get_models()\\n\\n        # Should fall back to GROQ_MODELS\\n        assert isinstance(models, list)\\n\\n    def test_build_model_with_none_max_tokens(self, groq_model_instance, mock_api_key):\\n        \\\"\\\"\\\"Test build_model with max_tokens=None.\\\"\\\"\\\"\\n        groq_model_instance.api_key = mock_api_key\\n        groq_model_instance.model_name = \\\"llama-3.1-8b-instant\\\"\\n        groq_model_instance.max_tokens = None\\n        groq_model_instance.temperature = 0.7\\n        groq_model_instance.base_url = \\\"https://api.groq.com\\\"\\n        groq_model_instance.n = None\\n        groq_model_instance.stream = False\\n\\n        with patch(\\\"langchain_groq.ChatGroq\\\") as mock_chat_groq:\\n            groq_model_instance.build_model()\\n\\n            call_kwargs = mock_chat_groq.call_args[1]\\n            assert call_kwargs[\\\"max_tokens\\\"] is None\\n            assert call_kwargs[\\\"n\\\"] == 1  # Should default to 1\\n\\n\\nclass TestGroqModelBackwardCompatibility:\\n    \\\"\\\"\\\"Test backward compatibility with static GROQ_MODELS.\\\"\\\"\\\"\\n\\n    @pytest.fixture\\n    def groq_model_instance(self):\\n        \\\"\\\"\\\"Create a GroqModel instance for testing.\\\"\\\"\\\"\\n        return groq_module.GroqModel()\\n\\n    def test_groq_models_constant_available(self):\\n        \\\"\\\"\\\"Test that GROQ_MODELS constant is still available for backward compatibility.\\\"\\\"\\\"\\n        from lfx.base.models.groq_constants import GROQ_MODELS\\n\\n        assert isinstance(GROQ_MODELS, list)\\n        assert len(GROQ_MODELS) > 0\\n\\n    def test_fallback_to_groq_models_on_error(self, groq_model_instance, mock_api_key):\\n        \\\"\\\"\\\"Test that component falls back to GROQ_MODELS constant on error.\\\"\\\"\\\"\\n        from lfx.base.models.groq_constants import GROQ_MODELS\\n\\n        groq_model_instance.api_key = mock_api_key\\n\\n        # ValueError is one of the exceptions that's caught and triggers fallback\\n        with patch(\\\"lfx.components.groq.groq.get_groq_models\\\", side_effect=ValueError(\\\"API error\\\")):\\n            models = groq_model_instance.get_models()\\n\\n            # Should return GROQ_MODELS\\n            assert models == GROQ_MODELS\\n\\n    def test_model_name_input_has_default_options(self, groq_model_instance):\\n        \\\"\\\"\\\"Test that model_name input has default options from GROQ_MODELS.\\\"\\\"\\\"\\n        from lfx.base.models.groq_constants import GROQ_MODELS\\n\\n        model_name_input = next(inp for inp in groq_model_instance.inputs if inp.name == \\\"model_name\\\")\\n\\n        assert model_name_input.options == GROQ_MODELS\\n        assert model_name_input.value == GROQ_MODELS[0]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/helpers/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"adfe5cdbc27080f5815e0662aa17a46d7b68219a2c05543335611bc90c956991\",\"content\":\"\\\"\\\"\\\"Unit tests for langflow.helpers.\\\"\\\"\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/helpers/test_base_model_from_schema.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"7c7b85e8060bcf6e0c60ce5e31c107583f3a5e7cd2c3cc822eaa4d37bf30392f\",\"content\":\"# Generated by qodo Gen\\n\\nfrom typing import Any\\n\\nimport pytest\\nfrom langflow.helpers.base_model import build_model_from_schema\\nfrom pydantic import BaseModel\\nfrom pydantic_core import PydanticUndefined\\n\\n\\nclass TestBuildModelFromSchema:\\n    # Successfully creates a Pydantic model from a valid schema\\n    def test_create_model_from_valid_schema(self):\\n        schema = [\\n            {\\\"name\\\": \\\"field1\\\", \\\"type\\\": \\\"str\\\", \\\"default\\\": \\\"default_value\\\", \\\"description\\\": \\\"A string field\\\"},\\n            {\\\"name\\\": \\\"field2\\\", \\\"type\\\": \\\"int\\\", \\\"default\\\": 0, \\\"description\\\": \\\"An integer field\\\"},\\n            {\\\"name\\\": \\\"field3\\\", \\\"type\\\": \\\"bool\\\", \\\"default\\\": False, \\\"description\\\": \\\"A boolean field\\\"},\\n        ]\\n        model = build_model_from_schema(schema)\\n        instance = model(field1=\\\"test\\\", field2=123, field3=True)\\n        assert instance.field1 == \\\"test\\\"\\n        assert instance.field2 == 123\\n        assert instance.field3 is True\\n\\n    # Handles empty schema gracefully without errors\\n    def test_handle_empty_schema(self):\\n        schema = []\\n        model = build_model_from_schema(schema)\\n        instance = model()\\n        assert instance is not None\\n\\n    # Ensure the model created from schema has the expected attributes by checking on an instance\\n    def test_handles_multiple_fields_fixed_with_instance_check(self):\\n        schema = [\\n            {\\\"name\\\": \\\"field1\\\", \\\"type\\\": \\\"str\\\", \\\"default\\\": \\\"default_value1\\\"},\\n            {\\\"name\\\": \\\"field2\\\", \\\"type\\\": \\\"int\\\", \\\"default\\\": 42},\\n            {\\\"name\\\": \\\"field3\\\", \\\"type\\\": \\\"list\\\", \\\"default\\\": [1, 2, 3]},\\n            {\\\"name\\\": \\\"field4\\\", \\\"type\\\": \\\"dict\\\", \\\"default\\\": {\\\"key\\\": \\\"value\\\"}},\\n        ]\\n\\n        model = build_model_from_schema(schema)\\n        model_instance = model(field1=\\\"test\\\", field2=123, field3=[1, 2, 3], field4={\\\"key\\\": \\\"value\\\"})\\n\\n        assert issubclass(model, BaseModel)\\n        assert hasattr(model_instance, \\\"field1\\\")\\n        assert hasattr(model_instance, \\\"field2\\\")\\n        assert hasattr(model_instance, \\\"field3\\\")\\n        assert hasattr(model_instance, \\\"field4\\\")\\n\\n    # Correctly accesses descriptions using the recommended fix\\n    def test_correctly_accesses_descriptions_recommended_fix(self):\\n        schema = [\\n            {\\\"name\\\": \\\"field1\\\", \\\"type\\\": \\\"str\\\", \\\"default\\\": \\\"default_value1\\\", \\\"description\\\": \\\"Description for field1\\\"},\\n            {\\\"name\\\": \\\"field2\\\", \\\"type\\\": \\\"int\\\", \\\"default\\\": 42, \\\"description\\\": \\\"Description for field2\\\"},\\n            {\\\"name\\\": \\\"field3\\\", \\\"type\\\": \\\"list\\\", \\\"default\\\": [1, 2, 3], \\\"description\\\": \\\"Description for field3\\\"},\\n            {\\\"name\\\": \\\"field4\\\", \\\"type\\\": \\\"dict\\\", \\\"default\\\": {\\\"key\\\": \\\"value\\\"}, \\\"description\\\": \\\"Description for field4\\\"},\\n        ]\\n\\n        model = build_model_from_schema(schema)\\n\\n        assert model.model_fields[\\\"field1\\\"].description == \\\"Description for field1\\\"\\n        assert model.model_fields[\\\"field2\\\"].description == \\\"Description for field2\\\"\\n        assert model.model_fields[\\\"field3\\\"].description == \\\"Description for field3\\\"\\n        assert model.model_fields[\\\"field4\\\"].description == \\\"Description for field4\\\"\\n\\n    # Supports both single and multiple type annotations\\n    def test_supports_single_and_multiple_type_annotations(self):\\n        schema = [\\n            {\\\"name\\\": \\\"field1\\\", \\\"type\\\": \\\"str\\\", \\\"default\\\": \\\"default_value1\\\", \\\"description\\\": \\\"Description 1\\\"},\\n            {\\\"name\\\": \\\"field2\\\", \\\"type\\\": \\\"list\\\", \\\"default\\\": [1, 2, 3], \\\"description\\\": \\\"Description 2\\\", \\\"multiple\\\": True},\\n            {\\\"name\\\": \\\"field3\\\", \\\"type\\\": \\\"int\\\", \\\"default\\\": 100, \\\"description\\\": \\\"Description 3\\\"},\\n        ]\\n        model_type = build_model_from_schema(schema)\\n        assert issubclass(model_type, BaseModel)\\n\\n    # Manages unknown field types by defaulting to Any\\n    def test_manages_unknown_field_types(self):\\n        schema = [\\n            {\\\"name\\\": \\\"field1\\\", \\\"type\\\": \\\"str\\\", \\\"default\\\": \\\"default_value1\\\"},\\n            {\\\"name\\\": \\\"field2\\\", \\\"type\\\": \\\"unknown_type\\\", \\\"default\\\": \\\"default_value2\\\"},\\n        ]\\n        with pytest.raises(ValueError, match=\\\"Invalid type: unknown_type\\\"):\\n            build_model_from_schema(schema)\\n\\n    # Confirms that the function raises a specific exception for invalid input\\n    def test_raises_error_for_invalid_input_different_exception_with_specific_exception(self):\\n        schema = [{\\\"name\\\": \\\"field1\\\", \\\"type\\\": \\\"invalid_type\\\", \\\"default\\\": \\\"default_value\\\"}]\\n        with pytest.raises(ValueError, match=\\\"Invalid type: invalid_type\\\"):\\n            build_model_from_schema(schema)\\n\\n    # Processes schemas with missing optional keys like description or multiple\\n    def test_process_schema_missing_optional_keys_updated(self):\\n        schema = [\\n            {\\\"name\\\": \\\"field1\\\", \\\"type\\\": \\\"str\\\", \\\"default\\\": \\\"default_value1\\\"},\\n            {\\\"name\\\": \\\"field2\\\", \\\"type\\\": \\\"int\\\", \\\"default\\\": 0, \\\"description\\\": \\\"Field 2 description\\\"},\\n            {\\\"name\\\": \\\"field3\\\", \\\"type\\\": \\\"list\\\", \\\"default\\\": [], \\\"multiple\\\": True},\\n            {\\\"name\\\": \\\"field4\\\", \\\"type\\\": \\\"dict\\\", \\\"default\\\": {}, \\\"description\\\": \\\"Field 4 description\\\", \\\"multiple\\\": True},\\n        ]\\n        result_model = build_model_from_schema(schema)\\n        assert result_model.__annotations__[\\\"field1\\\"] == str  # noqa: E721\\n        assert result_model.model_fields[\\\"field1\\\"].description == \\\"\\\"\\n        assert result_model.__annotations__[\\\"field2\\\"] == int  # noqa: E721\\n        assert result_model.model_fields[\\\"field2\\\"].description == \\\"Field 2 description\\\"\\n        assert result_model.__annotations__[\\\"field3\\\"] == list[list[Any]]\\n        assert result_model.model_fields[\\\"field3\\\"].description == \\\"\\\"\\n        assert result_model.__annotations__[\\\"field4\\\"] == list[dict[str, Any]]\\n        assert result_model.model_fields[\\\"field4\\\"].description == \\\"Field 4 description\\\"\\n\\n    # Deals with schemas containing fields with None as default values\\n    def test_schema_fields_with_none_default(self):\\n        schema = [\\n            {\\\"name\\\": \\\"field1\\\", \\\"type\\\": \\\"str\\\", \\\"default\\\": None, \\\"description\\\": \\\"Field 1 description\\\"},\\n            {\\\"name\\\": \\\"field2\\\", \\\"type\\\": \\\"int\\\", \\\"default\\\": None, \\\"description\\\": \\\"Field 2 description\\\"},\\n            {\\\"name\\\": \\\"field3\\\", \\\"type\\\": \\\"list\\\", \\\"default\\\": None, \\\"description\\\": \\\"Field 3 description\\\", \\\"multiple\\\": True},\\n        ]\\n        model = build_model_from_schema(schema)\\n        assert model.model_fields[\\\"field1\\\"].default == PydanticUndefined\\n        assert model.model_fields[\\\"field2\\\"].default == PydanticUndefined\\n        assert model.model_fields[\\\"field3\\\"].default == PydanticUndefined\\n\\n    # Checks for proper handling of nested list and dict types\\n    def test_nested_list_and_dict_types_handling(self):\\n        schema = [\\n            {\\\"name\\\": \\\"field1\\\", \\\"type\\\": \\\"list\\\", \\\"default\\\": [], \\\"description\\\": \\\"list field\\\", \\\"multiple\\\": True},\\n            {\\\"name\\\": \\\"field2\\\", \\\"type\\\": \\\"dict\\\", \\\"default\\\": {}, \\\"description\\\": \\\"Dict field\\\"},\\n        ]\\n        model_type = build_model_from_schema(schema)\\n        assert issubclass(model_type, BaseModel)\\n\\n    # Verifies that the function can handle large schemas efficiently\\n    def test_handle_large_schemas_efficiently(self):\\n        schema = [\\n            {\\\"name\\\": \\\"field1\\\", \\\"type\\\": \\\"str\\\", \\\"default\\\": \\\"default_value1\\\", \\\"description\\\": \\\"Description 1\\\"},\\n            {\\\"name\\\": \\\"field2\\\", \\\"type\\\": \\\"int\\\", \\\"default\\\": 100, \\\"description\\\": \\\"Description 2\\\"},\\n            {\\\"name\\\": \\\"field3\\\", \\\"type\\\": \\\"list\\\", \\\"default\\\": [1, 2, 3], \\\"description\\\": \\\"Description 3\\\", \\\"multiple\\\": True},\\n            {\\\"name\\\": \\\"field4\\\", \\\"type\\\": \\\"dict\\\", \\\"default\\\": {\\\"key\\\": \\\"value\\\"}, \\\"description\\\": \\\"Description 4\\\"},\\n        ]\\n        model_type = build_model_from_schema(schema)\\n        assert issubclass(model_type, BaseModel)\\n\\n    # Ensures that the function returns a valid Pydantic model class\\n    def test_returns_valid_model_class(self):\\n        schema = [\\n            {\\\"name\\\": \\\"field1\\\", \\\"type\\\": \\\"str\\\", \\\"default\\\": \\\"default_value1\\\", \\\"description\\\": \\\"Description for field1\\\"},\\n            {\\\"name\\\": \\\"field2\\\", \\\"type\\\": \\\"int\\\", \\\"default\\\": 42, \\\"description\\\": \\\"Description for field2\\\", \\\"multiple\\\": True},\\n        ]\\n        model_class = build_model_from_schema(schema)\\n        assert issubclass(model_class, BaseModel)\\n\\n    # Validates that the last occurrence of a duplicate field name defines the type in the schema\\n    def test_no_duplicate_field_names_fixed_fixed(self):\\n        schema = [\\n            {\\\"name\\\": \\\"field1\\\", \\\"type\\\": \\\"str\\\", \\\"default\\\": \\\"default_value1\\\"},\\n            {\\\"name\\\": \\\"field2\\\", \\\"type\\\": \\\"int\\\", \\\"default\\\": 0},\\n            {\\\"name\\\": \\\"field1\\\", \\\"type\\\": \\\"float\\\", \\\"default\\\": 0.0},  # Duplicate field name\\n        ]\\n        model = build_model_from_schema(schema)\\n        assert model.__annotations__[\\\"field1\\\"] == float  # noqa: E721\\n        assert model.__annotations__[\\\"field2\\\"] == int  # noqa: E721\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/helpers/test_data.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a21eaf621e9d29e90993ca1d382f64fe4c49763a0e966047155f51ad102ca22d\",\"content\":\"import pytest\\nfrom langflow.helpers.data import data_to_text_list\\nfrom lfx.schema import Data\\n\\n\\n@pytest.mark.parametrize(\\n    (\\n        \\\"template\\\",\\n        \\\"data\\\",\\n        \\\"expected\\\",\\n    ),\\n    [\\n        (\\n            \\\"{name} is {age} years old\\\",\\n            Data(data={\\\"name\\\": \\\"Alice\\\", \\\"age\\\": 25}),\\n            ([\\\"Alice is 25 years old\\\"], [Data(data={\\\"name\\\": \\\"Alice\\\", \\\"age\\\": 25})]),\\n        ),\\n        (\\n            \\\"{name} is {age} years old\\\",\\n            [\\n                Data(data={\\\"name\\\": \\\"Alice\\\", \\\"age\\\": 25}),\\n                Data(data={\\\"name\\\": \\\"Bob\\\", \\\"age\\\": 30}),\\n                Data(data={\\\"name\\\": \\\"Alex\\\", \\\"age\\\": 35}),\\n            ],\\n            (\\n                [\\n                    \\\"Alice is 25 years old\\\",\\n                    \\\"Bob is 30 years old\\\",\\n                    \\\"Alex is 35 years old\\\",\\n                ],\\n                [\\n                    Data(data={\\\"name\\\": \\\"Alice\\\", \\\"age\\\": 25}),\\n                    Data(data={\\\"name\\\": \\\"Bob\\\", \\\"age\\\": 30}),\\n                    Data(data={\\\"name\\\": \\\"Alex\\\", \\\"age\\\": 35}),\\n                ],\\n            ),\\n        ),\\n    ],\\n)\\ndef test_data_to_text_list(template, data, expected):\\n    result = data_to_text_list(template, data)\\n    assert result == expected\\n\\n\\ndef test_data_to_text_list__template_empty():\\n    template = \\\"\\\"\\n    data = Data(data={\\\"key\\\": \\\"value\\\"})\\n\\n    result = data_to_text_list(template, data)\\n\\n    assert isinstance(result, tuple)\\n    assert len(result) == 2\\n    assert isinstance(result[0], list)\\n    assert isinstance(result[1], list)\\n    assert template in result[0]\\n    assert data in result[1]\\n\\n\\ndef test_data_to_text_list__template_without_placeholder():\\n    template = \\\"My favorite color is gray\\\"\\n    data = Data(data={\\\"color\\\": \\\"silver\\\"})\\n\\n    result = data_to_text_list(template, data)\\n\\n    assert isinstance(result, tuple)\\n    assert len(result) == 2\\n    assert isinstance(result[0], list)\\n    assert isinstance(result[1], list)\\n    assert template in result[0]\\n    assert data in result[1]\\n\\n\\ndef test_data_to_text_list__template_without_placeholder_and_data_attribute_empty():\\n    template = \\\"My favorite color is gray\\\"\\n    data_list = [Data(data={})]\\n\\n    result = data_to_text_list(template, data_list)\\n\\n    assert isinstance(result, tuple)\\n    assert len(result) == 2\\n    assert isinstance(result[0], list)\\n    assert isinstance(result[1], list)\\n    assert template in result[0]\\n    assert data_list == result[1]\\n\\n\\ndef test_data_to_text_list__template_wrong_placeholder():\\n    template = \\\"My favorite color is {color}\\\"\\n    data = Data(data={\\\"fruit\\\": \\\"apple\\\"})\\n\\n    # Should not raise KeyError due to defaultdict behavior\\n    result = data_to_text_list(template, data)\\n    assert result == ([\\\"My favorite color is \\\"], [data])\\n\\n\\ndef test_data_to_text_list__data_with_data_attribute_empty():\\n    template = \\\"My favorite color is {color}\\\"\\n    data = Data(data={})\\n\\n    # Should not raise KeyError due to defaultdict behavior\\n    result = data_to_text_list(template, data)\\n    assert result == ([\\\"My favorite color is \\\"], [data])\\n\\n\\ndef test_data_to_text_list__data_contains_nested_data_key():\\n    template = \\\"My data is: {data}\\\"\\n    data = Data(data={\\\"data\\\": {\\\"key\\\": \\\"value\\\"}})\\n\\n    result = data_to_text_list(template, data)\\n\\n    assert isinstance(result, tuple)\\n    assert len(result) == 2\\n    assert isinstance(result[0], list)\\n    assert isinstance(result[1], list)\\n    assert template not in result[0]\\n    assert data in result[1]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/helpers/test_data_to_text_list.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"ee20ce0ae63787b2d8fe5799dd370a7dbbf8cbb7ebcf7e2120fe86d033e480f8\",\"content\":\"import pytest\\nfrom langflow.helpers.data import data_to_text_list\\nfrom lfx.schema import Data\\n\\n\\n@pytest.mark.parametrize(\\n    (\\\"template\\\", \\\"data\\\", \\\"expected_text\\\"),\\n    [\\n        # Test basic string data\\n        (\\n            \\\"Text: {text}\\\",\\n            Data(text=\\\"Hello\\\"),\\n            [\\\"Text: Hello\\\"],\\n        ),\\n        # Test dictionary data\\n        (\\n            \\\"{name} is {age} years old\\\",\\n            Data(data={\\\"name\\\": \\\"Alice\\\", \\\"age\\\": 25}),\\n            [\\\"Alice is 25 years old\\\"],\\n        ),\\n        # Test list of Data objects\\n        (\\n            \\\"{name} is {age} years old\\\",\\n            [\\n                Data(data={\\\"name\\\": \\\"Alice\\\", \\\"age\\\": 25}),\\n                Data(data={\\\"name\\\": \\\"Bob\\\", \\\"age\\\": 30}),\\n            ],\\n            [\\\"Alice is 25 years old\\\", \\\"Bob is 30 years old\\\"],\\n        ),\\n        # Test nested data dictionary\\n        (\\n            \\\"User: {text}\\\",\\n            Data(data={\\\"data\\\": {\\\"text\\\": \\\"Hello World\\\"}}),\\n            [\\\"User: Hello World\\\"],\\n        ),\\n        # Test error message in data\\n        (\\n            \\\"Error: {text}\\\",\\n            Data(data={\\\"error\\\": \\\"Something went wrong\\\"}),\\n            [\\\"Error: Something went wrong\\\"],\\n        ),\\n        # Test non-Data object conversion\\n        (\\n            \\\"Value: {text}\\\",\\n            Data(text=\\\"Simple string\\\"),\\n            [\\\"Value: Simple string\\\"],\\n        ),\\n    ],\\n)\\ndef test_data_to_text_list_parametrized(template, data, expected_text):\\n    \\\"\\\"\\\"Test various input combinations for data_to_text_list.\\\"\\\"\\\"\\n    result = data_to_text_list(template, data)\\n    assert result[0] == expected_text\\n    assert all(isinstance(d, Data) for d in result[1])\\n\\n\\ndef test_data_to_text_list_none_data():\\n    \\\"\\\"\\\"Test handling of None data input.\\\"\\\"\\\"\\n    result = data_to_text_list(\\\"template\\\", None)\\n    assert result == ([], [])\\n\\n\\ndef test_data_to_text_list_none_template():\\n    \\\"\\\"\\\"Test handling of None template input.\\\"\\\"\\\"\\n    with pytest.raises(ValueError, match=\\\"Template must be a string, but got None\\\"):\\n        data_to_text_list(None, Data(text=\\\"test\\\"))\\n\\n\\ndef test_data_to_text_list_invalid_template_type():\\n    \\\"\\\"\\\"Test handling of invalid template type.\\\"\\\"\\\"\\n    with pytest.raises(TypeError, match=\\\"Template must be a string, but got\\\"):\\n        data_to_text_list(123, Data(text=\\\"test\\\"))\\n\\n\\ndef test_data_to_text_list_missing_key():\\n    \\\"\\\"\\\"Test handling of missing template key.\\\"\\\"\\\"\\n    template = \\\"Hello {missing_key}\\\"\\n    data = Data(data={\\\"existing_key\\\": \\\"value\\\"})\\n    # Should not raise KeyError due to defaultdict\\n    result = data_to_text_list(template, data)\\n    assert result == ([\\\"Hello \\\"], [data])\\n\\n\\ndef test_data_to_text_list_empty_data_dict():\\n    \\\"\\\"\\\"Test handling of empty data dictionary.\\\"\\\"\\\"\\n    template = \\\"Hello {text}\\\"\\n    data = Data(data={})\\n    result = data_to_text_list(template, data)\\n    assert result == ([\\\"Hello \\\"], [data])\\n\\n\\ndef test_data_to_text_list_mixed_data_types():\\n    \\\"\\\"\\\"Test handling of mixed data types in list.\\\"\\\"\\\"\\n    template = \\\"Item: {text}\\\"\\n    data = [\\n        Data(text=\\\"First\\\"),\\n        \\\"Second\\\",\\n        Data(data={\\\"text\\\": \\\"Third\\\"}),\\n        123,\\n    ]\\n    result = data_to_text_list(template, data)\\n    expected_texts = [\\n        \\\"Item: First\\\",\\n        \\\"Item: Second\\\",\\n        \\\"Item: Third\\\",\\n        \\\"Item: 123\\\",\\n    ]\\n    assert result[0] == expected_texts\\n    assert len(result[1]) == 4\\n    assert all(isinstance(d, Data) for d in result[1])\\n\\n\\ndef test_data_to_text_list_complex_nested_data():\\n    \\\"\\\"\\\"Test handling of complex nested data structures.\\\"\\\"\\\"\\n    template = \\\"Name: {name}, Info: {text}, Status: {status}\\\"\\n    data = Data(data={\\\"name\\\": \\\"Test\\\", \\\"data\\\": {\\\"text\\\": \\\"Nested text\\\", \\\"status\\\": \\\"active\\\"}})\\n    result = data_to_text_list(template, data)\\n    expected = ([\\\"Name: Test, Info: Nested text, Status: active\\\"], [data])\\n    assert result == expected\\n\\n\\ndef test_data_to_text_list_empty_template():\\n    \\\"\\\"\\\"Test handling of empty template string.\\\"\\\"\\\"\\n    data = Data(data={\\\"key\\\": \\\"value\\\"})\\n    result = data_to_text_list(\\\"\\\", data)\\n    assert result == ([\\\"\\\"], [data])\\n\\n\\ndef test_data_to_text_list_string_data():\\n    \\\"\\\"\\\"Test handling of string data in Data object.\\\"\\\"\\\"\\n    template = \\\"Message: {text}\\\"\\n    data = Data(data={\\\"text\\\": \\\"Direct string\\\"})\\n    result = data_to_text_list(template, data)\\n    assert result == ([\\\"Message: Direct string\\\"], [data])\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/helpers/test_nested_provider_policy_scope.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"084c94d2ceec32a739ad36da9e78d7cabdc7866def9ff68dba8743bbb72d2e86\",\"content\":\"\\\"\\\"\\\"Nested saved-flow execution must use the target flow's provider-policy scope.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\nfrom contextlib import contextmanager\\nfrom types import SimpleNamespace\\nfrom unittest.mock import AsyncMock, MagicMock\\nfrom uuid import UUID, uuid4\\n\\nimport pytest\\nfrom langchain_core.tools import ToolException\\nfrom langflow.helpers.flow import generate_function_for_flow, load_flow, run_flow\\nfrom langflow.services.database.models import Folder\\nfrom langflow.services.database.models.flow.model import Flow\\nfrom langflow.services.deps import session_scope\\nfrom lfx.base.tools.flow_tool import FlowTool\\nfrom lfx.base.tools.run_flow import RunFlowBaseComponent\\nfrom lfx.components.models_and_agents.a2a_agent import A2AAgentComponent\\nfrom lfx.custom.custom_component.custom_component import CustomComponent\\nfrom lfx.schema.data import Data\\nfrom lfx.services.model_provider_policy import (\\n    BaseModelProviderPolicyService,\\n    ModelProviderPolicyError,\\n    ModelProviderPolicyPurpose,\\n    current_model_provider_policy_context,\\n    require_model_provider,\\n    reset_current_model_provider_policy_context,\\n    set_current_model_provider_policy_context,\\n)\\n\\n\\nclass _ProjectPolicy(BaseModelProviderPolicyService):\\n    \\\"\\\"\\\"Allow providers only in the mutable set of project ids.\\\"\\\"\\\"\\n\\n    SNAPSHOT_CACHE_MAX_SIZE = 0\\n\\n    def __init__(self) -> None:\\n        super().__init__()\\n        self.allowed_projects: set[str] = set()\\n        self.seen_projects: list[str | None] = []\\n        self.set_ready()\\n\\n    def get_allowed_provider_ids(self, *, context, candidate_provider_ids, purpose):\\n        assert purpose is ModelProviderPolicyPurpose.USE\\n        project_id = context.attributes.get(\\\"project_id\\\")\\n        normalized = str(project_id) if project_id is not None else None\\n        self.seen_projects.append(normalized)\\n        return candidate_provider_ids if normalized in self.allowed_projects else ()\\n\\n\\nclass _ProviderGraph:\\n    \\\"\\\"\\\"Small graph double whose provider use precedes its network-capable action.\\\"\\\"\\\"\\n\\n    def __init__(self, *, flow_id: str | None, probe: MagicMock, callback=None) -> None:\\n        self.flow_id = flow_id\\n        self.flow_name = None\\n        self.user_id: str | None = None\\n        self.run_id = None\\n        self.session_id = None\\n        self.vertices = []\\n        self.successor_map = {}\\n        self.description = None\\n        self.updated_at = None\\n        self._probe = probe\\n        self._callback = callback\\n\\n    def set_run_id(self, run_id) -> None:\\n        self.run_id = run_id\\n\\n    async def arun(self, *_args, **_kwargs):\\n        if self._callback is not None:\\n            return await self._callback()\\n        require_model_provider(user_id=self.user_id, provider=\\\"OpenAI\\\")\\n        self._probe()\\n        return []\\n\\n\\n@pytest.fixture\\ndef project_policy(monkeypatch) -> _ProjectPolicy:\\n    policy = _ProjectPolicy()\\n    monkeypatch.setattr(\\\"lfx.services.deps.get_model_provider_policy_service\\\", lambda: policy)\\n    return policy\\n\\n\\n@pytest.fixture\\nasync def nested_flow_rows(active_user):\\n    workspaces = [uuid4(), uuid4(), uuid4()]\\n    async with session_scope() as session:\\n        projects = [\\n            Folder(name=f\\\"nested-scope-{index}-{uuid4()}\\\", user_id=active_user.id, workspace_id=workspace_id)\\n            for index, workspace_id in enumerate(workspaces)\\n        ]\\n        session.add_all(projects)\\n        await session.flush()\\n        targets = [\\n            Flow(\\n                name=f\\\"nested-target-{index}-{uuid4()}\\\",\\n                data={\\\"nodes\\\": [], \\\"edges\\\": []},\\n                user_id=active_user.id,\\n                folder_id=project.id,\\n                workspace_id=project.workspace_id,\\n            )\\n            for index, project in enumerate(projects[1:], start=1)\\n        ]\\n        session.add_all(targets)\\n        await session.flush()\\n        rows = SimpleNamespace(\\n            user_id=str(active_user.id),\\n            outer_project=projects[0].id,\\n            outer_workspace=projects[0].workspace_id,\\n            target_project=projects[1].id,\\n            target_workspace=projects[1].workspace_id,\\n            target_flow=targets[0].id,\\n            target_name=targets[0].name,\\n            moved_project=projects[2].id,\\n            moved_workspace=projects[2].workspace_id,\\n            recursive_flow=targets[1].id,\\n        )\\n    yield rows\\n\\n    async with session_scope() as session:\\n        for flow_id in (rows.target_flow, rows.recursive_flow):\\n            if flow := await session.get(Flow, flow_id):\\n                await session.delete(flow)\\n        for project_id in (rows.outer_project, rows.target_project, rows.moved_project):\\n            if project := await session.get(Folder, project_id):\\n                await session.delete(project)\\n\\n\\n@contextmanager\\ndef _outer_scope(rows):\\n    token = set_current_model_provider_policy_context(\\n        user_id=rows.user_id,\\n        attributes={\\n            \\\"project_id\\\": rows.outer_project,\\n            \\\"workspace_id\\\": rows.outer_workspace,\\n            \\\"provider_scope_required\\\": True,\\n        },\\n    )\\n    try:\\n        yield\\n    finally:\\n        reset_current_model_provider_policy_context(token)\\n\\n\\ndef _install_build_probe(monkeypatch, probe: MagicMock):\\n    from lfx.graph.graph.base import Graph\\n\\n    def _from_payload(_payload=None, *, payload=None, flow_id=None, user_id=None, **_kwargs):\\n        _ = payload\\n        require_model_provider(user_id=user_id, provider=\\\"OpenAI\\\")\\n        probe()\\n        return _ProviderGraph(flow_id=str(flow_id) if flow_id is not None else None, probe=probe)\\n\\n    monkeypatch.setattr(Graph, \\\"from_payload\\\", staticmethod(_from_payload))\\n\\n\\n@pytest.mark.parametrize(\\\"entry\\\", [\\\"loader\\\", \\\"custom\\\", \\\"generated\\\"])\\n@pytest.mark.asyncio\\nasync def test_cold_nested_entry_denies_target_before_provider_io(entry, nested_flow_rows, project_policy, monkeypatch):\\n    \\\"\\\"\\\"An outer grant must not authorize a denied target build or execution.\\\"\\\"\\\"\\n    probe = MagicMock()\\n    _install_build_probe(monkeypatch, probe)\\n    project_policy.allowed_projects = {str(nested_flow_rows.outer_project)}\\n\\n    async def _invoke():\\n        if entry == \\\"loader\\\":\\n            return await load_flow(nested_flow_rows.user_id, flow_id=str(nested_flow_rows.target_flow))\\n        if entry == \\\"custom\\\":\\n            component = SimpleNamespace(\\n                user_id=UUID(nested_flow_rows.user_id),\\n                graph=SimpleNamespace(run_id=None),\\n            )\\n            return await CustomComponent.run_flow(\\n                component,\\n                flow_id=str(nested_flow_rows.target_flow),\\n                output_type=\\\"any\\\",\\n            )\\n        function = generate_function_for_flow([], str(nested_flow_rows.target_flow), nested_flow_rows.user_id)\\n        return await function()\\n\\n    expected_error = ToolException if entry == \\\"generated\\\" else ModelProviderPolicyError\\n    with _outer_scope(nested_flow_rows), pytest.raises(expected_error):\\n        await _invoke()\\n\\n    probe.assert_not_called()\\n\\n\\n@pytest.mark.parametrize(\\\"entry\\\", [\\\"loader\\\", \\\"custom\\\", \\\"generated\\\"])\\n@pytest.mark.asyncio\\nasync def test_cold_nested_entry_uses_target_grant_when_outer_is_denied(\\n    entry, nested_flow_rows, project_policy, monkeypatch\\n):\\n    \\\"\\\"\\\"A target grant must work even when the ambient outer project is denied.\\\"\\\"\\\"\\n    probe = MagicMock()\\n    _install_build_probe(monkeypatch, probe)\\n    project_policy.allowed_projects = {str(nested_flow_rows.target_project)}\\n\\n    with _outer_scope(nested_flow_rows):\\n        if entry == \\\"loader\\\":\\n            await load_flow(nested_flow_rows.user_id, flow_id=str(nested_flow_rows.target_flow))\\n        elif entry == \\\"custom\\\":\\n            component = SimpleNamespace(\\n                user_id=UUID(nested_flow_rows.user_id),\\n                graph=SimpleNamespace(run_id=None),\\n            )\\n            await CustomComponent.run_flow(\\n                component,\\n                flow_id=str(nested_flow_rows.target_flow),\\n                output_type=\\\"any\\\",\\n            )\\n        else:\\n            function = generate_function_for_flow([], str(nested_flow_rows.target_flow), nested_flow_rows.user_id)\\n            await function()\\n\\n    assert probe.call_count >= 1\\n    assert project_policy.seen_projects\\n    assert set(project_policy.seen_projects) == {str(nested_flow_rows.target_project)}\\n\\n\\n@pytest.mark.parametrize(\\\"entry\\\", [\\\"helper\\\", \\\"flow_tool\\\"])\\n@pytest.mark.asyncio\\nasync def test_prebuilt_and_flow_tool_reauthorize_in_target_scope(entry, nested_flow_rows, project_policy):\\n    \\\"\\\"\\\"A prebuilt/frozen-style graph cannot retain the outer project's grant.\\\"\\\"\\\"\\n    probe = MagicMock()\\n    graph = _ProviderGraph(flow_id=str(nested_flow_rows.target_flow), probe=probe)\\n    project_policy.allowed_projects = {str(nested_flow_rows.outer_project)}\\n\\n    async def _invoke():\\n        if entry == \\\"helper\\\":\\n            return await run_flow(\\n                graph=graph,\\n                flow_id=str(nested_flow_rows.target_flow),\\n                user_id=nested_flow_rows.user_id,\\n                output_type=\\\"any\\\",\\n            )\\n        tool = FlowTool.model_construct(\\n            name=\\\"nested_target\\\",\\n            description=\\\"nested target\\\",\\n            graph=graph,\\n            flow_id=str(nested_flow_rows.target_flow),\\n            user_id=nested_flow_rows.user_id,\\n            inputs=[],\\n            session_id=None,\\n            get_final_results_only=True,\\n        )\\n        return await tool._arun()\\n\\n    with _outer_scope(nested_flow_rows), pytest.raises(ModelProviderPolicyError):\\n        await _invoke()\\n\\n    probe.assert_not_called()\\n\\n\\n@pytest.mark.asyncio\\nasync def test_internal_a2a_builds_and_runs_under_target_scope(nested_flow_rows, project_policy, monkeypatch):\\n    \\\"\\\"\\\"Internal A2A cannot construct its target graph in the ambient caller domain.\\\"\\\"\\\"\\n    probe = MagicMock()\\n    _install_build_probe(monkeypatch, probe)\\n    project_policy.allowed_projects = {str(nested_flow_rows.outer_project)}\\n    published = Data(\\n        data={\\n            \\\"id\\\": str(nested_flow_rows.target_flow),\\n            \\\"name\\\": nested_flow_rows.target_name,\\n            \\\"updated_at\\\": None,\\n        }\\n    )\\n    component = A2AAgentComponent(\\n        mode=\\\"Internal\\\",\\n        agent_name_selected=nested_flow_rows.target_name,\\n        input_value=\\\"hello\\\",\\n    )\\n    component._user_id = UUID(nested_flow_rows.user_id)\\n    component._frontend_node_flow_id = str(nested_flow_rows.target_flow)\\n    selected = component._inputs[\\\"agent_name_selected\\\"]\\n    selected.options = [nested_flow_rows.target_name]\\n    selected.options_metadata = [{\\\"id\\\": str(nested_flow_rows.target_flow)}]\\n    monkeypatch.setattr(component, \\\"alist_a2a_agents_by_flow_folder\\\", AsyncMock(return_value=[published]))\\n\\n    with _outer_scope(nested_flow_rows), pytest.raises(ModelProviderPolicyError):\\n        await component.send_to_agent()\\n\\n    probe.assert_not_called()\\n\\n\\n@pytest.mark.asyncio\\nasync def test_cached_run_flow_reconstruction_uses_fresh_target_scope(nested_flow_rows, project_policy, monkeypatch):\\n    \\\"\\\"\\\"Shared Run Flow cache hydration must not build under the caller's domain.\\\"\\\"\\\"\\n    probe = MagicMock()\\n    _install_build_probe(monkeypatch, probe)\\n    project_policy.allowed_projects = {str(nested_flow_rows.outer_project)}\\n    updated_at = \\\"2026-08-27T00:00:00Z\\\"\\n    cache_entry = {\\n        \\\"graph_dump\\\": {\\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}},\\n        \\\"flow_id\\\": str(nested_flow_rows.target_flow),\\n        \\\"user_id\\\": nested_flow_rows.user_id,\\n        \\\"updated_at\\\": updated_at,\\n    }\\n    component = RunFlowBaseComponent()\\n    component._user_id = nested_flow_rows.user_id\\n    component.cache_flow = True\\n    component._shared_component_cache = MagicMock()\\n    component._shared_component_cache.get.return_value = cache_entry\\n\\n    with _outer_scope(nested_flow_rows), pytest.raises(ModelProviderPolicyError):\\n        await component.get_graph(\\n            flow_id_selected=str(nested_flow_rows.target_flow),\\n            updated_at=updated_at,\\n        )\\n\\n    probe.assert_not_called()\\n\\n\\n@pytest.mark.asyncio\\nasync def test_cached_graph_rechecks_revocation_on_every_execution(nested_flow_rows, project_policy):\\n    probe = MagicMock()\\n    graph = _ProviderGraph(flow_id=str(nested_flow_rows.target_flow), probe=probe)\\n    project_policy.allowed_projects = {\\n        str(nested_flow_rows.outer_project),\\n        str(nested_flow_rows.target_project),\\n    }\\n\\n    with _outer_scope(nested_flow_rows):\\n        await run_flow(graph=graph, flow_id=str(nested_flow_rows.target_flow), user_id=nested_flow_rows.user_id)\\n        project_policy.allowed_projects = {str(nested_flow_rows.outer_project)}\\n        with pytest.raises(ModelProviderPolicyError):\\n            await run_flow(graph=graph, flow_id=str(nested_flow_rows.target_flow), user_id=nested_flow_rows.user_id)\\n\\n    assert probe.call_count == 1\\n    assert project_policy.seen_projects[-1] == str(nested_flow_rows.target_project)\\n\\n\\n@pytest.mark.asyncio\\nasync def test_cached_graph_rechecks_target_project_after_move(nested_flow_rows, project_policy):\\n    probe = MagicMock()\\n    graph = _ProviderGraph(flow_id=str(nested_flow_rows.target_flow), probe=probe)\\n    project_policy.allowed_projects = {\\n        str(nested_flow_rows.outer_project),\\n        str(nested_flow_rows.target_project),\\n    }\\n\\n    with _outer_scope(nested_flow_rows):\\n        await run_flow(graph=graph, flow_id=str(nested_flow_rows.target_flow), user_id=nested_flow_rows.user_id)\\n        async with session_scope() as session:\\n            target = await session.get(Flow, nested_flow_rows.target_flow)\\n            target.folder_id = nested_flow_rows.moved_project\\n            target.workspace_id = nested_flow_rows.moved_workspace\\n            session.add(target)\\n        with pytest.raises(ModelProviderPolicyError):\\n            await run_flow(graph=graph, flow_id=str(nested_flow_rows.target_flow), user_id=nested_flow_rows.user_id)\\n\\n    assert probe.call_count == 1\\n    assert project_policy.seen_projects[-1] == str(nested_flow_rows.moved_project)\\n\\n\\n@pytest.mark.asyncio\\nasync def test_recursive_nested_scope_restores_parent_and_root(nested_flow_rows, project_policy):\\n    seen: list[tuple[str, str | None]] = []\\n\\n    def _project() -> str | None:\\n        context = current_model_provider_policy_context()\\n        value = context.attributes.get(\\\"project_id\\\") if context is not None else None\\n        return str(value) if value is not None else None\\n\\n    async def _inner():\\n        seen.append((\\\"inner\\\", _project()))\\n        return []\\n\\n    inner_graph = _ProviderGraph(\\n        flow_id=str(nested_flow_rows.recursive_flow),\\n        probe=MagicMock(),\\n        callback=_inner,\\n    )\\n\\n    async def _outer():\\n        seen.append((\\\"parent-before\\\", _project()))\\n        await run_flow(\\n            graph=inner_graph,\\n            flow_id=str(nested_flow_rows.recursive_flow),\\n            user_id=nested_flow_rows.user_id,\\n        )\\n        seen.append((\\\"parent-after\\\", _project()))\\n        return []\\n\\n    outer_graph = _ProviderGraph(\\n        flow_id=str(nested_flow_rows.target_flow),\\n        probe=MagicMock(),\\n        callback=_outer,\\n    )\\n    project_policy.allowed_projects = {\\n        str(nested_flow_rows.outer_project),\\n        str(nested_flow_rows.target_project),\\n        str(nested_flow_rows.moved_project),\\n    }\\n\\n    with _outer_scope(nested_flow_rows):\\n        await run_flow(\\n            graph=outer_graph,\\n            flow_id=str(nested_flow_rows.target_flow),\\n            user_id=nested_flow_rows.user_id,\\n        )\\n        seen.append((\\\"root\\\", _project()))\\n\\n    assert seen == [\\n        (\\\"parent-before\\\", str(nested_flow_rows.target_project)),\\n        (\\\"inner\\\", str(nested_flow_rows.moved_project)),\\n        (\\\"parent-after\\\", str(nested_flow_rows.target_project)),\\n        (\\\"root\\\", str(nested_flow_rows.outer_project)),\\n    ]\\n\\n\\n@pytest.mark.asyncio\\nasync def test_nested_scope_restores_parent_after_child_exception(nested_flow_rows, project_policy):\\n    error_message = \\\"child failed\\\"\\n\\n    async def _raise():\\n        context = current_model_provider_policy_context()\\n        assert str(context.attributes[\\\"project_id\\\"]) == str(nested_flow_rows.target_project)\\n        raise RuntimeError(error_message)\\n\\n    graph = _ProviderGraph(flow_id=str(nested_flow_rows.target_flow), probe=MagicMock(), callback=_raise)\\n    project_policy.allowed_projects = {str(nested_flow_rows.target_project)}\\n\\n    with _outer_scope(nested_flow_rows):\\n        with pytest.raises(RuntimeError, match=error_message):\\n            await run_flow(graph=graph, flow_id=str(nested_flow_rows.target_flow), user_id=nested_flow_rows.user_id)\\n        context = current_model_provider_policy_context()\\n        assert str(context.attributes[\\\"project_id\\\"]) == str(nested_flow_rows.outer_project)\\n\\n\\n@pytest.mark.asyncio\\nasync def test_concurrent_nested_runs_keep_target_scopes_isolated(nested_flow_rows, project_policy):\\n    ready = asyncio.Event()\\n    entered = 0\\n    seen: dict[str, list[str]] = {\\\"first\\\": [], \\\"second\\\": []}\\n\\n    def _callback(label, expected):\\n        async def _run():\\n            nonlocal entered\\n            context = current_model_provider_policy_context()\\n            seen[label].append(str(context.attributes[\\\"project_id\\\"]))\\n            entered += 1\\n            if entered == 2:\\n                ready.set()\\n            await asyncio.wait_for(ready.wait(), timeout=5)\\n            context = current_model_provider_policy_context()\\n            seen[label].append(str(context.attributes[\\\"project_id\\\"]))\\n            assert seen[label] == [str(expected), str(expected)]\\n            return []\\n\\n        return _run\\n\\n    first = _ProviderGraph(\\n        flow_id=str(nested_flow_rows.target_flow),\\n        probe=MagicMock(),\\n        callback=_callback(\\\"first\\\", nested_flow_rows.target_project),\\n    )\\n    second = _ProviderGraph(\\n        flow_id=str(nested_flow_rows.recursive_flow),\\n        probe=MagicMock(),\\n        callback=_callback(\\\"second\\\", nested_flow_rows.moved_project),\\n    )\\n    project_policy.allowed_projects = {\\n        str(nested_flow_rows.target_project),\\n        str(nested_flow_rows.moved_project),\\n    }\\n\\n    with _outer_scope(nested_flow_rows):\\n        await asyncio.gather(\\n            run_flow(graph=first, flow_id=str(nested_flow_rows.target_flow), user_id=nested_flow_rows.user_id),\\n            run_flow(graph=second, flow_id=str(nested_flow_rows.recursive_flow), user_id=nested_flow_rows.user_id),\\n        )\\n        context = current_model_provider_policy_context()\\n        assert str(context.attributes[\\\"project_id\\\"]) == str(nested_flow_rows.outer_project)\\n\\n\\n@pytest.mark.parametrize(\\\"flow_id\\\", [None, \\\"not-a-uuid\\\"])\\n@pytest.mark.asyncio\\nasync def test_prebuilt_graph_missing_or_invalid_target_fails_before_execution(\\n    flow_id, nested_flow_rows, project_policy\\n):\\n    probe = MagicMock()\\n    graph = _ProviderGraph(flow_id=flow_id, probe=probe)\\n    project_policy.allowed_projects = {str(nested_flow_rows.outer_project)}\\n\\n    with _outer_scope(nested_flow_rows), pytest.raises((ValueError, TypeError)):\\n        await run_flow(graph=graph, flow_id=flow_id, user_id=nested_flow_rows.user_id)\\n\\n    probe.assert_not_called()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/initial_setup/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/initial_setup/starter_projects/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/initial_setup/starter_projects/test_memory_chatbot.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"20e309ae1ad2402fd0bd8c6ac3058baa1c3f22185d4679b92473be640d485b76\",\"content\":\"import operator\\nfrom collections import deque\\nfrom typing import TYPE_CHECKING\\n\\nimport pytest\\nfrom lfx.components.helpers.memory import MemoryComponent\\nfrom lfx.components.input_output import ChatInput, ChatOutput\\nfrom lfx.components.models import LanguageModelComponent\\nfrom lfx.components.models_and_agents import PromptComponent\\nfrom lfx.components.processing.converter import TypeConverterComponent\\nfrom lfx.graph.graph.base import Graph\\nfrom lfx.graph.graph.constants import Finish\\n\\nif TYPE_CHECKING:\\n    from lfx.graph.graph.schema import GraphDump\\n\\n\\n@pytest.fixture\\ndef memory_chatbot_graph():\\n    session_id = \\\"test_session_id\\\"\\n    template = \\\"\\\"\\\"{context}\\n\\nUser: {user_message}\\nAI: \\\"\\\"\\\"\\n    memory_component = MemoryComponent(_id=\\\"chat_memory\\\")\\n    memory_component.set(session_id=session_id)\\n    chat_input = ChatInput(_id=\\\"chat_input\\\")\\n    type_converter = TypeConverterComponent(_id=\\\"type_converter\\\")\\n    type_converter.set(input_data=memory_component.retrieve_messages_dataframe)\\n    prompt_component = PromptComponent(_id=\\\"prompt\\\")\\n    prompt_component.set(\\n        template=template,\\n        user_message=chat_input.message_response,\\n        context=type_converter.convert_to_message,\\n    )\\n    language_model_component = LanguageModelComponent(_id=\\\"language_model\\\")\\n    language_model_component.set(\\n        input_value=prompt_component.build_prompt, max_tokens=100, temperature=0.1, api_key=\\\"test_api_key\\\"\\n    )\\n    language_model_component.set_on_output(name=\\\"text_output\\\", value=\\\"Mock response\\\", cache=True)\\n\\n    chat_output = ChatOutput(_id=\\\"chat_output\\\")\\n    chat_output.set(input_value=language_model_component.text_response)\\n\\n    graph = Graph(chat_input, chat_output)\\n    language_model_vertex = graph.get_vertex(\\\"language_model\\\")\\n    assert language_model_vertex.data[\\\"node\\\"][\\\"template\\\"][\\\"api_key\\\"][\\\"load_from_db\\\"] is False\\n    assert graph.in_degree_map == {\\n        \\\"chat_output\\\": 1,\\n        \\\"type_converter\\\": 1,\\n        \\\"prompt\\\": 2,\\n        \\\"language_model\\\": 1,\\n        \\\"chat_input\\\": 0,\\n        \\\"chat_memory\\\": 0,\\n    }\\n    return graph\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\ndef test_memory_chatbot(memory_chatbot_graph):\\n    # Now we run step by step\\n    expected_order = deque([\\\"chat_input\\\", \\\"chat_memory\\\", \\\"type_converter\\\", \\\"prompt\\\", \\\"language_model\\\", \\\"chat_output\\\"])\\n    assert memory_chatbot_graph.in_degree_map == {\\n        \\\"chat_output\\\": 1,\\n        \\\"type_converter\\\": 1,\\n        \\\"prompt\\\": 2,\\n        \\\"language_model\\\": 1,\\n        \\\"chat_input\\\": 0,\\n        \\\"chat_memory\\\": 0,\\n    }\\n    assert memory_chatbot_graph.vertices_layers == [[\\\"type_converter\\\"], [\\\"prompt\\\"], [\\\"language_model\\\"], [\\\"chat_output\\\"]]\\n    assert memory_chatbot_graph.first_layer == [\\\"chat_input\\\", \\\"chat_memory\\\"]\\n\\n    for step in expected_order:\\n        result = memory_chatbot_graph.step()\\n        if isinstance(result, Finish):\\n            break\\n\\n        assert step == result.vertex.id, (memory_chatbot_graph.in_degree_map, memory_chatbot_graph.vertices_layers)\\n\\n\\ndef test_memory_chatbot_dump_structure(memory_chatbot_graph: Graph):\\n    # Now we run step by step\\n    graph_dict = memory_chatbot_graph.dump(\\n        name=\\\"Memory Chatbot\\\", description=\\\"A memory chatbot\\\", endpoint_name=\\\"membot\\\"\\n    )\\n    assert isinstance(graph_dict, dict)\\n    # Test structure\\n    assert \\\"data\\\" in graph_dict\\n    assert \\\"is_component\\\" in graph_dict\\n\\n    data_dict = graph_dict[\\\"data\\\"]\\n    assert \\\"nodes\\\" in data_dict\\n    assert \\\"edges\\\" in data_dict\\n    assert \\\"description\\\" in graph_dict\\n    assert \\\"endpoint_name\\\" in graph_dict\\n\\n    # Test data\\n    nodes = data_dict[\\\"nodes\\\"]\\n    edges = data_dict[\\\"edges\\\"]\\n    description = graph_dict[\\\"description\\\"]\\n    endpoint_name = graph_dict[\\\"endpoint_name\\\"]\\n\\n    assert len(nodes) == 6\\n    assert len(edges) == 5\\n    assert description is not None\\n    assert endpoint_name is not None\\n\\n\\ndef test_memory_chatbot_dump_components_and_edges(memory_chatbot_graph: Graph):\\n    # Check all components and edges were dumped correctly\\n    graph_dict: GraphDump = memory_chatbot_graph.dump(\\n        name=\\\"Memory Chatbot\\\", description=\\\"A memory chatbot\\\", endpoint_name=\\\"membot\\\"\\n    )\\n\\n    data_dict = graph_dict[\\\"data\\\"]\\n    nodes = data_dict[\\\"nodes\\\"]\\n    edges = data_dict[\\\"edges\\\"]\\n\\n    # sort the nodes by id\\n    nodes = sorted(nodes, key=operator.itemgetter(\\\"id\\\"))\\n\\n    # Check each node\\n    assert nodes[0][\\\"data\\\"][\\\"type\\\"] == \\\"ChatInput\\\"\\n    assert nodes[0][\\\"id\\\"] == \\\"chat_input\\\"\\n\\n    assert nodes[1][\\\"data\\\"][\\\"type\\\"] == \\\"Memory\\\"\\n    assert nodes[1][\\\"id\\\"] == \\\"chat_memory\\\"\\n\\n    assert nodes[2][\\\"data\\\"][\\\"type\\\"] == \\\"ChatOutput\\\"\\n    assert nodes[2][\\\"id\\\"] == \\\"chat_output\\\"\\n\\n    assert nodes[3][\\\"data\\\"][\\\"type\\\"] == \\\"LanguageModelComponent\\\"\\n    assert nodes[3][\\\"id\\\"] == \\\"language_model\\\"\\n\\n    assert nodes[4][\\\"data\\\"][\\\"type\\\"] == \\\"Prompt Template\\\"\\n    assert nodes[4][\\\"id\\\"] == \\\"prompt\\\"\\n\\n    # Check edges\\n    expected_edges = [\\n        (\\\"chat_input\\\", \\\"prompt\\\"),\\n        (\\\"chat_memory\\\", \\\"type_converter\\\"),\\n        (\\\"type_converter\\\", \\\"prompt\\\"),\\n        (\\\"prompt\\\", \\\"language_model\\\"),\\n        (\\\"language_model\\\", \\\"chat_output\\\"),\\n    ]\\n\\n    assert len(edges) == len(expected_edges)\\n\\n    for edge in edges:\\n        source = edge[\\\"source\\\"]\\n        target = edge[\\\"target\\\"]\\n        assert (source, target) in expected_edges, edge\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/initial_setup/starter_projects/test_vector_store_rag.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"20207b51812d3b16bc69e260eb80302b585b5c6f7242026eb5a7af3d92bd3556\",\"content\":\"import copy\\nimport operator\\nfrom textwrap import dedent\\n\\nimport pytest\\nfrom lfx.components.data import FileComponent\\nfrom lfx.components.input_output import ChatInput, ChatOutput\\nfrom lfx.components.models import LanguageModelComponent\\nfrom lfx.components.models_and_agents import PromptComponent\\nfrom lfx.components.processing import ParserComponent\\nfrom lfx.components.processing.split_text import SplitTextComponent\\nfrom lfx.graph.graph.base import Graph\\nfrom lfx.graph.graph.constants import Finish\\nfrom lfx.schema import Data\\nfrom lfx.schema.dataframe import DataFrame\\nfrom lfx.schema.message import Message\\n\\n\\ndef _sample_dataframe() -> DataFrame:\\n    return DataFrame(data=[Data(text=\\\"This is a test file.\\\")])\\n\\n\\ndef _file_component(component_id: str) -> FileComponent:\\n    file_component = FileComponent(_id=component_id)\\n    file_component.set(path=\\\"test.txt\\\")\\n    file_component.set_on_output(name=\\\"message\\\", value=Message(text=\\\"This is a test file.\\\"), cache=True)\\n    return file_component\\n\\n\\n@pytest.fixture\\ndef ingestion_graph():\\n    file_component = _file_component(\\\"file-123\\\")\\n    text_splitter = SplitTextComponent(_id=\\\"text-splitter-123\\\")\\n    text_splitter.set(data_inputs=file_component.load_files_message)\\n    text_splitter.set_on_output(name=\\\"dataframe\\\", value=_sample_dataframe(), cache=True)\\n\\n    return Graph(file_component, text_splitter)\\n\\n\\n@pytest.fixture\\ndef rag_graph():\\n    chat_input = ChatInput(_id=\\\"chatinput-123\\\")\\n    chat_input.get_output(\\\"message\\\").value = Message(text=\\\"What is the meaning of life?\\\")\\n\\n    file_component = _file_component(\\\"rag-file-123\\\")\\n    text_splitter = SplitTextComponent(_id=\\\"rag-text-splitter-123\\\")\\n    text_splitter.set(data_inputs=file_component.load_files_message)\\n    text_splitter.set_on_output(name=\\\"dataframe\\\", value=_sample_dataframe(), cache=True)\\n\\n    parse_data = ParserComponent(_id=\\\"parse-data-123\\\")\\n    parse_data.set(input_data=text_splitter.split_text, mode=\\\"Stringify\\\")\\n    prompt_component = PromptComponent(_id=\\\"prompt-123\\\")\\n    prompt_component.set(\\n        template=dedent(\\\"\\\"\\\"Given the following context, answer the question.\\n                         Context:{context}\\n\\n                         Question: {question}\\n                         Answer:\\\"\\\"\\\"),\\n        context=parse_data.parse_combined_text,\\n        question=chat_input.message_response,\\n    )\\n\\n    language_model_component = LanguageModelComponent(_id=\\\"language-model-123\\\")\\n    language_model_component.set(input_value=prompt_component.build_prompt)\\n    language_model_component.set_on_output(name=\\\"text_output\\\", value=\\\"Hello, world!\\\", cache=True)\\n\\n    chat_output = ChatOutput(_id=\\\"chatoutput-123\\\")\\n    cha";
